INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1, 1, '2026-05-09 23:25:13', '2026-05-09 23:25:13', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'publish', 'open', 'open', '', 'hello-world', '', '', '2026-05-09 23:25:13', '2026-05-09 23:25:13', '', 0, 'http://tlt.local/?p=1', 0, 'post', '', 1);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (3, 1, '2026-05-09 23:25:13', '2026-05-09 23:25:13', '<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Our website address is: http://tlt.local.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n', 'Privacy Policy', '', 'draft', 'closed', 'open', '', 'privacy-policy', '', '', '2026-05-09 23:25:13', '2026-05-09 23:25:13', '', 0, 'http://tlt.local/?page_id=3', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (4, 1, '2026-05-09 23:29:15', '0000-00-00 00:00:00', '', 'Auto Draft', '', 'auto-draft', 'open', 'open', '', '', '', '', '2026-05-09 23:29:15', '0000-00-00 00:00:00', '', 0, 'http://tlt.local/?p=4', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1000, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '<p></p>', 'blog', '', 'publish', 'closed', 'closed', '', 'blog', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=page&amp;p=1000', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1001, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '\n<div class="body entry-content"><div id="item-688020b30db5006aef8b8c5e"><div><div><div><div>\n<div>\n<p>Directed by Trina Williamson</p><p>October 24 - November 9, 2025<br/>Thursday - Saturday at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, November 6th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, November 9th at 2:00pm</p><p>$30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under</p><p>Run Time: 2 hours and 30 minutes with one intermission</p><h3><strong><em>Dan Brown’s bestselling mystery brought to life on stage</em></strong></h3><p>In this thrilling play, based on Dan Brown’s bestselling novel, Professor Robert Langdon is summoned to the Louvre, where he becomes the center of a murder investigation. Cryptologist Sophie Neveu warns him that he is both suspect and investigator, setting them on a frantic race to clear his name and decode a labyrinthine puzzle before a shocking historical secret is lost forever. From Paris to London, they unravel mysteries hidden for centuries in this gripping adaptation. With danger at every turn, they must solve the clues before time runs out. This adaptation brings the novel’s twists and turns to life with thrilling intensity.</p><p>Recommended for Ages 12+ </p><p><strong><em>This production of THE DA VINCI CODE includes the following:<br/>Lighting effects including a strobe light, a hypoallergenic haze, gunshots, simulated violence and blood, minor language, depictions of self-harm, and brief mention of sexual situations.</em></strong></p><p>Featuring the talents of:<br/>Alan Peery as Robert Langdon<br/>Marisa-Clare Hissey as Sophie Neveu<br/>Scott C Brown as Sir Leigh Teabing<br/>Jacob Tice as Silas<br/>W. Scott Pinkston as Jacques Sauniére<br/>Scott Welborn as Bezu Fache<br/>Jim Mendoza as Rémy<br/>Carrie Sleeper-Bowers as Sister Sandrine/Marie<br/>Michael Haven as Vernet<br/>Abby Brown as Collet<br/>Kolten Tomlin as Philip</p><p><a href="/s/Da-Vinci-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-the-da-vinci-code-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-the-da-vinci-code-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n', 'THE DA VINCI CODE', 'Directed by Trina Williamson  October 24 - November 9, 2025 Thursday - Saturday at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, November 6th at 7:30pm  ASL Interpreted Performance: Sunday, November 9th at 2:00pm  $30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under', 'publish', 'closed', 'closed', '', 'the-da-vinci-code', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1001', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1002, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6880225f61e3497e7ecdd7cb"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York<br/>Musically Directed by Lindsay Delmarter<br/>Choreographed by Cassie Jo Fastabend</p><p>December 5 - December 28, 2025</p><p><span><strong><em>17 Performances!<br/></em></strong></span>Friday, December 5 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Saturday, December 6 at 7:30pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Sunday, December 7 at 2:00pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Thursday, December 11, 2025 at 7:30pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Friday, December 12 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Saturday, December 13 at 2:00pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Saturday, December 13 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Sunday, December 14 at 2:00pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Thursday, December 18 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Friday, December 19 at 7:30pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Saturday, December 20 at 2:00pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Saturday, December 20 at 7:30pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Sunday, December 21 at 2:00pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Friday, December 26 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Saturday, December 27 at 2:00pm (Nell Edlund as Matilda/Adia Watt as Lavender)<br/>Saturday, December 27 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender)<br/>Sunday, December 28 at 2:00pm (Nell Edlund as Matilda/Adia Watt as Lavender)</p><p>Pay What You Can: Thursday, December 18th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, December 28th at 2:00pm</p><p>$32 Adults - $30 Students/Seniors/Military - $25 Children 12 &amp; Under</p><p>Run Time: 2 hours and 30 minutes with one intermission</p><h3><strong><em>A magical, rebellious musical about a brilliant girl who stands up for herself and friends</em></strong></h3><p>Inspired by Roald Dahl’s genius, <em>Matilda The Musical</em> is a Tony Award-winning masterpiece celebrating childhood rebellion, imagination, and a girl’s fight for a better life. Matilda, an extraordinary young girl with intelligence, wit, and psychokinetic powers, is unloved by her cruel parents but admired by her kind teacher, Miss Honey. However, the tyrannical headmistress, Miss Trunchbull, rules the school with an iron fist—until Matilda’s courage and cleverness inspire her classmates to stand up for themselves. Filled with wit, whimsy, and unforgettable music, this musical is a joyful celebration of empowerment. With a heartwarming message, Matilda delights audiences of all ages.</p><p>Recommended for All Ages</p><p><strong><em>This production of Matilda the Musical includes the following: adults threatening physical and psychological violence against children, bright flashing lights, and some loud noises.</em></strong></p><p>Featuring the talents of:<br/>Hazel Barnett as Matilda Wormwood (See above schedule for performances)<br/>Nell Edlund as Matilda Wormwood (See above schedule for performances)<br/>Jacob Axelson as Miss Agatha Trunchbull<br/>Brittany Griffins as Miss Honey<br/>Ryan Coleman as Mr. Wormwood<br/>Stephanie Leeper as Mrs. Wormwood<br/>Caleb Osborne as Michael Wormwood<br/>Jess Beeler as Bruce<br/>Maya Kagochi as Lavender (See above schedule for performances)<br/>Adia Watt as Lavender (See above schedule for performances)<br/>Brittany D. Henderson as Mrs. Phelps<br/>Kyle Sinclair as The Escapologist &amp; Rudolpho<br/>Jordyn Konopaski as The Acrobat<br/>Grant McGee as The Doctor<br/>Molly Callender as The Children’s Entertainer<br/>Violet Brotherston as Ensemble<br/>Gemma Cohn as Ensemble<br/>Saoirse Forkner as Ensemble<br/>Lola Hallstrom as Ensemble<br/>Anna Horn as Ensemble<br/>Alana Kagochi as Ensemble<br/>Luke Leslie as Ensemble<br/>Claire Londyn as Ensemble<br/>Paige Norbjerg as Ensemble<br/>Sam Pedroni as Ensemble<br/>Frankie Reichl as Ensemble<br/>Maggie Savage as Ensemble<br/>Carlos Tice-Zelaya as Ensemble</p><p><a href="/s/Matilda-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-matilda-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-matilda-the-musical-tacoma-little-theatre" target="_blank">The Sound on Stage</a><br/><a href="https://olyarts.org/matilda-the-musical-at-tacoma-little-theatre/" target="_blank">OLY ARTS</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'MATILDA', 'Directed by Jennifer York Musically Directed by Lindsay Delmarter Choreographed by Cassie Jo Fastabend  December 5 - December 28, 2025     17 Performances!    Friday, December 5 at 7:30pm (Hazel Barnett as Matilda/Maya Kagochi as Lavender) Saturday, December 6 at 7:30pm (Nell Edlund as Matilda/Adia', 'publish', 'closed', 'closed', '', 'matilda', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1002', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1003, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-688024e4d59e531259e98d4c"><div><div><div><div>\n<div>\n<p>Directed by Kathy Pingel</p><p>January 23 - February 8, 2026<br/>Thursdays - Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><h2><strong>TIME CHANGE FOR SUNDAY, FEBRUARY 8, 2026<br/>This performance will now be <br/>at 12:00pm instead of 2:00pm.</strong></h2><p>Pay What You Can: Thursday, February 5th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, February 8th at 2:00pm</p><p>$30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under</p><p>Run Time: TBD</p><h3><strong>JOIN US ON OPENING NIGHT FOR. TALKBACK WITH THE PLAYWRIGHT, MICHAEL D. FOX, IMMEDIATELY FOLLOWING THE PERFORMANCE!</strong></h3><h3><strong><em>A thrilling adaptation of H. G. Wells\' classic sci-fi tale</em></strong></h3><p>Michael D. Fox’s adaptation of <span>The Time Machine</span> reimagines H.G. Wells’ classic sci-fi adventure, blending historical fiction with time travel. Helene Briggs, a scientist who has discovered a device capable of manipulating time, must protect it from those who seek to control its power. Alongside her granddaughter Skye, she embarks on a thrilling journey across the ages, encountering figures from history while uncovering the consequences of altering time. With adventure, suspense, and thought-provoking themes, this adaptation brings new life to a classic. It explores the dilemmas of altering history and the ripple effects of every decision.</p><p>Recommended for Ages 12+ </p><p>Featuring the talents of:<br/>Dana Galagan as Helene Briggs<br/>Simone Jolly as Skye Mason<br/>Reed Viydo as H.G. Wells<br/>Brett Hunt as Bradley Mason<br/>Derek Mesford as Gregory Whitman<br/>Tim Sherburn as Mr. Backman/Albert Einstein/Guard<br/>Meg Baker as Young Helene Briggs/Woman/Mother<br/>Ben Stahl as William Morris/Man/Telegram Man<br/>Hayden McManus as Mrs. Morris/Presenter</p><p><a href="/s/The-Time-Machine-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-the-time-machine-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-the-time-machine-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'THE TIME MACHINE', 'Directed by Kathy Pingel  January 23 - February 8, 2026 Thursdays - Saturdays at 7:30pm Sundays at 2:00pm   TIME CHANGE FOR SUNDAY, FEBRUARY 8, 2026 This performance will now be  at 12:00pm instead of 2:00pm.   Pay What You Can: Thursday, February 5th at 7:30pm  ASL Interpreted Performance: Sunday,', 'publish', 'closed', 'closed', '', 'the-time-machine', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1003', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1004, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-68802559e06e122c5fb8e3e7"><div><div><div><div>\n<div>\n<p>Directed by Maria-Tania Bandes B. Weingarden<br/>Musically Directed by Daniel Wolfert<br/>Choreographed by Ashley Roy-Simpson</p><p>March 6 - March 29, 2026<br/>Thursdays - Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, March 19th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, March 29th at 2:00pm</p><p>$32 Adults - $30 Students/Seniors/Military - $25 Children 12 &amp; Under</p><p>Run Time: Two hours and five minutes with a 15 minute intermission</p><h3>This production of <em>SPRING AWAKENING</em> includes the following: strong language, themes of child abuse, simulated sexual activity, simulated self-harm, suicide, a prop gun,  strobing light effects, and a hypoallergenic fog effect.  </h3><p><br/>PRODUCED IN PARTNERSHIP WITH UWT</p>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://www.canva.com/design/DAHBIlYQo88/KOHMn7qczniowZHGhDPKOA/view?utm_content=DAHBIlYQo88&amp;utm_campaign=designshare&amp;utm_medium=link2&amp;utm_source=uniquelinks&amp;utlId=hbab5b34116" target="_blank">\n      FIND OUT MORE ABOUT THE HISTORY OF SPRING AWAKENING\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<h3><strong><em>A bold, electrifying musical about love, repression, and the turbulence of youth</em></strong></h3><p>In 1891 Germany, where adults hold power, young Wendla questions life\'s mysteries while her mother silences her curiosity. Meanwhile, the fearless Melchior defends his anxious friend Moritz, who is overwhelmed by puberty and school pressures. As Melchior and Wendla discover a powerful but forbidden desire, Moritz\'s despair leads to tragedy, with the rigid school system blaming Melchior for his friend’s fate. When Wendla’s unexpected pregnancy is revealed, the young lovers confront a world unwilling to support them. With raw emotion and a powerful score, Spring Awakening captures the highs and lows of rebellion.</p><p>Recommended for Ages 14+ </p><p>Featuring the talents of:<br/>Macy Byrd as Wendla<br/>Ayo Alaka as Melchior<br/>Eliana-Marie Becerra Bandes as Martha<br/>Zym Edson as Moritz<br/>Annelise Martin as Thea<br/>Fisher Wapato as Hanschen<br/>Monique Otter-Johnson as Anna<br/>Ellian Kelly as Ernst<br/>Kiley Dollymore as Ilse<br/>Evan Dyck as Georg<br/>Russell Dunmire as Otto<br/>Loryestine Buentipo as Ensemble<br/>Em Castle as Ensemble (Thea &amp; Anna understudy)<br/>Phoenix Fassio as Ensemble<br/>Finn Henwood as Ensemble<br/>Alexandria Melville as Ensemble<br/>Erik Davis as Ensemble<br/>Naitiyah Prum as Ensemble<br/>Cordelia Seil as Ensemble (Hanschen &amp; Ernst understudy)<br/>Alexandria Smith as Ensemble (Wendla understudy)<br/>Beau Xzane as Ensemble (Otto &amp; Georg understudy)<br/>Naomi Blue Nieves Driver as Adult Woman<br/>Eric Strachan as Adult Man</p><p><a href="/s/Spring-Awakening-Program.pdf" target="_blank">PROGRAM</a><br/></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-spring-awakening-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.tacoma.uw.edu/news/spring-awakening" target="_blank">University of Washington Tacoma</a><br/><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-spring-awakening-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'SPRING AWAKENING', 'Directed by Maria-Tania Bandes B. Weingarden Musically Directed by Daniel Wolfert Choreographed by Ashley Roy-Simpson  March 6 - March 29, 2026 Thursdays - Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, March 19th at 7:30pm  ASL Interpreted Performance: Sunday, March 29th at 2:00', 'publish', 'closed', 'closed', '', 'spring-awakening', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1004', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1005, 1, '2026-05-09 16:14:21', '2026-05-09 16:14:21', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-68802633b4396a0fd366fb53"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/200478181" target="_blank">\n      CLICK HERE FOR TICKETS\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p>Directed by Jalen Penn</p><p>April 24 - May 10, 2026<br/>Thursdays - Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, May 7th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, May 10th at 2:00pm</p><p>$30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under</p><h3><strong>Join us for a talkback on Sunday, May 3rd and Friday, May 8h, immediately following the performance.  You don’t have to attend the performance to be a part of the talkback, just show up around 9:30pm!</strong></h3><h3>Run Time: Act One-51 minutes Act Two-45 minutes <em>(There will be a 15-minute intermission)</em></h3><h3><strong><em>A powerful reimagining of MLK’s final night, weaving history, humanity, and hope</em></strong></h3><p>After delivering his famous I\'ve Been to the Mountaintop speech, an exhausted Dr. Martin Luther King Jr. returns to his motel room, burdened by the weight of the civil rights movement. There, he encounters Camae, a mysterious hotel maid whose sharp wit and unexpected insights challenge his beliefs and legacy. As their conversation deepens, King is forced to confront his mortality and unfinished work. Blending realism with spiritual and surreal elements, The Mountaintop offers a human portrait of an iconic leader. A thought-provoking journey, this play redefines the man behind the movement.</p><p><strong><em>This proudction contains flashing lights, a hypoallergenic haze, a recorded gunshot, mature themes, strong language including use of an offensive racial slur, discussions of infidelity, violence, and racism.</em></strong></p><p>Recommended for Ages 14+ </p><p>Featuring the talents of:<br/>DuWayne Andrews, Jr. as Martin Luther King, Jr.<br/>Ibri Brooks as Camae</p>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="/s/The-Mountaintop-Dramaturgy.pdf" target="_blank">\n      THE MOUNTAINTOP DRAMATURGY\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p><br/></p><p><a href="/s/The-Mountaintop-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-the-mountaintop-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-the-mountaintop-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'THE MOUNTAINTOP', 'Directed by Jalen Penn  April 24 - May 10, 2026 Thursdays - Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 7th at 7:30pm  ASL Interpreted Performance: Sunday, May 10th at 2:00pm  $30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under   Join us for a talk', 'publish', 'closed', 'closed', '', 'the-mountaintop', '', '', '2026-05-09 16:14:21', '2026-05-09 16:14:21', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1005', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1006, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-688026890a7a01660ea01c61"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/200478182" target="_blank">\n      CLICK HERE FOR TICKETS\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p>Directed by Maria Valenzuela</p><p>June 5 - June 21, 2026<br/>Thursdays - Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, June 18th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, June 21st at 2:00pm</p><p>$30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under</p><p>Run Time: TBD</p><h3><strong><em>A lyrical and haunting exploration of memory, love, and the echoes of history</em></strong></h3><p>Nilo Cruz’s Sotto Voce is a poetic exploration of memory, loss, and the enduring power of love. Saquiel, a young Cuban man obsessed with the M.S. St. Louis—a ship of Jewish refugees turned away from American shores in 1939—seeks out Bemadette Kahn, an aging German-born writer who lost her lover in that tragic voyage. As they form an unconventional bond through phone calls and imagined conversations, Bemadette confronts long-buried grief. Through poetic language and magical realism, Sotto Voce intertwines past and present, exile and longing, and the lingering weight of history.</p><p>Featuring the talents of:<br/>Sharry O\'Hare as Bemadette Kahn<br/>John Pedro as Saquiel Rafaeli<br/>Valeria Sanchez-Jimenez as Lucila Pulpo</p><p>Recommended for Ages 12+ </p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-sotto-voce-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'SOTTO VOCE', 'Directed by Maria Valenzuela  June 5 - June 21, 2026 Thursdays - Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 18th at 7:30pm  ASL Interpreted Performance: Sunday, June 21st at 2:00pm  $30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under  Run Time: T', 'publish', 'closed', 'closed', '', 'sotto-voce', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1006', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1007, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-688026cd24d6aa647278d0b1"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/200478173" target="_blank">\n      CLICK HERE FOR TICKETS\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p>Directed by Micheal O’Hara</p><p>July 10 - July 26, 2026<br/>Thursdays - Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, July 23rd at 7:30pm</p><p>ASL Interpreted Performance: Sunday, July 26th at 2:00pm</p><p>$30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under</p><p>Run Time: TBD</p><h3><strong><em>An uproarious comedy of marital misadventures</em></strong></h3><p>In this raucous 1975 comedy, Ayckbourn brilliantly blends farce and claustrophobia, confining the drama to three bedrooms over one endless Saturday night. Manipulating time and space, he explores the ups and downs of four marriages—older Delia and Ernest, their son Trevor and his wife Susannah, young Malcolm and Kate, and Trevor’s ex-girlfriend Jan and her husband Nick. As complications and revelations mount, relationships teeter on the edge, yet each character finds their own way forward. This fast-paced comedy revels in the absurdity of human relationships and the chaos they bring.</p><p>Recommended for Ages 12+ </p><p>Featuring the talents of:<br/>Vince Brady as Ernest<br/>Sally Brady as Delia<br/>Don Anderson II as Nick<br/>Gina Grosso as Jan<br/>Bil Nowicki as Malcolm<br/>Athena Stirbis as Kate<br/>Brett Hunt as Trevor<br/>Jordyn Konopaski as Susannah</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-bedroom-farce-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'BEDROOM FARCE', 'Directed by Micheal O’Hara  July 10 - July 26, 2026 Thursdays - Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, July 23rd at 7:30pm  ASL Interpreted Performance: Sunday, July 26th at 2:00pm  $30 Adults - $28 Students/Seniors/Military - $23 Children 12 &amp; Under  Run Time: TB', 'publish', 'closed', 'closed', '', 'bedroom-farce', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1007', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1008, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-686cadbf285e714dff691da7"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/judy-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2025-2028</strong></p><p>BIO PENDING</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Judy Zerzan-Thul', 'BOARD TERM 2025-2028   BIO PENDING', 'publish', 'closed', 'closed', '', 'judy-zerzan-thul', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1008', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1009, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-686cad974c899a3ae12d9df8"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="480" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/placeholder-female1.jpg" width="480"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2025-2028</strong></p><p>Athena Renne Hitson, a Tacoma community member with more than 15 years of experience, brings expertise in event production, nonprofit fundraising, and community engagement to the Tacoma Little Theatre Board. </p><p>As the founder and lead producer of Peacock Events, she has organized large-scale corporate conferences, festivals, and inclusive community fundraisers that highlight creativity, collaboration, and local culture. </p><p>Her leadership has contributed to signature events like the Pearl Foundation of the Puget Sound’s 11th Annual Golf Tournament and 8th Annual Black Tie Gala in 2025, as well as Rainbow Center’s Tacoma Pride and the 2024 Gayla, where her strategic and relationship-focused approach consistently achieved record-breaking fundraising results. Driven by a passion for storytelling and the arts, Athena believes live performance can connect communities and amplify diverse voices. She is proud to bring her expertise in event strategy and community-centered vision to Tacoma Little Theatre, supporting its mission to make theatre accessible, inclusive, and artistically bold.</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Athena Hitson', 'BOARD TERM 2025-2028   Athena Renne Hitson, a Tacoma community member with more than 15 years of experience, brings expertise in event production, nonprofit fundraising, and community engagement to the Tacoma Little Theatre Board.   As the founder and lead producer of Peacock Events, she has organiz', 'publish', 'closed', 'closed', '', 'athena-hitson', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1009', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1010, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-686cad68a52584408129db83"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="480" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/placeholder-female1.jpg" width="480"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2025-2028</strong></p><p>BIO PENDING</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Libby Lindstrom', 'BOARD TERM 2025-2028   BIO PENDING', 'publish', 'closed', 'closed', '', 'libby-lindstrom', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1010', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1011, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-686c04f832a4607e27281876"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1200" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/lhm-headshot.jpg" width="800"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2025-2028</strong></p><p>Leah is a life-long Washingtonian, residing in the Puget sound area for over 30 years. She currently resides in Tacoma with her husband Michael and dog Nola, and enjoys visiting with their three adult children. She is an experienced public servant leader, passionate about improving lives for all people by advancing the highest quality, best value care and improved health care access. Leah currently serves as general counsel and chief strategist for Washington’s Health Benefit Exchange- the state’s insurance marketplace for over 250,000 Washington individuals and families that don’t have access to employer sponsored health insurance. She has led many public programs and innovations to improve access, reduce health disparities, and focus public resources on high value health care. Leah has no performance experience or talent, but she is a long time admirer of local theater and its capacity to connect community. She is honored and excited to serve on the Board of TLT and learn from and contribute to its resilience.  </p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Leah Hole-Marshall', 'BOARD TERM 2025-2028   Leah is a life-long Washingtonian, residing in the Puget sound area for over 30 years. She currently resides in Tacoma with her husband Michael and dog Nola, and enjoys visiting with their three adult children. She is an experienced public servant leader, passionate about impr', 'publish', 'closed', 'closed', '', 'leah-hole-marshall', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1011', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1012, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69dd6d9aada7b32eb255f44d"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1350" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/2026-summer-camp-announcement.png" width="1080"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69dd6d9aada7b32eb255f44d"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/index.php?sections=classes" target="_blank">\n      CLICK HERE TO ENROLL\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<h2><em>SESSION 1: Oliver jr.<br/></em>(Entering 1st grade through 6th grade)</h2><p>June 22 - July 18. Monday - Friday from 9 AM - 4 PM. <br/>Performances July 17 at 7:00 PM and July 19 at 2:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p><strong>About the Show:</strong></p><p>Consider yourself at home with <em>Oliver! JR., </em>the Broadway Junior version of Lionel Bart\'s classic musical based on Charles Dickens\' novel, <em>Oliver Twist</em>. The Tony and Olivier Award-winning show is one of the few musicals to win an Academy Award for Best Picture and is widely hailed as a true theatrical masterpiece by actors and audience members alike.</p><p>The streets of Victorian England come to life as Oliver, a malnourished orphan in a workhouse, becomes the neglected apprentice of an undertaker. Oliver escapes to London and finds acceptance amongst a group of petty thieves and pickpockets led by the elderly Fagin. When Oliver is captured for a theft that he did not commit, the benevolent victim, Mr. Brownlow takes him in. Fearing the safety of his hideout, Fagin employs the sinister Bill Sikes and the sympathetic Nancy to kidnap him back, threatening Oliver’s chances of discovering the true love of a family.</p><p><em>Oliver! JR. </em>is full of classic songs like "Consider Yourself", "Food Glorious Food", and "Oom-Pah-Pah", and perfectly showcases the talents of a large ensemble cast.<br/><br/></p><h2><em>Session 1: High School musical, jr.<br/></em>(Entering 7th grade through graduating senior)</h2><p>June 22 - July 18. Monday - Friday from 9 AM - 4 PM. <br/>Performances July 18 at 11:00 AM and at 5:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p> <strong>About the Show:</strong></p><p>Disney Channel\'s smash hit movie musical comes to life on your stage in <em>Disney’s High School Musical JR. </em>Now updated to the convenient binder version! Troy, Gabriella and the students of East High must deal with issues of love, friends and family while balancing their classes and extra curricular activities. The show’s infectious, danceable songs are sure to engage performers and audiences alike.</p><p>It’s the first day after winter break at East High. The Jocks, Brainiacs, Thespians and Skater Dudes all find their cliques. Basketball team captain and resident jock, Troy, discovers that the brainy Gabriella, a girl he met singing karaoke on his ski trip, has just enrolled at East High. The couple cause an upheaval when they decide to audition for the high school musical. Although many students resent the threat posed to the "status quo," Troy and Gabriella’s alliance might just open the door for others to shine as well.</p><p><em>Disney’s High School Musical JR. </em>is a great way to involve your school’s student-athletes. The show’s large cast size can easily be expanded to accommodate students in many grade levels, and its modern-day school setting, scenery and costumes are easily accessible.</p><h2><em>Session 2: TITLE TO BE ANNOUNCED<br/></em>(Entering 1st grade through 6th grade.)</h2><p>July 20 - August 15. Monday - Friday from 9 AM - 4 PM. <br/>Performances August 14 at 7:00 PM and August 15 at 2:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p> <strong>About the Show:</strong></p><p>This is a fun show that we are waiting on the official rights for.  It will be a show full of singing and dancing that you will love!<br/><br/></p><h2><em>SESSION 2: XANADU, Jr.</em> <br/>(Entering 7th grade through graduating senior)</h2><p>July 20 - August 15. Monday - Friday from 9 AM - 4 PM. <br/>Performances August 15 at 11:00 AM and  5:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p><strong>About the Show:</strong></p><p><em>Xanadu JR.</em> is inspired by the Tony Award-nominated Broadway musical and the Universal Pictures\' cult classic movie that starred Olivia Newton-John and Gene Kelly. <em>Xanadu JR.</em> is a moving, electrifying tale of endless fun that will keep audiences in stitches while the original, legendary chart-topping tunes lift them out of their seats.</p><p><em>Xanadu JR.</em> follows the journey of a magical and beautiful Greek muse, Kira, who descends from the heavens of Mt. Olympus to Venice Beach, California, on a quest to inspire a struggling artist, Sonny, to achieve the greatest artistic creation of all time – the first Roller Disco. (Hey, it\'s 1980!) But, when Kira falls into forbidden love with the mortal Sonny, her jealous sisters take advantage of the situation, and chaos abounds.</p><p>With a flexible cast size and lots of room for large disco dance numbers, <em>Xanadu JR.</em> will have your students rolling along (no skates required!)<br/></p><h2><strong>Scholarships:</strong></h2><p>Some scholarship funding is available. <a href="https://docs.google.com/forms/d/e/1FAIpQLSdEwJCTMI4GGxAXoBhfZhi1GrNk0DP5pFTkFFJd1qKc8TciDA/viewform?usp=header" target="_blank"><span>Click here to be directed to the application.</span></a><span> </span>Apply now, so we can process your application before enrollment opens!</p><p>*Note:  Please apply for a scholarship <strong>BEFORE</strong> trying to enroll your student.  Once approved, your scholarship will hold your students spot in the camp. </p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Depending on when the site is launched we may just need this info', 'Summer Camp is enrolling now!', 'publish', 'closed', 'closed', '', 'depending-on-when-the-site-is-launched-we-may-just-need-this-info', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1012', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1013, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6691611e2bbd8e03d71f68d3"><div><div><div><div>\n<div>\n<p>Directed by Brett Carr</p><p>September 6 - September 22, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, September 19th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, September 22nd at 2:00pm</p><p>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: 2 hours and 40 minutes with one intermission</p><p><strong>Sex, food, and money keep you laughing in this adapted classic Italian comedy</strong></p><p>Brighton, England. 1963. Change is in the air, and Francis Henshall is looking to make his mark. In search of work, he finds himself employed by small-time gangster Roscoe Crabbe. But Roscoe is really Rachel, posing as her own dead brother, herself in love with Stanley Stubbers who, in turn, becomes our hero’s other ‘guvnor’. Fighting a mounting sense of confusion, Francis goes out of his way to serve both bosses. But with the distractions of a feminist book keeper, a self-important actor, and select members of the criminal fraternity (not to mention his own mammoth appetite) to contend with, how long can he keep them apart? This hilarious comedy received 5-star reviews from every London newspaper and was the hit of the 2012 Broadway season. </p><p>Recommended for Ages 12+ </p><p><strong><em>This production contains strong adult language, sexual innuendo, comic violence, alcohol use, and crass British slang.</em></strong><br/><br/>Featuring:<br/>Blake York as Francis Henshall<br/>Guy Simpson III as Stanley Stubbers<br/>Cassie Fastabend as Rachel Crabbe<br/>Mikel Michener as Harry Dangle<br/>John Gonzales as Charlie "The Duck" Clench<br/>Mark Peterson as Lloyd Boateng<br/>Brittany Griffins as Pauline Clench<br/>Mason Quinn as Alan Dangle<br/>Gretchen Boyt as Dolly<br/>Micheal O\'Hara as Alfie<br/>Roger Iverson as Gareth<br/>Christina Ramirez-Michalk as Ensemble</p><p><a href="/s/One-Man-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-one-man-two-guvnorsposter-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-reviews-one-man-two-guvnors-tlt-run-for-your-wife-bct" target="_blank">The Sound on Stage</a><br/><a href="https://thesubtimes.com/2024/09/09/one-man-two-guvnors-at-tacoma-little-theatre/" target="_blank">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'ONE MAN, TWO GUVNORS', 'Directed by Brett Carr  September 6 - September 22, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, September 19th at 7:30pm  ASL Interpreted Performance: Sunday, September 22nd at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Unde', 'publish', 'closed', 'closed', '', 'one-man-two-guvnors', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1013', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1014, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6692fae14f8df346ce9efa6d"><div><div><div><div>\n<div>\n<h2>EXTENDED TO NOVEMBER 10TH!</h2><p>Directed by Frank Roberts</p><p>October 18 - November 10, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, October 31st at 7:30pm</p><p>ASL Interpreted Performance: Sunday, November 3rd at 2:00pm</p><p>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: 2 hours and 15 minutes with one intermission.</p><p><strong>The world’s most successful and longest-running play comes to the TLT stage</strong></p><p>After a murder, the guests and staff at Monkswell Manor find themselves stranded during a snowstorm. It soon becomes clear that the killer is among them, and the strangers grow increasingly suspicious of one another. A detective interrogates the suspects: the newlyweds running the house; a spinster with a curious background; an architect who seems better equipped to be a chef; a retired Army major; a strange man who claims his car has overturned in a drift; and a jurist who makes life miserable for everyone. When a second murder takes place, tensions and fears escalate. This record-breaking murder mystery features a brilliant surprise finish from Dame Agatha Christie, the foremost mystery writer of her time. </p><p>Recommended for Ages 7+ </p><p>This production contains the following: simulated violence, gun use, and mention of child abuse.</p><p>Featuring:<br/>Rachel Larkin as Mollie Ralston<br/>Jacob Tice as Giles Ralston<br/>Joe DeRosier as Christopher Wren<br/>Elizabeth Booth as Mrs. Boyle<br/>Tim Sherburn as Major Metcalf<br/>Jill Heinecke as Miss Casewell<br/>Scott Welborn as Mr. Paravicini<br/>Shaun Parker as Detective Sergeant Trotter</p><p><a href="/s/The-Mousetrap-Prorgram.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-the-mousetrap-poster-extended-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-the-mousetrap-tacoma-little-theatre" target="_blank">The Sound on Stage</a><br/><a href="https://thesubtimes.com/2024/10/24/the-mousetrap-by-agatha-christie/" target="_blank">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'THE MOUSETRAP', 'EXTENDED TO NOVEMBER 10TH!  Directed by Frank Roberts  October 18 - November 10, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, October 31st at 7:30pm  ASL Interpreted Performance: Sunday, November 3rd at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 C', 'publish', 'closed', 'closed', '', 'the-mousetrap', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1014', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1015, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6692fbc35f8fc01bd04cf2e1"><div><div><div><div>\n<div>\n<p>Directed by Melanie Gladstone<br/>Musically Directed by Shawna Avinger<br/>Choreographed by Heather Adams Arneson</p><p>December 6 - December 29, 2024<br/><br/><strong><em>18 Performances!<br/></em></strong>Friday, December 6, 2024 at 7:30pm<br/>Saturday, December 7, 2024 at 7:30pm<br/>Sunday, December 8, 2024 at 2:00pm<br/>Thursday, December 12, 2024 at 7:30pm<br/>Friday, December 13, 2024 at 7:30pm<br/>Saturday, December 14, 2024 at 2:00pm &amp; 7:30pm<br/>Sunday, December 15, 2024 at 2:00pm<br/>Thursday, December 19, 2024 at 7:30pm<br/>Friday, December 20, 2024 at 7:30pm<br/>Saturday, December 21, 2024 at 2:00pm &amp; 7:30pm<br/>Sunday, December 22, 2024 at 2:00pm<br/>Thursday, December 26, 2024 at 7:30pm<br/>Friday, December 27, 2024 at 7:30pm<br/>Saturday, December 28, 2024 at 2:00pm &amp; 7:30pm<br/>Sunday, December 29, 2024 at 2:00pm</p><p>Pay What You Can: Thursday, December 19th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, December 29th at 2:00pm</p><p>$31 Adults - $29 Students/Seniors/Military - $24 Children 12 &amp; Under</p><p>Run Time: 2 hours and 21 minutes with one intermission</p><p><strong>The perfect mix of audience-pleasing humor and heart for the holidays  </strong></p><p>Set in the little village of Anatevka, the story centers on Tevye, a poor milkman, and his five daughters. With the help of a colorful and tight-knit Jewish community, Tevye tries to protect his daughters and instill them with traditional values in the face of changing social mores and the growing anti-Semitism of Czarist Russia. Rich in historical and ethnic detail, <em>Fiddler on the Roof’s </em>universal theme of tradition cuts across barriers of race, class, nationality, and religion, leaving audiences crying tears of laughter, joy, and sadness. Winner of nine Tony® Awards when it debuted in 1964, <em>Fiddler </em>is a classic not to be missed! </p><p>Recommended for All Ages</p><p>Featuring:<br/>Jonathan Bill  as Tevye<br/>Rebecca Maiten as Golde<br/>Jed Slaughter as Lazar Wolf<br/>Libby Catalinich as Yente<br/>Annelise Martin as Tzeitel<br/>Juli Dowd as Hodel<br/>Nora Sidhu as Chava<br/>Oona Muller as Shprintze, Bielke: <em>12/6, 12/8, 12/12, 12/14, 12/19, 12/20, 12/21 (7:30pm), 12/22, 12/27, 12/28 (2pm), 12/29</em><br/>Vivian Pemoulie as Shprintze, Bielke: <em>12/6, 12/7, 12/12, 12/13, 12/14 (7:30pm). 12/15, 12/20, 12/21 (2pm), 12/22, 12/26, 12/28</em><br/>Maggie Savage as Shprintze, Bielke: <em>12/7, 12/8, 12/13, 12/14 (2pm), 12/15, 12/19, 12/21, 12/26, 12/27, 12/28 (7:30pm), 12/29)</em><br/>Ellian Kelly as Motel<br/>Aleks Aurelion as Perchik<br/>Craig Rock as The Constable<br/>Sam Barker as The Rabbi<br/>Erik Davis as Mendel<br/>Nick Fitzgerald as Avram<br/>Theron Danielson as Sasha<br/>Nigel Kelley as Fyedka<br/>Sean Vale as Nachum, Mordcha<br/>Mara Aveline as Fruma-Sarah<br/>Jennifer Torrence as Grandma Tzeitel<br/>Fletcher Kelley as Young Suitor: <em>12/6, 12/8, 12/12, 12/14, 12/19, 12/20, 12/21 (7:30pm), 12/22, 12/27, 12/28 (2pm), 12/29</em><br/>Otto Kelley as Young Suitor: <em>12/6, 12/7, 12/12, 12/13, 12/14 (7:30pm). 12/15, 12/20, 12/21 (2pm), 12/22, 12/26, 12/28</em><br/>Gavin Weston as Young Suitor: <em>12/7, 12/8, 12/13, 12/14 (2pm), 12/15, 12/19, 12/21, 12/26, 12/27, 12/28 (7:30pm), 12/29)</em><br/>Rayan Atallah as Ensemble<br/>Emily Castle as Ensemble<br/>Aven Kilmer as Ensemble<br/>Natasha Nelina as Ensemble<br/>Tyler Weston as Ensemble<br/>Selayna Rudolph as The Fiddler</p><p><a href="/s/Fiddler-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-fiddler-on-the-roof-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-fiddler-on-the-roof-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'FIDDLER ON THE ROOF', 'Directed by Melanie Gladstone Musically Directed by Shawna Avinger Choreographed by Heather Adams Arneson  December 6 - December 29, 2024    18 Performances!   Friday, December 6, 2024 at 7:30pm Saturday, December 7, 2024 at 7:30pm Sunday, December 8, 2024 at 2:00pm Thursday, December 12, 2024 at 7:', 'publish', 'closed', 'closed', '', 'fiddler-on-the-roof', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1015', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1016, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-672457bf9ff8d52967de37c9"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com" target="_blank">\n      CLICK HERE FOR TICKETS\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p>Monday, December 15, 2025 at 7:30pm<br/>Tuesday, December 16, 2025 at 7:30pm<br/><br/>All Seats $15.00</p><p>Run Time: 1 hour with no intermission</p><p><strong>Allen Fitzpatrick returns to TLT with his acclaimed solo show!</strong></p><p>In his 5th year of performing <em>A Christmas Carol,</em> Allen follows in the footsteps of Charles Dickens who, a few years after writing the novella, began public readings of it— which he continued to perform until the year of his death. Allen performs 26 characters, telling the entire story in one hour.</p><p>Allen has spent 50 years on Broadway and in professional theatre, working alongside such notables as Stephen Sondheim, Andrew Lloyd-Webber, Harold Prince, John Guare, and Marvin Hamlisch. He debuted on Broadway in <em>Les Miserables</em>; among his eight other Broadway credits are <em>Driving Miss Daisy</em> (with James Earl Jones), <em>The Scarlet Pimpernel, Damn Yankees</em> (with Jerry Lewis), and <em>42nd Street.</em> He was the stand-by for John Lithgow in <em>Sweet Smell of Success, </em>directed by Sir Nick Hytner.  Allen shared an Emmy Award for his contribution to <em>Passion: Live from Lincoln Center</em>, in which he appeared opposite Patti LuPone. He starred opposite Petula Clark in <em>Sunset Boulevard</em>, with Keith Michell in Lloyd-Webber\'s <em>Aspects of Love,</em> and with Marlo Thomas in <em>Six Degrees of Separation</em>. He has appeared in 28 productions at Seattle’s 5th Avenue Theatre, was featured in several Broadway national tours, and played a leading role in the premiere of <em>Whistle Down the Wind</em> directed by Hal Prince. He has appeared often on television.</p><p>Recommended for All Ages</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/2526-chirstmas-carol-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Put in don\'t know. However this is only because we are doing this show again in December and may want this to copy and paste content', 'BACK BY POPULAR DEMAND   Monday, December 15, 2025 at 7:30pm Tuesday, December 16, 2025 at 7:30pm  All Seats $15.00  Run Time: 1 hour with no intermission   Allen Fitzpatrick returns to TLT with his acclaimed solo show!   In his 5th year of performing  A Christmas Carol,  Allen follows in the footst', 'publish', 'closed', 'closed', '', 'put-in-dont-know-however-this-is-only-because-we-are-doing-this-show-again-in-december-and-may-want-this-to-copy-and-paste-content', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1016', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1017, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6692fe8dcf45560f0faab9fe"><div><div><div><div>\n<div>\n<p>Directed by Suzy Willhoft</p><p>January 24 - February 9, 2025<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, February 6th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, February 9th at 2:00pm</p><p>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><strong>The inventive Olivier and Tony®-Award-winning play  about the wonders of life</strong></p><p>15-year-old Christopher has an extraordinary brain: He is exceptional at mathematics but ill-equipped to interpret everyday life. He has never ventured alone beyond the end of his road, he detests being touched, and he distrusts strangers. Now it is seven minutes after midnight, and Christopher stands beside his neighbor’s dead dog, Wellington, who has been speared with a garden fork. Finding himself under suspicion, Christopher is determined to solve the mystery of who murdered Wellington, and he carefully records each fact of the crime. But his detective work takes him on a thrilling journey that upturns his world. </p><p>Recommended for Ages 12+ <br/>This production includes mature themes, such as domestic violence, bullying, and death of an animal; depictions of sensory overload and self injury; use of strong language, bright and flashing lights, as well as an intense soundscape.</p><p>Featuring the talents of:<br/>Brad Alemao as Christopher<br/>Levin Kim as Siobhan<br/>Mitchell Diehr as Ed<br/>Michelle Patrick as Judy<br/>Andrea Weston-Smart as Ensemble: Voice 1<br/>Grant McGee as Ensemble: Voice 2<br/>Evan Dyck as Ensemble: Voice 3<br/>Ludovico Capponi as Ensemble: Voice 4<br/>Alexandria Melville as Ensemble: Voice 5<br/>Shivani Ludwig as Ensemble: Voice 6</p><p><a href="/s/Curious-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-curious-incident-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://olyarts.org/2025/01/19/tacoma-little-theatre-presents-the-curious-incident-of-the-dog-in-the-night-time/" target="_blank">OLY ARTS</a></p><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-the-curious-incident-of-the-dog-in-the-night-time-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'THE CURIOUS INCIDENT OF THE DOG IN THE NIGHT-TIME', 'Directed by Suzy Willhoft  January 24 - February 9, 2025 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, February 6th at 7:30pm  ASL Interpreted Performance: Sunday, February 9th at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under', 'publish', 'closed', 'closed', '', 'the-curious-incident-of-the-dog-in-the-night-time', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1017', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1018, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6692ff8b595f29379b9ee529"><div><div><div><div>\n<div>\n<p>Directed by Maria-Tania Bandes B. Weingarden<br/>Choreographed by Marisela Fleites-Lear </p><p>March 7 - March 23, 2025<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, March 20th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, March 23rd at 2:00pm</p><p>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><strong>TLT and UWT bring Pulitzer Prize-winner, Nilo Cruz’s surrealist play to life</strong></p><p><em>Lorca in a Green Dress</em> pays homage to Federico García Lorca, writer of Gypsy Ballads, Mariana Pineda, and Play Without a Title.  Lorca was killed by fascist forces on August 19, 1936 in the opening days of the Spanish Civil War. Upon his death, the great Spanish poet arrives in the “Lorca Room” in purgatory where he learns he will be quarantined for the next 40 days. With dramatic and sensual flamenco flair, <em>Lorca in a Green Dress</em> is a spellbinding exploration of the life and death of Lorca. Five different actors portray aspects of the poet’s personality in a surrealistic landscape that questions what it means to die, to live, to create and to love.  </p><p>Recommended for Ages 12+ </p><p><strong><em>This production contains discussion of death, discussion of sexuality, adult language, homophobic slurs, recorded gunshots, and simulated violence.  There is a hypoallergenic haze used during the production.</em></strong>  </p><p>Featuring the talents of:<br/>Xander Pena Layden as Lorca with Blood<br/>Erik Davis-Lorca in a Green Dress<br/>Parker Nist as Lorca with Bicycle Pants<br/>Alexandria Smith as Lorca as a Woman<br/>Solace Fairbank asLorca in a White Suit<br/>Arwen Dewey as Flamenco Dancer (March 7, 9, 15, 20, 22)<br/>Marisela Fleites-Lear as Flamenco Dancer (March 8, 14, 16, 21, 23)<br/>Bailey Christie as The Guard<br/>Bil Nowicki as The General<br/>John Bussoletti as The Guitarist</p><p><a href="/s/Lorca-Program.pdf" target="_blank">PROGRAM</a></p><p><a href="/s/Lorca-Dramaturgy.pdf" target="_blank">DRAMATURGY INFORMATION</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-lorca-in-a-green-dress-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-lorca-in-a-green-dress-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'LORCA IN A GREEN DRESS', 'Directed by Maria-Tania Bandes B. Weingarden Choreographed by Marisela Fleites-Lear   March 7 - March 23, 2025 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, March 20th at 7:30pm  ASL Interpreted Performance: Sunday, March 23rd at 2:00pm  $29 Adults - $27 Students/Sen', 'publish', 'closed', 'closed', '', 'lorca-in-a-green-dress', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1018', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1019, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-669300490e82911538263ad2"><div><div><div><div>\n<div>\n<h2><strong>Bug is recommended for mature audiences only.  It contains graphic sexual content, ADULT LANGUAGE, FRONTAL nudity, simulated drug use, hypoallergenic fog, PTSD themes, non-nicotine/tobacco/tar based theatrical cigarettes, blood, and simulated violence.</strong> </h2><p>Directed by Blake R. York</p><p>April 25 - May 11, 2025<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, May 8th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, May 11th at 2:00pm</p><p>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><strong>The line between reality and delusion blurs in this thriller</strong></p><p>The play centers on the meeting between Agnes, a lonely divorcee, and Peter, a soft-spoken Gulf War drifter. Agnes stays at a seedy motel in hopes of avoiding her abusive ex-husband, Jerry. At first, she lets Peter sleep platonically on her floor, but not long after he is promoted to the bed. Matters become more complicated as Jerry eagerly returns expecting to resume their relationship. On top of that, there’s a hidden bug infestation that has both Agnes and Peter dealing with scathing welts and festering sores—which has Peter believing this is the result of experiments conducted on him during his stay at an Army hospital. Their fears soon escalate to paranoia, conspiracy theories and twisted psychological motives.   </p><p>Recommended for Ages 16+ </p><p>Featuring the talents of:<br/>Cassie Jo Fastabend as Agnes White<br/>Katrina Mattson as R.C.<br/>Bil Nowicki as Peter Evans<br/>Joshua Johnson as Jerry Goss<br/>Evan Collier as Dr. Sweet</p><p><a href="/s/Bug-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-bug-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2025/04/26/bug-the-latest-live-production-at-tacoma-little-theatre/" target="_blank">The Suburban Times</a></p><p><a href="https://olyarts.org/bug-at-tacoma-little-theatre/" target="_blank">OlyArts</a></p><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-bug-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'BUG', 'Bug is recommended for&nbsp;mature audiences only.&nbsp; It contains graphic sexual content, ADULT LANGUAGE, FRONTAL nudity, simulated drug use, hypoallergenic fog, PTSD themes, non-nicotine/tobacco/tar based theatrical cigarettes, blood, and simulated violence. &nbsp;  Directed by Blake', 'publish', 'closed', 'closed', '', 'bug', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1019', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1020, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-669300ba1d98f15cbbb7becf"><div><div><div><div>\n<div>\n<p>Directed by Chris Serface<br/>Co-Directed and Choreographed by Ashley Roy<br/>Musically Directed by Lindsay Delmarter</p><p>June 6 - June 29, 2025<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, June 19th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, June 29th at 2:00pm</p><p>$31 Adults - $29 Students/Seniors/Military - $24 Children 12 &amp; Under</p><p><strong>The greatest underdog story of our time, live on stage</strong></p><p>Rocky Balboa is a small-time Philadelphia boxer who is chosen to take on the reigning world heavyweight champion, Apollo Creed, when the undefeated fighter’s scheduled opponent is injured. While he diligently trains for the fight, Rocky begins a relationship with Adrian, a wallflower who is tired of being pushed around by her brother. As their love grows, they find their inner strength and bring out the best in each other. <em> Rocky </em>is a hard-hitting yet tender musical with music and lyrics by Tony®-winners and Academy Award® nominees Lynn Ahrens and Stephen Flaherty, and a book by multiple Tony®-winner Thomas Meehan, adapted from the acclaimed Oscar®-nominated screenplay by Sylvester Stallone.     </p><p>Recommended for Ages 13+ </p><p>Featuring the talents of:</p><p>Derek Mesford as Rocky Balboa<br/>Mariesa Genzale as Adrian Pennino<br/>DuWayne Andrews, Jr. as Apollo Creed<br/>Martin Goldsmith as Mickey Goldmill<br/>Stan Morrow as Paulie Pennino<br/>Christina Ramirez as Gloria<br/>Sophie Kashman as Angie (Adrian understudy)<br/>Annelise Martin as Joanne<br/>Ben Bott as Gazzo (Rocky understudy)<br/>Guy Simpson III as Jergens/Ensemble<br/>Charlie Stevens as Spider Rico/Apollo’s Manager/Ensemble<br/>Evan Dyck as Dipper Riley/Ensemble<br/>Erin Johnson as Linda/Apollo’s Girl/Ensemble (Joanne understudy)<br/>Marty Stiles as Watchman/Ensemble<br/>Joe DeRosier as Buddy/Ensemble (Paulie understudy)<br/>Kareyana Aguon as Apollo’s GIrl/Ensemble<br/>Em Castle as Ensemble<br/>Christine Choate as Shirley/Ensemble<br/>LaNita Hudson Walters as Apollo’s Girl/Ensemble (Gloria understudy)<br/>Anna Horn as Apollo’s Girl/Ensemble (Angie understudy)<br/>Ellie Jay McKee as Ensemble<br/>Madalyn Banouvong as Ensemble<br/>Ronni Satterwhite as Ensemble<br/>Ellian Kelly as Ensemble (Gazzo understudy)<br/>Will Morgan as Ensemble<br/>Teagan McMonagle as Ensemble</p><p><a href="/s/Rocky-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-rocky-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'ROCKY', 'Directed by Chris Serface Co-Directed and Choreographed by Ashley Roy Musically Directed by Lindsay Delmarter  June 6 - June 29, 2025 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 19th at 7:30pm  ASL Interpreted Performance: Sunday, June 29th at 2:00pm  $31 Adul', 'publish', 'closed', 'closed', '', 'rocky', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1020', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1021, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<p>Welcome to opening night of the Cornley University Drama Society’s newest production, where things are quickly going from bad to utterly disastrous. This 1920s whodunit has everything you never wanted in a show — an unconscious leading lady, a corpse that can’t play dead, and actors who trip over everything (including their lines).</p>', 'THE PLAY THAT GOES WRONG', 'Back by popular demand — get ready to laugh even more.', 'publish', 'closed', 'closed', '', 'the-play-that-goes-wrong', '', '', '2026-05-12 18:21:34', '2026-05-12 18:21:34', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1021', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1022, 1, '2026-05-09 16:14:22', '2026-05-09 16:14:22', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8a06b4919277092431098"><div><div><div><div>\n<div>\n<p>Directed by Chris Serface</p><p>October 20 - November 5, 2023<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, November 2, 2023 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, November 5, 2023 at 2:00pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act 1-70 minutes (15 minute intermission) Act 2-55 minutes</p><p><strong>Stephen King’s award-winning novel comes to life on the stage.</strong></p><p><em>Misery</em> follows successful romance novelist Paul Sheldon, who is rescued from a car crash by his “Number One Fan,” Annie Wilkes, and wakes up captive in her secluded home. While Paul is convalescing, Annie reads the manuscript to his newest novel and becomes enraged when she discovers the author has killed off her favorite character, Misery Chastain. Annie forces Paul to write a new “Misery” novel, and he quickly realizes Annie has no intention of letting him go anywhere. The irate Annie has Paul writing as if his life depends on it, and it does. <br/><br/>Recommended for Ages 13+ <br/><br/>Featuring:<br/>Deya Ozburn as Annie Wilkes<br/>Dylan Twiner as Paul Sheldon<br/>Andrew Fry as Buster</p><p><a href="/s/Misery-Program-Opening.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-misery-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2023/10/23/misery-at-tacoma-little-theatre-a-review/">The Suburban Times</a><br/><a href="https://olyarts.org/2023/10/23/misery-a-darkly-funny-thriller-for-the-halloween-season/?fbclid=IwAR2y6KizlQyFpsrbW5WWrrkaBz7XGDblTzt7UgE-vGg-ZmV1CfagdPO2Hdw">Oly Arts</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'MISERY', 'Directed by Chris Serface  October 20 - November 5, 2023 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, November 2, 2023 at 7:30pm  ASL Interpreted Performance: Sunday, November 5, 2023 at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp;', 'publish', 'closed', 'closed', '', 'misery', '', '', '2026-05-09 16:14:22', '2026-05-09 16:14:22', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1022', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1023, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8a1ef557bc14b0711a6f0"><div><div><div><div>\n<div>\n<p>Directed by Nick Fitzgerald<br/>Musical Direction by Debra Leach<br/>Choreography by Melanie Gladstone</p><p>December 8 - December 31, 2023<br/><br/><strong><em>16 Performances!<br/></em></strong>Friday, December 8, 2023 at 7:30pm<br/>Saturday, December 9, 2023 at 7:30pm<br/>Sunday, December 10, 2023 at 2:00pm<br/>Thursday, December 14, 2023 at 7:30pm<br/>Friday, December 15, 2023 at 7:30pm<br/>Saturday, December 16, 2023 at 7:30pm<br/>Sunday, December 17, 2023 at 2:00pm<br/>Thursday, December 21, 2023 at 7:30pm<br/>Friday, December 22, 2023 at 7:30pm<br/>Saturday, December 23, 2023 at 2:00pm<br/>Saturday, December 23, 2023 at 7:30pm<br/>Sunday, December 24, 2023 at 2:00pm<br/>Thursday, December 28, 2023 at 7:30pm<br/>Friday, December 29, 2023 at 7:30pm<br/>Saturday, December 30, 2023 at 7:30pm<br/>Sunday, December 31, 2023 at 2:00pm</p><p>Pay What You Can: Thursday, December 21, 2023 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, December 31, 2023 at 2:00pm<br/><br/>$31 Adults - $29 Students/Seniors/Military - $24 Children 12 &amp; Under</p><p>Run Time: Act 1-45 minutes (15 minute intermission) Act 2-30 minutes</p><p><strong>A holiday classic comes to the stage for the first time ever!</strong></p><p>The holiday classic soars off the screen in this musical adaptation of the beloved television special. Filled with holiday hits like “Rudolph the Red-Nosed Reindeer” and “A Holly Jolly Christmas,” <em>Rudolph the Red-Nosed Reindeer™</em> features all of your favorite characters including Santa and Mrs. Claus, Hermey the Elf, Bumble the Abominable Snow Monster, Clarice, Yukon Cornelius and, of course, Rudolph. It’s an adventure that teaches us that what makes you different can be what makes you special.<br/><br/>Recommended for All Ages <br/><br/>Featuring:<br/>Sam Barker as Sam<br/>Jennifer Torrence as Rudolph<br/>Luke Wenceslao as Hermey<br/>Katie Jones as Clairce<br/>Craig Rock as Santa Claus<br/>Madonna Hanna as Mrs. Claus<br/>Eric Strachan as Donner<br/>Libby Catalinich as Mrs. Donner<br/>Alan Plaster as Boss Elf/Coach Comet<br/>Stan Morrow as Yukon Cornelius<br/>Jaclyn Del Castillo as Reindeer/Misfit Toy/Elf<br/>Laura Hautala as Reindeer/Misfit Toy/Elf<br/>Miranda Manning as Reindeer/Misfit Toy/Elf<br/>Ailey Mills as Reindeer/Misfit Toy/Elf<br/>Selayna Rudolph as Reindeer/Misfit Toy/Elf<br/>Katie Shelledy as Reindeer/Misfit Toy/Elf<br/>Nora Sidhu as Reindeer/Misfit Toy/Elf<br/>Cayden Styron as Reindeer/Misfit Toy/Elf</p><p><a href="/s/Rudolph-Program.pdf"><strong>PROGRAM</strong></a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-rudolph-the-red-nosed-reindeer-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'RUDOLPH THE RED-NOSED REINDEER', 'Directed by Nick Fitzgerald Musical Direction by Debra Leach Choreography by Melanie Gladstone  December 8 - December 31, 2023    16 Performances!   Friday, December 8, 2023 at 7:30pm Saturday, December 9, 2023 at 7:30pm Sunday, December 10, 2023 at 2:00pm Thursday, December 14, 2023 at 7:30pm Frida', 'publish', 'closed', 'closed', '', 'rudolph-the-red-nosed-reindeer', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1023', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1024, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8a6631553e9456f9ce9e7"><div><div><div><div>\n<div>\n<p>Directed by Marilyn Bennett</p><p>January 26 - February 11, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, February 8, 2024 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, February 11, 2024 at 2:00pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act 1-58 minutes (15 minute intermission) Act 2-50 minutes</p><p><strong>The brand-new follow up to our 100th Season production of <em>A Doll’s House.</em></strong></p><p>In the final scene of Henrik Ibsen’s 1879 groundbreaking masterwork, Nora Helmer makes the shocking decision to leave her husband and children and begin a life on her own. This climactic event—when Nora slams the door on everything in her life—instantly propelled world drama into the modern age. In <em>A Doll’s House, Part 2</em>, many years have passed since Nora’s exit. Now, there’s a knock on that same door. Nora has returned. But why? And what will it mean for those she left behind?<br/><br/>Recommended for Ages 12+ <br/><br/><strong><em>This production contains Strong Adult Language and the use of Stage Blood.</em></strong><br/><br/>Featuring:<br/>Annie Katica Green as Nora<br/>Sean Neely as Torvald<br/>Dana Galagan as Anne Marie<br/>Brookelyne Peterson as Emmy</p><p><a href="/s/A-Dolls-House-Part-2-Program-Single-Page.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div><div class="website-component-block video-block"><div>\n<div class="intrinsic">\n\n<div class="video-caption-wrapper">\n<div class="video-caption">\n<p>Watch <em>A Doll’s House</em> from TLT’s 2018-2019 season</p>\n</div>\n</div>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-a-doll-s-house-part-2-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-a-dolls-house-part-2-tlt" target="_blank">The Sound on Stage</a><br/><a href="https://thesubtimes.com/2024/01/27/a-dolls-house-part-2-play-review-tacoma-little-theatre/" target="_blank">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'A DOLL\'S HOUSE, PART 2', 'Directed by Marilyn Bennett  January 26 - February 11, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, February 8, 2024 at 7:30pm  ASL Interpreted Performance: Sunday, February 11, 2024 at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &a', 'publish', 'closed', 'closed', '', 'a-dolls-house-part-2', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1024', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1025, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8a8e36f6fe633296a0a2a"><div><div><div><div>\n<div>\n<p>Directed by Maria-Tania Bandes B. Weingarden<br/>Musical Direction by Shawna Avinger<br/>Choreography by Eric Clausell</p><p>March 8 - March 31, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>ADDED PERFORMANCES<br/>Saturday, March 23, 2024 at 2:00pm<br/>Thursday, March 28, 2024 at 7:30pm<br/>Saturday, March 30, 2024 at 2:00pm</p><p>Pay What You Can: Thursday, March 21, 2024 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, March 31, 2024 at 2:00pm<br/><br/>$31 Adults - $29 Students/Seniors/Military - $24 Children 12 &amp; Under</p><p>Run Time: TBD</p><p><strong>TLT and the University of Washington-Tacoma Theatre Department team up again!</strong></p><p><em>Rent </em>follows a year in the life of a group of impoverished young artists and musicians struggling to survive and create in New York’s Lower East Side, under the shadow of HIV/AIDS. The physical and emotional complications of the disease pervade the lives of Roger, Mimi, Tom and Angel. Maureen deals with her chronic infidelity through performance art; her partner, Joanne, wonders if their relationship is worth the trouble. Benny has sold out his Bohemian ideals, and Mark, an aspiring filmmaker, feels like an outsider to life in general. How these young bohemians negotiate their dreams, loves and conflicts provides the narrative thread to this groundbreaking musical.<br/><br/>Recommended for Ages 13+ <br/><br/>Featuring:<br/>Zack Fowler as Mark Cohen<br/>Terence Mejos as Roger Davis<br/>Alison Rucker as Mimi Marquez<br/>Nick Ono as Benny Coffin III<br/>Emily Castle as Maureen Johnson<br/>Allison Fortenberry as Joanne Jefferson<br/>Darryin Cunningham as Tom Collins<br/>Erik Davis as Angel Dumott Schunard<br/>Camren Bleiler as Ensemble<br/>Araquin Boome as Ensemble<br/>Christine Choate as Ensemble<br/>Kiley Dollymore as Ensemble<br/>Christine Dove as Ensemble<br/>Katie Jones as Ensemble<br/>Kyle Laird as Ensemble<br/>Kyle Murphy as Ensemble<br/>Finn Henwood as Ensemble<br/>Eric Strachan as Ensemble<br/>Jada Williams as Ensemble</p><p><a href="/s/Rent-Program-Single-Page.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-rent-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-rent-tlt" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'RENT', 'Directed by Maria-Tania Bandes B. Weingarden Musical Direction by Shawna Avinger Choreography by Eric Clausell  March 8 - March 31, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  ADDED PERFORMANCES Saturday, March 23, 2024 at 2:00pm Thursday, March 28, 2024 at 7:30pm Saturday, March 30, 202', 'publish', 'closed', 'closed', '', 'rent', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1025', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1026, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6685928d104760460f685270"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/kay-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2024-2027</strong></p><p>BIO PENDING</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Kay Meier', 'BOARD TERM 2024-2027   BIO PENDING', 'publish', 'closed', 'closed', '', 'kay-meier', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1026', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1027, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-6685921dbd029c65418a6ab1"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/trevor-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2024-2027</strong></p><p>Trevor (He/Him) is currently serving his first year on the Board of Directors at Tacoma Little Theatre, driven by a profound passion for theatre and business. </p><p>Originally moving to Tacoma to attend the University of Washington Tacoma (UWT) to focus on academics, Dr. Maria-Tania reignited his enthusiasm for acting and the arts at the end of his freshman year. Since then, he has actively participated in numerous productions, both as an actor and on the production team, at UWT, TLT, and Dukesbay Productions. He is eager to explore more theater opportunities in the South Sound area.</p><p>While studying at UWT, Trevor is also the Director of Operations of the Husky Success Series as well as a Student Advising Mentor within the University Academic Advising office on campus. Trevor is passionate about expanding the partnership between UWT Theatre and TLT. He believes that by strengthening this collaboration, we can significantly contribute to the growth of theater in Tacoma, by providing students with enhanced opportunities for practical experience and professional growth.</p><p>Trevor is also deeply committed to promoting Diversity, Equity, and Inclusion (DEl) in all his endeavors. He recognizes the importance of creating inclusive spaces where diverse voices can be heard and valued. Through his work at TLT and UWT, Trevor aims to foster environments that champion equity and embrace diversity, ensuring that everyone has the opportunity to thrive in the theatre community.</p><p>Looking ahead, Trevor wishes to pursue an MFA in theatre management, leveraging his hands-on experience at TLT to bridge theoretical knowledge with practical application in the dynamic field of theatre management.</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Trevor Owens', 'BOARD TERM 2024-2027   Trevor (He/Him) is currently serving his first year on the Board of Directors at Tacoma Little Theatre, driven by a profound passion for theatre and business.&nbsp;  Originally moving to Tacoma to attend the University of Washington Tacoma (UWT) to focus on academics, Dr.', 'publish', 'closed', 'closed', '', 'trevor-owens', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_team&amp;p=1027', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1028, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8a970bce6592b8a10f914"><div><div><div><div>\n<div>\n<p>Directed by Rick Hornor</p><p>April 26 - May 12, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, May 9, 2024 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, May 12, 2024 at 2:00pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act 1-55 minutes (15 minute intermission) Act 2-55 minutes</p><p><strong>Welcome to Almost, Maine.  It’s love. But not quite.</strong></p><p>Welcome to Almost, Maine, a town that’s so far north, it’s almost not in the United States—it’s almost in Canada. And it almost doesn’t exist. Because its residents never got around to getting organized. So it’s just…Almost.  One cold, clear Friday night in the middle of winter, while the northern lights hover in the sky above, Almost’s residents find themselves falling in and out of love in the strangest ways. Knees are bruised. Hearts are broken. Love is lost, found, and confounded. And life for the people of Almost, Maine will never be the same.<br/><br/>Recommended for Ages 13+ <br/><br/>Featuring:<br/>K Cryer as Man 1<br/>Rachel Blackwelder Gardner as Woman 1<br/>Joshua Olver as Man 2<br/>Brookelyne Peterson as Woman 2</p><p><a href="/s/Almost-Maine-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-almost-maine-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2024/04/26/almost-maine-review-tacoma-little-theatre/" target="_blank">The Suburban Times</a><br/><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-almost-maine-tacoma-little-theatre" target="_blank">The Sound on Stage</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'ALMOST, MAINE', 'Directed by Rick Hornor  April 26 - May 12, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 9, 2024 at 7:30pm  ASL Interpreted Performance: Sunday, May 12, 2024 at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under  Run Time:', 'publish', 'closed', 'closed', '', 'almost-maine', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1028', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1029, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64a8aa066dd6990137b86816"><div><div><div><div>\n<div>\n<p>Directed by Michelle Blackmon</p><p>June 7 - June 23, 2024<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Pay What You Can: Thursday, June 20, 2024 at 7:30pm</p><p>ASL Interpreted Performance: Sunday, June 23, 2024 at 2:00pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act 1-44 minutes (15 minute intermission) Act 2-52 minutes</p><p><strong>A joyful celebration of survival.</strong></p><p>Based on her memoir of the same title, Dr. Endesha Ida Mae Holland recounts her 20 year journey from humble beginnings in Greenwood, Mississippi, during the Jim Crow era, her civil rights activism, achieving her Ph.D. at the University of Minnesota and celebrating her success as a Pulitzer-Prize nominated playwright. Experience a story of triumph in the face of extreme adversity that expertly weaves through the trials and tribulations of Dr. Holland’s life relayed through the bodies and voices of only three actors, all in tribute to one of America’s unsung heroes.<br/><br/>Recommended for Ages 16+ <br/><br/>Featuring:<br/>Sonia Alexis<br/>Whitney Crawford<br/>Canae Machelle Gray</p><p><a href="/s/Delta-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-from-the-mississippi-delta-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thesoundonstage.org/stage-reviews/stage-review-from-the-mississippi-delta-tacoma-little-theatre" target="_blank">The Sound on Stage</a><br/><a href="https://olyarts.org/2024/06/12/tacoma-little-theatre-closes-105th-season-with-lively-performance-of-from-the-mississippi-delta/" target="_blank">OlyArts</a><br/><a href="https://thesubtimes.com/2024/06/10/from-the-mississipp-live-theatre-production/" target="_blank">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'FROM THE MISSISSIPPI DELTA', 'Directed by Michelle Blackmon  June 7 - June 23, 2024 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 20, 2024 at 7:30pm  ASL Interpreted Performance: Sunday, June 23, 2024 at 2:00pm  $29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under  Ru', 'publish', 'closed', 'closed', '', 'from-the-mississippi-delta', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1029', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1030, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69fa4c25fd533f4af513b70a"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1080" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/orange-and-peach-simple-now-hiring-announcement-instagram-post.png" width="1080"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69fa4c25fd533f4af513b70a"><div><div><div><div>\n<div>\n<p>Tacoma Little Theatre is seeking designers for our 2026-2027 season. </p><p>We are seeking collaborative designers with a passion for the arts and their craft. The following design positions are available:</p><ul><li><p>Stage Managers</p></li><li><p>Resident Properties Designer</p></li><li><p>Resident Sound Designer</p></li><li><p>Show Costume Designer</p></li><li><p>Scenic Artist Apprentice</p></li></ul><p>At TLT, we believe theatre is a space for connection, reflection, and community storytelling. We are committed to producing work that is artistically bold, inclusive, and reflective of the diverse voices that make up our region. We strongly encourage designers of all backgrounds, identities, and experience levels to apply. </p><h2><span><strong>PRODUCTIONS</strong></span></h2><p><strong>THE OUTSIDER<br/>BY PAUL SLADE SMITH<br/>August 28-September 13, 2026</strong><br/>Ned Newley doesn’t even want to be governor. He’s terrified of public speaking, and his poll numbers are impressively bad. To his ever-supportive Chief of Staff, Ned seems destined to fail. But political consultant Arthur Vance sees things differently: Ned might be the worst candidate to ever run for office. Unless the public is looking for the worst candidate to ever run for office.  A timely and hilarious comedy that skewers politics and celebrates democracy.</p><p><strong>ARSENIC AND OLD LACE<br/>BY JOSEPH KESSERLING<br/>October 16-November 1, 2026</strong><br/>Drama critic Mortimer Brewster’s engagement announcement is upended when he discovers a corpse in his elderly aunts’ window seat. Mortimer rushes to tell Abby and Martha before they stumble upon the body themselves, only to learn that the two women aren’t just aware of the dead man in their parlor, they killed him! Between his aunts’ penchant for poisoning wine, a brother who thinks he’s Teddy Roosevelt, and another brother using plastic surgery to hide from the police – not to mention Mortimer’s own hesitancy about marriage – it’ll be a miracle if Mortimer makes it to his wedding. </p><p><strong>HALLMARKED<br/>BY MICHAEL D. FOX<br/>December 4-27, 2026</strong><br/>It seems everyone on the planet is obsessed with Hallmark movies. Everyone except Julie. She had her heart stomped on once and it will not happen again. No way. No how. Not even in Idyllic, Vermont. She refuses to be \'Hallmarked\'! Oh, no! Who\'s the guy in the plaid flannel? Packed with fabulous new pop songs, loads of laughter, and heartwarming delight, Hallmarked is a rom-com fever dream for those who swoon over the movies and for those who love roasting the people who do.</p><p><strong>DOT<br/>BY COLMAN DOMINGO<br/>February 5-21, 2027</strong><br/>The holidays are always a wild family affair at the Shealy house: But this year, Dotty and her three grown children gather with more than exchanging presents on their minds. As Dotty struggles to hold on to her memory, her children must fight to balance care for their mother and care for themselves. This twisted and hilarious new play grapples unflinchingly with aging parents, midlife crises, and the heart of a West Philly neighborhood.</p><p><strong>URINETOWN<br/>BY GREG KOTIS<br/>March 26-April 18, 2027</strong><br/>In this side-splitting satire, the young hero Bobby Strong leads his community in a fight against oppression. Set in a dystopian world where water is scarce and “Hope” is even scarcer, all citizens must now pay a fee for “The Privilege to Pee” at one of the public facilities controlled by a selfish tycoon, and monitored by authorities like Officer Lockstock. The citizens can only hold it in so much longer, and soon the poorest, filthiest of these facilities, run by the formidable Penelope Pennywise, becomes a “number one” site for major change.</p><p><strong>THE IMPORTANCE OF BEING EARNEST (UWT Partner Project)<br/>BY OSCAR WILDE<br/>May 21-June 6, 2027</strong></p><p>Being sensible can be excessively boring. At least Jack thinks so. While assuming the role of dutiful guardian in the country, he lets loose in town under a false identity. Meanwhile, his friend Algernon takes on a similar facade. Unfortunately, living a double life has its drawbacks, especially when it comes to love. Hoping to impress two eligible ladies, the gentlemen find themselves caught in a web of lies they must carefully navigate.</p><p><strong>THE PLAY THAT GOES WRONG<br/>BY HENRY LEWIS, JONATHAN SAYER &amp; HENRY SHIELDS<br/>July 9-July 25, 2027</strong></p><p>Welcome to opening night of the Cornley University Drama Society’s newest production, The Murder at Haversham Manor, where things are quickly going from bad to utterly disastrous. This 1920s whodunit has everything you never wanted in a show—an unconscious leading lady, a corpse that can’t play dead, and actors who trip over everything (including their lines). Nevertheless, the accident-prone thespians battle against all odds to make it through to their final curtain call, with hilarious consequences! Part Monty Python, part Sherlock Holmes, this Olivier Award–winning comedy is a global phenomenon that’s guaranteed to leave you aching with laughter!</p><h2><span><strong>COMPENSATION</strong></span></h2><p>Honorariums range in amounts from $600.00-$1400.00 per show.</p><h2><span><strong>HOW TO APPLY</strong></span></h2><p>If you are interested, please submit a current resume, and a letter of interest with the show(s) you are applying for to <a href="mailto:jobs@tacomalittletheatre.com?subject=2026-2027%20Director%20Search" target="_blank">jobs@tacomalittletheatre.com</a> or click the button below. You may apply for more than one production in your email. Letters will be reviewed on a rolling basis and positions filled by May 31, 2026.</p>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="mailto:jobs@tacomalittletheatre.com?subject=2026-2027%20Director%20Search" target="_blank">\n      SUBMIT EMAIL\n    </a>\n</div>\n\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'NOW HIRING-PRODUCTION TEAM MEMBERS FOR 2026-2027', 'TLT is currently accepting applications for production team members for 2026-2027!', 'publish', 'closed', 'closed', '', 'now-hiring-production-team-members-for-2026-2027', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1030', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1031, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc96c25f29d4033678e847"><div><div><div><div>\n<div>\n<p>Directed by Deanna Martinez</p><p>September 16 - September 25, 2022<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>SPECIAL ADDED PERFORMANCES<br/>Saturday, September 24, 2022 at 2:00pm<br/>Sunday, September 25, 2022 at 7:00pm</p><p>Pay What You Can: Thursday, September 22nd at 7:30pm</p><p>ASL Interpreted Performance: Sunday, September 25, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-60 minutes (15 minute intermission) Act 2-45 minutes</p><p><strong>With sharp witty banter and memorable one-liners, Steel Magnolias returns to TLT.</strong></p><p>Truvy’s salon is Chinquapin, Louisiana’s go-to place for a beauty fix with a hearty side of gossip. Along with her overeager assistant Annelle, Truvy pampers her small-town clients with hairdos, manicures, and all kinds of unsolicited advice. Anybody who’s anybody is a regular: There’s the doting M’Lynn and her soon-to-be-married daughter Shelby; the moody Ouiser; and the well-to-do widow Clairee. Through witty banter and wisecracks, this hodgepodge group of women form friendships as strong as steel, which they are forced to lean on when tragedy strikes.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Janice Williams as Truvy<br/>Samantha Jane Lobberegt as Annelle<br/>Laurice Roberts as Clairee<br/>Aliyah Shines as Shelby<br/>Shelleigh-Mairi Ferguson as M’Lynn<br/>Stephanie Leeper as Ouiser</p><p><a href="/s/Steel-Mags-Program.pdf" target="_blank"><strong>PROGRAM</strong></a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/steel-magnolias-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Steel Magnolias', 'Directed by Deanna Martinez  September 16 - September 25, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  SPECIAL ADDED PERFORMANCES Saturday, September 24, 2022 at 2:00pm Sunday, September 25, 2022 at 7:00pm  Pay What You Can: Thursday, September 22nd at 7:30pm  ASL Interpreted Performance:', 'publish', 'closed', 'closed', '', 'steel-magnolias', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1031', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1032, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc988318e75e2396b550e5"><div><div><div><div>\n<div>\n<p>Directed by Melanie Gladstone</p><p>October 21 - November 6, 2022<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, November 3rd at 7:30pm</p><p>ASL Interpreted Performance: Sunday, November 6, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-60 minutes (15 minute intermission) Act 2-50 minutes</p><p><strong>Eight suspects, one thrilling ride with this new adaptation by Ken Ludwig!</strong></p><p>Board the exotic and mysterious Orient Express as it takes off into the opulence and grandeur of the 1930s. Just after midnight, a snowdrift stops the Orient Express in its tracks. The luxurious train is surprisingly full for the time of year, but by the morning, it is one passenger fewer. An American tycoon lies dead in his compartment, his door locked from the inside. Isolated and with a killer in their midst, the passengers rely on detective Hercule Poirot to identify the murderer – in case they decide to strike again. Join Poirot as he battles the clock to figure out “whodunit” in this sleek, stylish, and surprisingly comedic murder mystery.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Craig Rock as Hercule Poirot<br/>Jacob Tice as Monsieur Bouc<br/>Andrea Gordon as Mary Debenham<br/>Ton Williams as Hector Macqueen<br/>Alan Plaster as Michel the Conductor<br/>Rosalie Hilburn as Princess Dragomiroff<br/>Marisa-Clare Hissey as Greta Ohlsson<br/>Canae Machelle Gray as Countess Andrenyi<br/>Jenifer Gillis Rifenbery as Helen Hubbard<br/>Brandon Fair as Colonel Arbuthnot<br/>Josh Johnson as Samuel Ratchett (Understudy Poirot/Michel/Colonel)<br/>Josie DeRosier as Head Waiter (Understudy Macqueen/Bouc)<br/>Haylee Gregory as Understudy Princess/Helen<br/>Jean-Michele Gregory as Understudy Greta/Countess/Mary</p><p><a href="/s/Murder-on-the-Orient-Express-Program.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/murder-on-the-orient-express-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2022/10/24/murder-on-the-orient-express-a-tacoma-little-theatre-review/">The Suburban Times</a></p><p><a href="https://www.heilmanandhaver.com/film-and-stage-reviews/Murder-Orient-TLT">Heilman &amp; Haver</a></p><p><a href="https://www.showsiveseen.com/murder-on-the-orient-express-play-tacoma-little-theatre/">Shows I’ve Seen</a></p><p><a href="https://www.dailyrecordnews.com/all_access/on-the-aisle-murder-on-the-orient-express-a-matter-of-adaptation/article_253ed63e-53cc-11ed-8f75-2b3cffdfd542.html">The Daily Record</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Murder on the Orient Express', 'Directed by Melanie Gladstone  October 21 - November 6, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, November 3rd at 7:30pm  ASL Interpreted Performance: Sunday, November 6, 2022 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp;', 'publish', 'closed', 'closed', '', 'murder-on-the-orient-express', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1032', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1033, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc997b37f118579343f48c"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York</p><p>December 2 - December 24, 2022<br/><br/><strong><em>18 Performances!</em></strong><br/>Friday, December 2, 2022 at 7:30pm<br/>Saturday, December 3, 2022 at 7:30pm<br/>Sunday, December 4, 2022 at 2:00pm<br/>Thursday, December 8, 2022 at 7:30pm<br/>Friday, December 9, 2022 at 7:30pm<br/>Saturday, December 10, 2022 at 2:00pm<br/>Saturday, December 10, 2022 at 7:30pm<br/>Sunday, December 11, 2022 at 2:00pm<br/>Thursday, December 15, 2022 at 7:30pm<br/>Friday, December 16, 2022 at 7:30pm<br/>Saturday, December 17, 2022 at 2:00pm<br/>Saturday, December 17, 2022 at 7:30pm<br/>Sunday, December 18, 2022 at 2:00pm<br/>Tuesday, December 20, 2022 at 7:30pm<br/>Wednesday, December 21, 2022 at 7:30pm<br/>Thursday, December 22, 2022 at 7:30pm<br/>Friday, December 23, 2022 at 7:30pm<br/>Saturday, December 24, 2022 at 2:00pm<br/><br/>Pay What You Can: Thursday, December 22nd at 7:30pm</p><p>ASL Interpreted Performance: Sunday, December 18th, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act One 1:05  Act Two 0:55</p><p><strong>A TLT audience favorite returns, Leg Lamp and all!</strong></p><p>Humorist Jean Shepherd’s memoir of growing up in the midwest in the 1940’s follows nine-year-old Ralphie Parker in his quest to get a genuine Red Ryder BB gun under the tree for Christmas. Ralphie pleads his case before his mother, his teacher, and even Santa Claus himself. The consistent response: “You’ll shoot your eye out!” All the elements from the beloved movie are here, including the family’s temperamental exploding furnace; Scut Farkas, the school bully; the boys’ experiment with a wet tongue on a cold lamppost; the Little Orphan Annie decoder pin; Ralphie’s father winning a leg lamp; Ralphie’s fantasy scenarios and more.<br/><br/>Recommended for All Ages<br/><br/>Featuring:<br/>Blake R. York as Ralph Parker<br/>Heidi Walworth-Horn as Mother<br/>Andrew Fry as The Old Man<br/>Stephanie Kroschel as Miss Shields<br/>Tyler Weston as Ralphie Parker<br/>Gavin Weston as Randy Parker<br/>Jack Burns as Flick<br/>Fletcher Kelley as Schwartz<br/>Maggie Savage as Esther Jane Alberry<br/>Maya Harris as Helen Weathers<br/>Nigel Kelley as Scut Farkus<br/>Glenn Fischer as Ensemble<br/>Natalie Jolly as Ensemble<br/>Brynn Livengood as Ensemble<br/>Zuzu Zimmer as Ensemble</p><p><a href="/s/Xmas-Program.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/a-christmas-story-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2022/12/06/a-christmas-story-from-tacoma-little-theatre-a-review/">The Suburban Times</a><br/><a href="https://www.showsiveseen.com/a-christmas-story-play-tacoma-little-theatre/">Shows I’ve Seen</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'A Christmas Story', 'Directed by Jennifer York  December 2 - December 24, 2022    18 Performances!   Friday, December 2, 2022 at 7:30pm Saturday, December 3, 2022 at 7:30pm Sunday, December 4, 2022 at 2:00pm Thursday, December 8, 2022 at 7:30pm Friday, December 9, 2022 at 7:30pm Saturday, December 10, 2022 at 2:00pm Sat', 'publish', 'closed', 'closed', '', 'a-christmas-story', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1033', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1034, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc9c0400c668208197c684"><div><div><div><div>\n<div>\n<p>Directed by David Hsieh</p><p>January 20 - February 5, 2023<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, February 2nd at 7:30pm</p><p>ASL Interpreted Performance: Sunday, February 5, 2023 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act One 1:13  Act Two 1:02</p><p><strong>A celebration of the human spirit and the joy of cooking.</strong></p><p><em>Po Boy Tango</em> tells the story of Richie Po, a Taiwanese immigrant who turns to his estranged friend Gloria, an African-American Soul Food Chef, to help him recreate his mother’s ‘Great Banquet’. Despite the challenges of shark fin soup, duck po boy sandwiches, and underlying cultural tensions, they find common ground through their shared humor and the blending of traditional Chinese cuisine and African-American soul food. Helped by lessons from Po Mama’s television cooking show, the two discover a deeper understanding of food, culture, and the nature of friendship.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Sam Lai as Richie Po<br/>Michelle Blackmon as Gloria B.<br/>Aya Hashiguchi Clark as Po Mama</p><p><a href="/s/TLT-Po-Boy-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/po-boy-tango-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.showsiveseen.com/po-boy-tango-play-tacoma-little-theatre/">Shows I’ve Seen</a><br/><a href="https://www.heilmanandhaver.com/film-and-stage-reviews/stage-review-po-boy-tango-tacoma-little-theatre?fbclid=IwAR3Th33rWHdGrRRVb2yfcN-rjl8zU7m4pkaaUTDP5ZNy37sIjGy3zVrilJ8">Helliman &amp; Halver</a><br/><a href="https://thesubtimes.com/2023/01/24/a-celebration-of-the-human-spirit-and-the-joy-of-cooking-po-boy-tango-review/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Po Boy Tango', 'Directed by David Hsieh  January 20 - February 5, 2023 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, February 2nd at 7:30pm  ASL Interpreted Performance: Sunday, February 5, 2023 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under', 'publish', 'closed', 'closed', '', 'po-boy-tango', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1034', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1035, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc9ca97f5597061e5ec791"><div><div><div><div>\n<div>\n<p>Directed by Maria-Tania Bandes B. Weingarden<br/>Musically Directed by Kim Davenport<br/>Choreography by Ashley Roy</p><p>March 3 - March 26, 2023<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>ADDED PERFORMANCE-THURSDAY, MARCH 23RD AT 7:30PM<br/><br/>Pay What You Can: Thursday, March 16th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, March 26, 2023 at 2:00pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act One-1:05 15-minute intermission Act Two-1:04</p><p><strong>University of Washington-Tacoma and TLT join forces!</strong></p><p>Aqua Net, Lycra, lace, and liquor flow freely at one of the Sunset Strips last legendary venues in the 1980s. A place where sex machine Stacee Jaxx takes the stage and scantily clad groupies line up to turn their fantasies into reality. Amidst the madness, aspiring rock star (and resident toilet cleaner) Drew longs to take the stage as the next big thing (and longs for Sherri, fresh off the bus from Kansas with stars in her eyes). But the fairy-tale is about to end when German developers sweep into town with plans to turn the fabled Strip into just another capitalist strip mall. Can Drew, Sherri, and the gang save the strip, and themselves, before it’s too late? Only the music of hit bands Styx, Journey, Bon Jovi, Whitesnake, and more hold the answer.<br/><br/>Recommended for Ages 13+ <br/><br/>Featuring:<br/>Keala Milles as Lonny Barnett<br/>Rafe Wadleigh as Dennis Dupree<br/>Michelle Weingarden-Bandes as Justice Charlier<br/>Vinny Contini as Drew Boley<br/>Annelise Martin as Sherrie Christian<br/>Mari Roy as Regina<br/>Eric Strachan as Hertz Klinemann<br/>Camren Bleiler as Franz Klinemann<br/>Ryan Coleman as Stacee Jaxx<br/>Bailey Christie as Ensemble<br/>Asante Hayes as Strip Club DJ/Ensemble<br/>Wade Hicks as Mayor/Ensemble<br/>Davey Magno as Ensemble<br/>Trevor Owens as Ja’Keith Gill/Ensemble<br/>Haunz Stroschein as Ensemble<br/>Andrew Taula as Father/Ensemble<br/>Madison Bleiler as Ensemble<br/>Christine Dove as Mother/Ensemble<br/>Kristina Dustan as Ensemble<br/>Erin R. Johnson as Constance/Ensemble<br/>Kyleigh Medard as Ensemble<br/>Kelsey Monahan as Ensemble<br/>Keri Peredo Panlasigui as Ensemble<br/>Molly Quinn as Ensemble<br/>Elisabeth Tena as Ensemble<br/>Julia Wyman as Waitress/Ensemble</p><p><a href="/s/Rock-of-Ages-Program.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/rock-of-ages-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2023/03/07/rock-of-ages-and-tacoma-little-theatre-reliving-the-eighties-review/">The Suburban Times</a><br/><a href="https://www.dramainthehood.net/2023/03/rock-of-ages-really-rocks-at-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://www.tacoma.uw.edu/news/getting-ready-rock?fbclid=IwAR0yZDCYj4Jgu4npaFHlXab6CL8-qNthCQUa2kPNqDAgYkmQt0oYgmuajSQ">University of Washington-Tacoma</a><br/><a href="https://l.facebook.com/l.php?__tn__=-UK-R&amp;c%5B0%5D=AT2sP2AaMTq_FWe4r57KYXLrbsUUTtEg2mJi4JP7bGLc4NSR5Bb4pSADjT_uW2XvhQad3Nm0DVJ5xWnpFR8EZCSM29wmBLNurJPN-hGTdErAZLqePAvIHjlSq41qs_jq9aTda_gWf5Eq9QGQ0vhSr8V3Dw2oKNTrH5x9v2rtGL2QFOTF-XDmKY-4qP7AFLRVCRPIdu76SVSi0MsMXZUt8ljU&amp;h=AT1UvPmhSih-kSKdyZZOCLJ14w0ufhGypiObclNmg9C6wcm-XHETKH_mFl2_LH5urjZt9CDiVN8YOJ5i5Yy_d07jucMUk62HDsu8tIyu28h8-BSDCDEDG-QentnzjDBLk9NZkSE&amp;u=http%3A%2F%2Fshowsiveseen.com%2F4321%3Ffbclid%3DIwAR0Ned9dim0FmTT19MANInpFRaxpdE7yK9cxlppdnhcMH8U7f7UnU2tI_OA">Shows I’ve </a><a href="https://www.showsiveseen.com/rock-of-ages-musical-tacoma-little-theatre/">Seen</a><br/><a href="https://www.heilmanandhaver.com/film-and-stage-reviews/Rock-of-Ages-TLT?fbclid=IwAR0nYy3uuo7xCqt5kT5odo6aID5a5PL10ILjQkHvL3Qau04tXCFoaKnydac">Heilman &amp; Haver</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Rock of Ages', 'Directed by Maria-Tania Bandes B. Weingarden Musically Directed by Kim Davenport Choreography by Ashley Roy  March 3 - March 26, 2023 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  ADDED PERFORMANCE-THURSDAY, MARCH 23RD AT 7:30PM  Pay What You Can: Thursday, March 16th at 7:30pm  ASL Interpreted', 'publish', 'closed', 'closed', '', 'rock-of-ages', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1035', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1036, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cca13f38895f775405d447"><div><div><div><div>\n<div>\n<p>Directed by Chris Serface</p><p>April 21 - May 7, 2023<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, May 4th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, May 7, 2023 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act One-1:00 15-minute intermission Act Two-0:55</p><p><strong>What happens when all of your friends get married and you’re still alone?</strong></p><p>Jordan Berman would love to be in love, but that’s easier said than done. So until he meets Mr. Right, he wards off lonely nights with his trio of close girlfriends. But as singles’ nights turn into bachelorette parties, Jordan discovers that the only thing harder than finding love is supporting the loved ones around you when they do. But, as they get married one by one, he is left to wonder why life won’t give him the same fairytale ending. <em>Significant Other </em>is an unorthodox romantic comedy that celebrates the highs and lows of twenty- something urban life, wedding after wedding after wedding.<br/><br/>Recommended for Ages 13+ <br/>Strong Adult Language/Sexual Situations/Talk of Suicide/Alcohol Consumption<br/><br/>Featuring:<br/>Nick Fitzgerald as Jordan Berman<br/>Corissa DeVerse as Laura<br/>Amanda McCarther as Vanessa<br/>Tryphaena Singleton as Kiki<br/>Sharry O’Hare as Helene Berman<br/>Rodman Bolek as Will/Conrad/Tony<br/>Paul Richter as Zach/Evan/Roger</p><p><a href="/s/TLT-Significant-Other-Program.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/significant-other-poster-3-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.heilmanandhaver.com/film-and-stage-reviews/stage-review-significant-other-tacoma-little-theatre">Heilman &amp; Haver</a><br/><a href="https://thesubtimes.com/2023/04/25/significant-other-at-tacoma-little-theatre-review/">The Suburban Times</a><br/><a href="https://www.showsiveseen.com/significant-other-play-tacoma-little-theatre/">Shows I’ve Seen</a><br/><a href="https://www.dramainthehood.net/2023/04/significant-other-or-better-yet-significant-self/">Drama in the Hood</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Significant Other', 'Directed by Chris Serface  April 21 - May 7, 2023 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 4th at 7:30pm  ASL Interpreted Performance: Sunday, May 7, 2023 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time: Act', 'publish', 'closed', 'closed', '', 'significant-other', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1036', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1037, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62cc9d9b9523911db9a88a0c"><div><div><div><div>\n<div>\n<p>Directed by Blake R. York</p><p>June 2 - June 18, 2023<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, June 15th at 7:30pm</p><p>ASL Interpreted Performance: Sunday, June 18, 2023 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-48 minutes Act 2-60 minutes</p><p><strong>Stephen King’s novella that inspired the film finally comes to the stage!</strong></p><p>Based on the novella by Stephen King, this adaptation of <em>The Shawshank Redemption</em> hearkens to the 1994 critically acclaimed film, bringing audiences to the edge of their seats. Andy Dufresne is convicted of the murder of his wife and her lover and sentenced to life imprisonment at Shawshank prison. While at Shawshank, Andy befriends some of the other inmates, namely a character known as Red. Over time Andy finds a way to live out life with as much relative ease as one can find in prison, leaving a message for all that while the body may be locked away in a cell, the spirit can never be truly imprisoned.<br/><br/>Recommended for Ages 16+ </p><p><strong><em>Replica rifles are featured on the stage but no shots are fired.  Includes strong explicit  language, scenes of a sexual nature, and some adult male nudity.</em></strong><br/><br/>Featuring:<br/>Mason Quinn as Andy Dufresne<br/>Mark Peterson as Red<br/>Joseph Grant as Warden Stammas<br/>Joshua Johnson as Hadley<br/>Alex Vowles as Entwistle<br/>Darius Sakui as Tommy Williams<br/>Beau Prichard as Dawkins<br/>Ton Williams as Rico<br/>Roger Iverson as Brooksie<br/>Joshua Olver as Bogs Diamond<br/>Paul Richter as Rooster<br/>Jeffrey York as Pinky<br/>Nathan Lovitt as Con/Ensemble<br/>Glenn Fischer as Con/Ensemble<br/>Russ Coffey as Con/Ensemble</p><p><a href="/s/Shawshank-Program.pdf"><strong>PROGRAM</strong></a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/the-shawshank-redemption-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2023/06/05/the-shawshank-redemption-at-tacoma-little-theatre-a-review/">The Suburban Times</a><br/><a href="https://www.dramainthehood.net/2023/06/shawshank-redemption-hope-springs-eternal/">Drama in the Hood</a><br/><a href="https://www.heilmanandhaver.com/stage-reviews/Shawshank-TLT">Heilman &amp; Haver</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'The Shawshank Redemption', 'Directed by Blake R. York  June 2 - June 18, 2023 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 15th at 7:30pm  ASL Interpreted Performance: Sunday, June 18, 2023 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time:', 'publish', 'closed', 'closed', '', 'the-shawshank-redemption', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1037', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1038, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64add2c3b6f4695b3671e875"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/jalen-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2023-2026</strong></p><p>Jalen C. Penn (he/him) is an actor, director, rapper/DJ, and educator who uses his educational background and hip-hop roots/influences to promote diversity, equity, and inclusion in all things he pursues. </p><p>Jalen Originally attended Saint Martin’s University to study English Language Arts in attempts to become a scholar, but was quickly hit with the Theatre bug after being cast in his first evening of one acts on campus. This inspired Jalen to pursue a double major in English Language Arts and Theatre Arts at SMU. During this time Jalen would appear in a multitude of school productions and community productions but his favorites are as follows:  <em>Into the Woods</em> (Wolf/Cinderella’s Prince), <em>Uncle Vanya </em>(Astrov), <em>The Drowsy Chaperone (</em>George),  <em>The Last Days of Judas Iscariot </em>(El Fayoumy), <em>Polaroid Stories (</em>Orpheus); and post grad <em>Shrek the Musical </em>(Donkey) with SRO Theatre in Yelm and <em>As You Like it (</em>Orlando) with Gold Finch Productions in Olympia, WA. </p><p>In addition to his on stage experiences, Jalen takes great pride in his directing and stage managing too. Most recently, Jalen returned to his Alma Mater, SMU, and co-directed <em>The Play That Goes Wrong. </em>He has also assisted stage manage multiple productions for The Harlequin Theatre and Olympia Family Theatre in Olympia, WA. Jalen is eager to continue this good work as he pursues more opportunities up North with TLT and others alike. Furthermore, Jalen hopes to seek more opportunities to work with more creatives of color who look like him and have similar experiences and stories to tell. </p><p>While a big chunk of Jalen’s experiences are in theatre production, Jalen is an accomplished educator as well, where he adopts a Hip-Hop cultural philosophy in the classroom, which he thinks can be applied to stage work too. Jalen believes theatre, like hip-hop, is about truth, rhythm, and giving voice to stories that demand to be heard. His philosophy blends art and education—using the stage as a classroom where curiosity, critical thinking, and cultural awareness are sharpened. Jalen is committed to building spaces where artists and learners alike can take risks, speak boldly, and grow through the process. Education and theatre both thrive on representation, mentorship, and real-world relevance. If the work has a pulse, a purpose, and the power to teach, it belongs in the spotlight.</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Jalen C. Penn', 'BOARD TERM 2023-2026   Jalen C. Penn (he/him) is an actor, director, rapper/DJ, and educator who uses his educational background and hip-hop roots/influences to promote diversity, equity, and inclusion in all things he pursues.&nbsp;  Jalen Originally attended Saint Martin’s University to study', 'publish', 'closed', 'closed', '', 'jalen-c-penn', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1038', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1039, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64add1578810e21fd9515fd6"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/ashley-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2023-2026</strong></p><p>Ashley Young long-time and proud resident of the PNW. While she\'s lived in different states on opposite sides of the country, including Virginia, North Carolina, Tennessee, and California, Ashley and her long-term partner Michael grew up in Tacoma and settled back here in 2017 to raise their two young children.</p><p>Ashley grew up singing and performing in church and high school. She was a soprano and alto for the Henry Foss High School competition jazz and chamber choirs. From there she went on to travel two years with a performing arts non-profit organization doing assembly shows for elementary students on the weekday and performing at churches throughout the country. It was with this organization that she performed in Pigeon Forge, TN (home of the famous Dollywood) doing musical theater. In her personal music endeavors she has performed with bands such as Phunkatron and the Double Duce Horns.</p><p>In her career, Ashley has spent over a decade in hospitality, as a corporate and social event planner, director, and venue manager for several venues in San Diego, Seattle, and Tacoma. In her time as a government employee, Ashley has acted as the liaison for committees such as the Des Moines Arts Commission.</p><p>In her new role with City of Tacoma, Ashley is the Community Events Coordinator working with the Tacoma Venues and Events Department. She oversees Special Event Permits and is the liaison to the City [of Tacoma] Events and Recognition’s Committee, who host the Dr. Martin Luther King Jr. Day Celebration and the City of Destiny Awards. In addition, she has overseen grant programs for arts and culture, applied for program funding, and worked hand in had with tourism marketing organizations.</p><p>Though Ashley’s involvement with performing arts has evolved over the years, she is passionate about providing access to those who may otherwise not have it, supporting career paths for events and arts, and finding new ways to engage the community in arts and culture. </p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Ashley Young', 'BOARD TERM 2023-2026   Ashley Young long-time and proud resident of the PNW. While she\'s lived in different states on opposite sides of the country, including Virginia, North Carolina, Tennessee, and California, Ashley and her long-term partner Michael grew up in Tacoma and settled back here in 2017', 'publish', 'closed', 'closed', '', 'ashley-young', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1039', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1040, 1, '2026-05-09 16:14:23', '2026-05-09 16:14:23', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-680981a194649a1f781713a4"><div><div><div><div>\n<div>\n<p>Tacoma Little Theatre is excited to announce its partnership with <a href="https://www.facebook.com/HarborLightsTacoma?__cft__[0]=AZXcW4NYm2Vn3-zIk18RHGaZlV2zSc-ux4YaryhZQhXpH0J1ksms78jsKTdO4_5BGCMfF8FXStVxJG811JqXXOcTYE7SS-hr6LBIc9Kzu9jW0KlJ4Qh6OXtHVHUBz4zMhIWN7qRkGzEAWnYaUBIA24NlZgMzlgVQFv7JMSmwvbUkBlAtJoFkiT6Wmy13JHJKtu0lvcx6gJvCx3t8RqMusITw&amp;__tn__=-]K-R"><strong>Harbor Lights</strong></a> for our patrons.</p><p>ALL PATRONS</p><p>Enjoy access to the 3-Course Sunset Dinner menu any day of the week before or after a performance. Just show your ticket!</p><p>SEASON/FLEX PASS HOLDERS</p><p>Dinner deserves a standing ovation too. Your subscription includes one complimentary appetizer or dessert with every performance.</p>\n</div>\n</div></div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<a href="https://www.anthonys.com/restaurant/harbor-lights/" target="_blank">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2550" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/harbor-lights-program-insert-0126-2.jpg" width="1650"/>\n</div>\n</div>\n</a>\n</figure>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://www.anthonys.com/restaurant/harbor-lights/" target="_blank">\n      CLICK HERE TO MAKE A RESERVATION\n    </a>\n</div>\n\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'GRAB DINNER AT HARBOR LIGHTS!', 'TLT AND HARBOR LIGHTS START A NEW PARTNERSHIP  Tacoma Little Theatre is excited to announce its partnership with   Harbor Lights   for our patrons.  ALL PATRONS  Enjoy access to the 3-Course Sunset Dinner menu any day of the week before or after a performance. Just show your ticket!  SEASON/FLEX PAS', 'publish', 'closed', 'closed', '', 'grab-dinner-at-harbor-lights', '', '', '2026-05-09 16:14:23', '2026-05-09 16:14:23', '', 0, 'https://example.local/?post_type=post&amp;p=1040', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1041, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69e126fb83eff920f061e4d6"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1999" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/2026-spring-class-announcement.png" width="1545"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><p>Three great programs for students in grades 1-8!</p> <a class="read-more" href="/blog/20252026/springclass">Read More</a></div>\n<!--POST FOOTER-->', 'Education Program — Blog', '', 'publish', 'closed', 'closed', '', 'education-program-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1041', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1042, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-555b50bde4b0060facccb19b"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3235" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/chris-serface-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p>Chris was raised in the Pacific Northwest (Olympia), where he discovered the theatre at an early age and became involved with the local community scene.  At 17, he became the youngest board member of Capital Playhouse in Olympia, Washington, and helped that organization grow from a seasonal production schedule to year-round programming.  During his educational and professional career, he has traveled throughout the West, working closely with many theatres as an actor, technician, director, musician, volunteer, or board member (sometimes all of them at the same time).  In his previous professional experiences he served as; a District Manager for Hollywood Video (Utah, Arizona, California, and Washington), managing 18 retail locations; Company Manager for Capital Playhouse where he implemented and developed a Human Resources program, oversaw the reorganization of their accounting practices, developed a Community Outreach program, oversaw Profit &amp; Loss management, and ensured patron retention.  In his five years as the Director of Education at Tacoma Musical Playhouse he developed a year round curriculum. He currently sits on the boards of the Washington State Community Theatre Association as its Secretary (<a href="http://www,wscta,org">www.wscta.org</a>), The Rotary Club of Tacoma #8, and is the immediate Past President for the American Association of Community Theatre (<a href="http://www.aact.org">www.aact.org</a>).  </p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Staff — Blog', '', 'publish', 'closed', 'closed', '', 'staff-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1042', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1043, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-555b9c18e4b0e2f61a548a97"><div><div><div><div><div><div>\n<div>\n<h2><a href="/s/2012-2013-SYLVIA.pdf">Sylvia</a></h2><p>September 7th through September 30th, 2012<br/>Directed by Elliot Weiner</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/5550122ee4b0005c697257d6-1432067285715-dpg3mqtlw2n88tx0ofu8.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div><div><div><div><div>\n<div>\n<h2><a href="/s/2012-2013-NIGHT-WATCH.pdf">Night Watch</a></h2><p>October 19th through November 11th, 2012<br/>Directed by Randy Clark</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/image-asset-29.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div><div><div><div><div>\n<div>\n<h2><a href="/s/2012-2013-MIRACLE-ON-34TH-STREET.pdf">Miracle on 34th Street</a></h2><p>November 30th through December 23rd, 2012<br/>Directed by Casi Wilkerson</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/image-asset-30.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div><div><div><div><div>\n<div>\n<h2><a href="/s/2012-2013-Six-Dance-Lessons-in-Six-Weeks.pdf">Six Dance Lessons in Six Weeks</a></h2><p>January 18th through February 10th, 2013<br/>Directed by Frank Kohel</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/image-asset-31.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div><div><div><div><div>\n<div>\n<h2>The Joy Luck Club</h2><p>March 15th through April 7th, 2013<br/>Directed by David Hsieh</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/image-asset-32.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div><div><div><div><div>\n<div>\n<h2><a href="/s/2012-2013-LITTLE-SHOP-OF-HORRORS.pdf">Little Shop of Horrors</a></h2><p>May 3rd through May 26th, 2013<br/>Directed by Maria Valenzuela</p><p>A down-and out skid row floral assistant becomes an overnight sensation when he discovers an exotic plant with a mysterious craving for fresh blood. Soon “Audrey II” grows into an ill-tempered, foul-mouthed, R&amp;B-singing carnivore who offers him fame and fortune in exchange for feeding its growing appetite, finally revealing itself to be an alien creature poised for global domination!</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="479" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/image-asset-33.jpg" width="310"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div></div></div>\n<!--POST FOOTER-->', '2012-2013', '', 'publish', 'closed', 'closed', '', '2012-2013', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1043', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1044, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5552c856e4b02a4d730b0cee"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-4.jpg" width="2200"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p>Four young lovers escape into the forest in defiance of parental commands. They wander into the fairy world, ruled by a King and Queen who happen to be quarreling. The King and his servant sprite Puck cause mayhem among the lovers with a magic potion, which also affects a group of six amateur actors, leading to hilarious conse - quences. Mistaken identities, love potions, mischievous sprites and seriously amateur acting weave together for an enchanting adventure.</p><p><a href="/s/1415-Midsummer-Program.pdf">Program</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'for', '', 'publish', 'closed', 'closed', '', 'for', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1044', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1045, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-686cadbf285e714dff691da7"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 41.66666666666667vw, 41.66666666666667vw" src="/wp-content/uploads/migrated/judy-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2025-2028</strong></p><p>BIO PENDING</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Board — Blog', '', 'publish', 'closed', 'closed', '', 'board-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1045', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1046, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69fa4c25fd533f4af513b70a"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1080" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/orange-and-peach-simple-now-hiring-announcement-instagram-post.png" width="1080"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><p>TLT is currently accepting applications for production team members for 2026-2027!</p> <a class="read-more" href="/blog/20252026/productionteam">Read More</a></div>\n<!--POST FOOTER-->', 'Jobs — Blog', '', 'publish', 'closed', 'closed', '', 'jobs-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1046', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1047, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '\n<div class="body entry-content"><p>Join us for this staged reading!</p> <a class="read-more" href="/blog/2018/shipwrecked-3ywjl">Read More</a></div>\n', 'Off the Shelf — Blog', '', 'publish', 'closed', 'closed', '', 'off-the-shelf-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1047', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1049, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60b16079b2c09b2fb8ff4180"><div><div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3333" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/tlt-american-association-of-community-thaetre-diamond-award-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p><strong>Tacoma Little Theatre</strong> of Tacoma, Washington, is being honored with the <strong>Diamond Crown Organizational Award</strong> by the American Association of Community Theatre (AACT). The 2021 AACT National Award presentations will be pre-recorded and streamed during Virtual AACTFest 2021 National Theatre Festival, Saturday, June 19, beginning at 11:45AM (Eastern). To view the AACT National Awards presentations and participate in other exciting Virtual AACTFest 2021 events during June 14–20, 2021, register at <a href="http://aact.org/21">aact.org/21</a>.</p><p>The AACT Diamond Crown Organizational Award recognizes longevity and vitality of AACT member theatres that have expanded programming and/or facilities in the past ten years and have the administrative leadership to remain vital to their communities for the next ten years. Recipients must have been in continuous operation for seventy-five years. Visit <a href="http://aact.org/awards">aact.org/awards</a> for information on all AACT National Awards, 2021 AACT Award winners, and previous honorees.</p><p>Tacoma Little Theatre (TLT) was founded in 1918 as the Tacoma Little Theatre and Drama League, and at 103 years is among the oldest community theatres currently operating in the United States. TLT’s vision is to offer a destination for the diverse community of Tacoma and Puget Sound by offering a well-rounded season of mainstage productions, staged readings, murder mysteries, special events, and a year-around education program serving both adults and children. TLT increases community awareness through special ticket programs and embracing other non-profit and service organizations, such as United Way. With the support of the community and local funders, TLT was able to complete a full remodel of its auditorium and lobby spaces, beginning in June of 2020. This was the first major upgrade since the 1950s, and came as a result of listening and responding to patron feedback. After a break in response to the Covid pandemic, the theatre is looking forward to welcoming back patrons in the fall of 2021.</p><p>AACT provides networking, resources, and support for America’s theatres. AACT represents the interests of more than 7,000 theatres across the United States and its territories, as well as theatre companies with the U.S. Military Services overseas.</p>\n</div>\n</div></div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="159" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/aactfest21.jpg" width="317"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Press — Blog', '', 'publish', 'closed', 'closed', '', 'press-blog', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=post&amp;p=1049', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1050, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<p></p>', 'Tacoma Little Theatre', '', 'publish', 'closed', 'closed', '', 'cover', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=page&amp;p=1050', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1051, 1, '2026-05-09 16:14:24', '2026-05-09 16:14:24', '<div><div><p class="button-row"><a href="https://tlt.ludus.com" target="_blank">\n      PURCHASE TICKETS\n    </a></p><div><div>\n<div>\n</div>\n</div></div><div class="float float-right"><div>\n<div>\n<p><strong>MUSICALS</strong><br/>$32.00 for Adults<br/>$30.00 for Seniors (60+)/Students/Military<br/>$25.00 for Children (12 and under)</p><p><strong>GROUP RATES</strong><br/>10-24 tickets $26.00<br/>25+ tickets $25.00<br/><em>Group rates can be purchased through the box office only</em><br/> </p>\n</div>\n</div></div><div><div>\n<div>\n<p><strong>PLAYS</strong><br/>$30.00 for Adults<br/>$28.00 for Seniors (60+)/Students/Military<br/>$23.00 for Children (12 and under)</p><p><strong>GROUP RATES</strong><br/>10-24 tickets $24.00<br/>25+ tickets $23.00<br/><em>Group rates can be purchased through the box office only</em></p><p><strong>PAY WHAT YOU CAN (PWYC) PERFORMANCES</strong><br/>PWYC performances are typically held the third Thursday<br/>of the run of a show.  Our suggested minimum donation<br/>is $5.00.  PWYC tickets can be purchased in person, over the phone, or online.</p><p><strong>DEBIT/CREDIT CARD TRANSACTION FEES</strong><br/>Credit/Debit Card orders carry a 5% convenience fee and $0.85 charge per ticket/pass added to the grand total.  There are no transaction fees for cash or check transactions. </p><p><strong>GIFT CARDS</strong><br/>Gift Cards are available to purchase in any amount on our website, over the phone, or in person.  Gift Cards are available to be used on ticket purchases, Season Ticket packages, FLEX Passes, and Class Enrollments.  At this time Gift Cards cannot be used on concessions. <br/>Gift Cards are redeemable online,  over the phone, or in person. </p><h1><strong>Season Tickets and Flex Passes</strong></h1>\n</div>\n</div></div><div class="float float-right"><div>\n<div>\n<p><strong>Pricing:</strong><br/>$171.20 for an Adult Season Ticket<br/>$160.00 for a Senior (60+)/Student/Military Season Ticket<br/>$132.00 for a Child (12 and under) Season Ticket</p><p>$160.00 for a FLEX pass</p><p><strong>SUBSCRIBE TODAY!</strong></p><p>If you would like to subscribe to TLT you can do so online, by calling us, or by mailing in an order form to:</p><p>Tacoma Little Theatre<br/>210 North I Street<br/>Tacoma, WA 98403</p>\n</div>\n</div></div><div><div>\n<div>\n<p>Season tickets offer you the same seat and date of your choice for all seven (7) Main Stage shows.  Flex passes SIX (6) admissions that allow you to see any Main Stage show at any time with advance reservations.  Both options offer you a savings, however, the Flex Pass requires that you make reservations in advance and are not guaranteed the same seats.</p><h3>SEASON TICKETS</h3><p>A Season Ticket is good for one seat to all of our regular productions. (Does not include Special Events) You save per show over the single ticket price, are guaranteed the same seat for every show in your date package, and are able to exchange your ticket for no additional fee (minimum 24 hours notice) if necessary.</p><h3>FLEX PASS</h3><p>The Flex Pass is a prepaid admission, which saves you per show over the single ticket price.  Flex Passes can be used for our Main Stage productions only and do not apply to Education productions or Special Events. The 6 Show Flex Pass allows you to use your punch options however you wish. Flex Passes can be redeemed for tickets online or by calling the Box Office at least 24 hours before the performance. <em>Remember that Flex Passes are only six punches (there are seven shows in a season)</em></p><p>You can use your Flex Pass in several combinations, even use it to bring a friend! When you determine the best date to attend a performance, give us a call, and we\'ll get you the best seats available at the time you order. <strong>Many shows sell out fast. Flex Pass holders are advised to make their reservations at least two weeks before the desired performance date.</strong></p><h1>POLICIES</h1>\n</div>\n</div></div><div><div><div><div>\n<div>\n<h2>General policies</h2><p>LOST TICKET REPLACEMENT<br/>If you lose your tickets, call the Box Office and we can reprint them for you. Reprinted tickets will be held at the WILL CALL window under your last name, and can be picked up on the date of the performance.</p><p>TICKET SALES</p><ul><li><p>All ticket sales are final. No refunds. We offer ticket exchanges. (Murder Mystery Dinners must be exchanged 5 days in advance)</p></li><li><p>Online ticket orders require a credit card to complete.</p></li><li><p>Online ticket orders receive email confirmation.</p></li><li><p>If you gave a donation, your credit card will be charged with your donation amount in addition to your ticket order amount.</p></li></ul><p>BABES IN ARMS<br/>For the comfort of our other patrons, please no babes in arms during our productions.</p><p>SPECIAL NEEDS SEATING<br/>TLT offers wheelchair accessible seating for each performance. If you or someone in your party requires this, please call the Box Office for arrangements and availability.</p><p>CAMERAS &amp; OTHER DEVICES<br/>For the respect, comfort and safety of the actors and patrons, the use of cameras and recording devices is not permitted. Please ensure that all noise-making electronics (phones, pagers, PDAs, handheld games, etc.) are turned off before the show starts.</p><p>LATE SEATING<br/>For the respect, comfort and safety of the patrons who arrived on time, if you arrive after the show has started, you will be seated in the back of the theatre (at the House Manager’s discretion) until intermission. At that time, an usher will be happy to show you your assigned seats. If you have not claimed your seats 15 minutes after the show has begun, Management reserves the right to release your seats.</p><p>CONCESSIONS<br/>Beverages (including soft drinks, coffee &amp; tea) as well as beer, wine, and cocktails are available along with a variety of snacks before performances and at intermission.</p><p>COAT CHECK<br/>There is a self coat check located inside the auditorium.  TLT is not responsible for lost or stolen articles.</p><p>RIGHT TO REFUSE SERVICE<br/>Tacoma Little Theatre reserves the right to refuse service.</p><p>PARKING<br/>Tacoma Little Theatre has limited parking available for Season Ticket Holders and Donors.  For more information about this parking agreement, please contact the Box Office.<br/>For general parking, we recommend that you arrive 30 minutes before curtain to find parking. Yakima Avenue, 2nd, I, and J streets are popular choices.  <br/>Please note: The 7-11 parking lot has THREE marked spots for TLT patrons.  Do not park in any other 7-11 parking spot.  Also, do not park in any of the private apartment lots.  They will tow your vehicle.</p><p>WEATHER<br/>All performances will take place as scheduled, regardless of weather conditions. Performances may only be cancelled in the event of a complete power outage.</p>\n</div>\n</div></div></div><div><div><div>\n<div>\n<h2>Season Ticket  and Flex Pass Policies</h2><p>SEASON TICKET<br/>A Season Ticket is good for one seat to all seven of our regular Main Stage productions.</p><p>If necessary, you can exchange your Season Ticket by calling the Box Office at (253) 272-2281 at least 24 hours in advance.<br/>Season Tickets are only valid for the season for which they are purchased.</p><p>FLEX PASS<br/>Flex Passes can be redeemed for tickets by calling the Box Office at least 24 hours before the performance.<br/>Flex Passes are only valid for Main Stage and Second Stage productions. They are not valid for SPECIAL EVENTS..<br/>Flex Passes can be used however the patron prefers.  There are 6 punches available.<br/>Once reservations are made with the Flex Pass, there are no refunds but we offer an exchange for no extra fee.<br/>FLEX passes are only valid for the season in which they are purchased.</p>\n</div>\n</div></div></div></div></div></div>', 'Ticket Information & Policies', '', 'publish', 'closed', 'closed', '', 'ticketinfo', '', '', '2026-05-09 16:14:24', '2026-05-09 16:14:24', '', 0, 'https://example.local/?post_type=page&amp;p=1051', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1052, 1, '2026-05-09 16:14:25', '2026-05-09 16:14:25', '<div><div><div><div>\n<div>\n<p>Interested in volunteering at TLT?  Click the button below and stay up to date on all the opportunities!</p>\n</div>\n</div></div><p class="button-row"><a href="https://tlt.ludus.com/volunteering.php" target="_blank">\n      VOLUNTEER WITH TLT\n    </a></p></div></div>', 'Volunteer', '', 'publish', 'closed', 'closed', '', 'volunteer', '', '', '2026-05-09 16:14:25', '2026-05-09 16:14:25', '', 0, 'https://example.local/?post_type=page&amp;p=1052', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1053, 1, '2026-05-09 16:14:25', '2026-05-09 16:14:25', '<div class="sqs-layout sqs-grid-12 columns-12" data-type="page" data-updated-on="1563822738405" id="page-55502164e4b0e06fcd3caf64"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="461" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/final-mural-copy.jpg" width="1440"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>HISTORY - A Concise Summary of a Century by Judith Cullen</p><p>In October of 1918, a group of civic-minded community members founded the Tacoma Chapter of the Drama League of America (known as the "Tacoma Drama League" or sometimes as the "Civic Drama League"). The Drama League of America sought to promote theater, the study of theatrical literature and culture as a means of community building and individual enrichment. Many chapters were started across the United States during the years surrounding the first World War. The Tacoma Chapter comprised the Civic Drama School and Tacoma Little Theatre (TLT); the Drama League providing oversight and governance.</p><p>While TLT\'s first fully-realized production was not until December 1919, a production of George Bernard Shaw\'s <em>You Never Can Tell,</em> the time from 1918 to 1919 was filled with classes, play reading and study. Persistent commitment to the pursuit of artistry and quality community involvement has been the hallmark of the TLT story. While some gaps may be found - for example due to the Great Depression and World War II, organizational activity has never ceased since those early days.</p><p>The 1920s saw TLT moving into its first permanent home in the "new gymnasium" at the Annie Wright Seminary, located at North First and Division Avenue, in the area now at the heart of the Stadium Business District. The first performances in the new space were held on December 11, 1925 with a program featuring Booth Tarkington\'s<em> The Trysting Place,</em> John Millington Synge\'s <em>Riders to the Sea</em>, and Kenneth Raisbeck\'s <em>Torches.</em></p><p>1927 was a banner year for the young company. First came a production of Stephen Phillip\'s tragic drama <em>Paolo and Francesca</em> which opened on February 12, 1927. Based on the tale from 13th C Italy, the play further interpreted the story treated in Dante\'s <em>Inferno</em>, and rendered in paint by Dante Gabriel Rossetti (1855). It was reported at the time to be the "greatest single accomplishment of the Tacoma Drama League to date, a milestone..." Local critics lavished praise; the four performances in the 400-seat Little Theatre (the highest number for a single production at that time) quickly sold out; and a fifth performance had to be added. It was typical for the plays presented at TLT to appear within 2-4 years after their debut productions in New York.</p><p>That summer, the national convention of The Drama League of America convened in Tacoma from June 27th through July 2nd. In his <em>The History of Tacoma Little Theatre, 1918-1932,</em> Stanley Denton Elberson reports, "...the convention would provide an unequaled opportunity for discussion of all phases of theatre," indicating a comprehensive range of topics. Also planned into convention activities were special excursions, and a special train car was booked from Chicago to Tacoma just to convey attendees to the convention. It would be over eight decades before any comparable convocation would return to Tacoma.</p>\n</div>\n</div></div><div class="float float-left"><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2175" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/slavonian-hall.jpg" width="1726"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>When the North First Street property was sold in 1931, and TLT\'s 400-seat home demolished, the company continued theater presentation and study. Members were able to retire all outstanding debts and take up residence in a smaller 100-seat performance space in Slavonian Hall, in Tacoma\'s Old Town. Meanwhile, a new home was sought - and found, just a few blocks away from its original home in the Stadium District. The location at 210 North I Street has remained TLT\'s home ever since.</p><p>The property, originally an auto repair shop, was purchased by the Tacoma Drama League in 1940. The first performance in the new theatre was Maxwell Anderson\'s Knickerbocker Holiday, which was also the first musical production presented by TLT. During the 1940\'s a 32-foot turntable was installed at the new facility using surplus parts from a U.S. Army railroad roundhouse. While much of the early hardware has been replaced over the years, the turntable has remained a unique feature of many productions.</p>\n</div>\n</div></div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="167" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-17.jpg" width="300"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>A second lot immediately to the north was purchased during the next decade. The current office and lobby wing was constructed, opening in 1950. Rehearsal facilities have included the former First Congregational Church on North J Street and Grant Elementary School, and educational programs have been produced in cooperation with a number of local organizations including Tacoma Metro Parks.</p>\n</div>\n</div></div><div class="float float-left"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="204" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-18.jpg" width="250"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>With cultural and political changes in the late 1960s, and the passing of most of the first generations of Little Theatre stalwarts, came challenges to the organization\'s long term sustainability. Yet aggressive slates of productions reflecting the popular theater of the time were mounted, including musical productions of <em>Carnival, South Pacific, and The Music Man;</em> as well as dramatic presentations of <em>Barefoot in the Park, The Night of the Iguana</em>, and<em> Bus Stop</em>.</p>\n</div>\n</div></div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2050" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/the-merry-widow-1952-53.jpg" width="2500"/>\n</div>\n</div>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>The Merry Widow 1952-1953</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>TLT’s growing success in the 1950s and 1960s was greatly influenced by many notable individuals, too many to mention in a concise summary. In the 1950s, TLT\'s paid annual memberships rose from 600 individuals to over 2300. A rigorous schedule of theater classes was maintained with the Civic Drama School, while a season of six productions continued annually - as many as eight in some years.</p><p>The 1970s and early 1980s saw a decline in the Little Theatre\'s scope of operations, but it would be a mistake to represent it as dwindling. The Little Theatre still maintained its six-production main stage season, even in the face of reduced budgets.</p><p>A renaissance began in the mid-1980s, prompted by the arrival and involvement of Mark and Alex Lewington; the hiring of Peter Epperson to what was then essentially an office manager position, and TLT\'s only paid staff position that was not work study college students; and the continued philanthropic support of Ed and Bethel Schneebeck.</p><p>With the great success and acclaim of the 1990 production of Athol Fugard’s <em>Master Harold and the Boys</em>, the board of directors and staff began focused conversations around how to better reflect the cultural communities of Tacoma, and celebrate those traditions. This initiative has continued and has led to productions of James Baldwin’s <em>The Amen Corner</em>, August Wilson’s <em>The Piano Lesson</em>, Emily Mann’s <em>Having Our Say: The Delaney Sisters First Hundred Years</em>, Susan Kim’s <em>The Joy Luck Club</em>; and a variety of musical productions.</p>\n</div>\n</div></div><div class="float float-left"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1667" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/1776-001.jpg" width="2500"/>\n</div>\n</div>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>1776 2006</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>Today, TLT continues as the surviving entity of the original three: Tacoma Drama League, The Civic Drama School, and the Little Theatre. As such, it has inherited the responsibilities and goals of all: governance, promotion, education and production. TLT is governed by a volunteer Board of Directors,and is managed by a small professional staff. TLT hires professional directors, and contracts designers and other production leadership positions from among those with professional or other significant experience. The actors, crew, ushers, and all other theater functions are accomplished by over 250 volunteers from a four-county area giving over 10,000 volunteer hours a year to provide their friends, family, neighbors, co-workers and community with some of the best amateur theater this area has to offer.</p><p>Growth in the 21st century has been significant, in many ways realizing the dreams and opportunities envisioned in the preceding decades. The staff and Board of Directors have refreshed the mission of the organization and adopted the working motto: "We bring you the theatre you want to see, and the theatre that you didn\'t know you wanted to see," offering diverse seasons that take many risks, while assuring continuing financial success and sustainability, with creative opportunity for artists and meaningful engagement for audiences. The company has functioned comfortably in the black financially since 2013, allowing for annual budget growth to beyond $500,000 and enabling significant investment in facilities, critical equipment, and patron amenities.</p>\n</div>\n</div></div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1667" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/tltthepillowman17.jpg" width="2500"/>\n</div>\n</div>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>The Pillowman 2018</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>In 2003, TLT first became active in the Washington State Community Theatre Association and the American Association of Community Theatres, hosting both the 2003 Region IX AACTFest Festival and the 2005 Washington State Kaleidoscope Festival in succession. TLT\'s entries in ACCTFest during the last two competition cycles (2017 and 2019) have received high marks for excellence, sending the company to the Region IX festival both years. In June 2019 TLT\'s production of <em>The Pillowman</em> by Martin McDonagh, represented Region IX at the national AACTFest competition in Gettysburg, PA.  Awards won were Best Supporting Actor (Sean Neely), Best Set Design (Blake R. York), Adjudicators Award for Best Ensemble (Sean Neely, Jacob Tice, Christian Carvajal &amp; Andrew Fry), and Blake R. York won the overall set design competition with <em>Bell, Book and Candle.</em> TLT has also been chosen as one of one of six premiere sites for AACT\'s NewPlayFest for 2020, slated to present <em>Shattering </em>in January.</p><p>The Little Theatre is in the midst of a phased facility renovation program, the first one of significance since the 1950s. Phase I was completed in 2017 with a full renovation of the building’s HVAC, and the purchase of the commercial property and structure immediately to the south of the existing buildings - becoming the "Stage Right" work space for the scene shop, with additional spaces to support production and education. Phase II planning and fundraising is underway, with a full overhaul of the theater auditorium and seating as its primary objectives.</p><p>To explore Tacoma Little Theatre’s production history look for the “Prior Seasons” tab.</p><h2>Did You Know?</h2>\n</div>\n</div></div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="162" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-16.jpg" width="200"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>One of TLT\'s first performance venue\'s was The First Congregational Church at 209 South J Street.</p><p>Among the productions presented in the early years (1930) was a controversial play by Eugene O\'Neil: Emperor Jones, an early twentieth century indictment of slavery and enslavement. Among the principle players in that production was one Morris Ankrum, who went on to a have a long career as a supporting actor in many Hollywood motion pictures from the 1940\'s through the early 1960\'s.</p><p>The original structure of TLT\'s facility at 210 North I Street was built in 1913 to repair automobiles. The business was expanded and became Tacoma Motors until the property was purchased by the Tacoma Drama League in 1940.<br/><br/>The first performance in the "new" facility at 210 North I Street was Maxwell Anderson\'s<em> Knickerbocker Holiday</em>, which was also the first musical production presented by TLT.</p><p>TLT\'s turntable was installed during the 1940\'s using surplus parts from a U.S. Army railroad roundhouse. While much of the early hardware has been replaced over the years, TLT maintains its 32\' motorized turntable as a unique feature of the stage to this day.</p>\n</div>\n</div></div></div></div></div>', 'History', '', 'publish', 'closed', 'closed', '', 'history', '', '', '2026-05-09 16:14:25', '2026-05-09 16:14:25', '', 0, 'https://example.local/?post_type=page&amp;p=1053', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1054, 1, '2026-05-09 16:14:25', '2026-05-09 16:14:25', '<div class="sqs-layout sqs-grid-12 columns-12" data-type="page" data-updated-on="1776452894205" id="page-55502be0e4b063a03032fce2"><div><div><div><div>\n<div>\n\n</div>\n</div></div><div class="summary-v2-block"><div>\n<div class="summary-block-wrapper summary-block-collection-type-blog summary-block-setting-text-size-medium summary-block-setting-text-align-left summary-block-setting-design-autogrid summary-block-setting-design-list-thumbnail-left summary-block-setting-metadata-position-below-content summary-block-setting-primary-metadata-date summary-block-setting-secondary-metadata-none summary-block-setting-show-thumbnail summary-block-setting-show-title summary-block-setting-show-price summary-block-setting-show-excerpt">\n<div class="summary-item-list-container">\n\n<div class="summary-item-list">\n<div class="summary-item summary-item-record-type-text summary-item-has-thumbnail summary-item-has-excerpt summary-item-has-cats summary-item-has-author">\n<div class="summary-thumbnail-outer-container">\n<a class="summary-thumbnail-container" href="/blog/20252026/springclass">\n<div class="summary-thumbnail img-wrapper">\n<!-- First Image in Post -->\n<img alt="2026 Spring Class Announcement.png" class="summary-thumbnail-image" elementtiming="summary-thumbnail-image-autogrid" src="/wp-content/uploads/migrated/2026-spring-class-announcement.png"/>\n</div>\n</a>\n<!-- Products: Quick View -->\n</div>\n<div class="summary-content">\n<div class="summary-metadata-container summary-metadata-container--above-title">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2025-03-11">Mar 11, 2025</time>\n</div>\n\n</div>\n<div class="summary-title">\n<a class="summary-title-link" href="/blog/20252026/springclass">Spring Education @ TLT</a></div>\n<div class="summary-metadata-container summary-metadata-container--below-title">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2025-03-11">Mar 11, 2025</time>\n</div>\n\n</div>\n<div class="summary-excerpt summary-excerpt-only"><p>Three great programs for students in grades 1-8!</p></div>\n<div class="summary-metadata-container summary-metadata-container--below-content">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2025-03-11">Mar 11, 2025</time>\n</div>\n\n</div>\n</div>\n</div>\n<div class="summary-item summary-item-record-type-text summary-item-has-thumbnail summary-item-has-excerpt summary-item-has-cats summary-item-has-author">\n<div class="summary-thumbnail-outer-container">\n<a class="summary-thumbnail-container" href="/blog/20252026/summercamp">\n<div class="summary-thumbnail img-wrapper">\n<!-- First Image in Post -->\n<img alt="2026 Summer Camp Announcement.png" class="summary-thumbnail-image" elementtiming="summary-thumbnail-image-autogrid" src="/wp-content/uploads/migrated/2026-summer-camp-announcement.png"/>\n</div>\n</a>\n<!-- Products: Quick View -->\n</div>\n<div class="summary-content">\n<div class="summary-metadata-container summary-metadata-container--above-title">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2024-12-18">Dec 18, 2024</time>\n</div>\n\n</div>\n<div class="summary-title">\n<a class="summary-title-link" href="/blog/20252026/summercamp">Summer Camp @ TLT</a></div>\n<div class="summary-metadata-container summary-metadata-container--below-title">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2024-12-18">Dec 18, 2024</time>\n</div>\n\n</div>\n<div class="summary-excerpt summary-excerpt-only"><p>Summer Camp is enrolling now!</p></div>\n<div class="summary-metadata-container summary-metadata-container--below-content">\n<div class="summary-metadata summary-metadata--primary">\n<!-- Timestamp -->\n<time class="summary-metadata-item summary-metadata-item--date" datetime="2024-12-18">Dec 18, 2024</time>\n</div>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div></div><div><div>\n<div>\n<h1>Education PrograM</h1><p>TLT\'s Theatre classes help students of all ages to grow to their full potential as performers and more importantly as people. TLT’s vision is to bring together students in our community to learn about and practice the skills and techniques of performance art, building life skills in the process. </p>\n</div>\n</div></div><div class="float float-left"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<button class="lightbox">\n<span class="v6-visually-hidden">View fullsize</span>\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1024" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-40.jpg" width="683"/>\n</div>\n</div>\n</button>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>Beauty and the Beast, Jr, Summer 2015</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p>While TLT prides itself in educating students with extensive knowledge and powerful skills they need as performers, our courses and camps are also created to build confidence, team work, collaboration, self esteem, communication, innovative thinking and much, much more!</p><p>Our classes are designed to enhance curriculums of study for both students attending public or private schools and those who are homeschooled, by providing opportunities for art to be part of the daily lives of our students. </p><p>In addition to skill building courses, TLT also offers exciting avenues for performance through our drama camps and stage productions.</p><p>Our instructors are trained theatre artists and bring a variety of experiences within the industry of theatre. Additionally, all instructors provide thorough curriculums for outstanding learning potential and must pass an extensive background check required by TLT.</p><p>TLT is excited to further our mission of enriching our community with quality, live theater experiences.  Come join the fun!</p><p><strong><em>Scholarships:</em></strong><em> The following button will direct you to our online scholarship application. This application is in draft form, and is being used for beta testing. If you choose to submit an application with us and do not hear back in just a couple of days, please send us an email at education @tacomalittletheatre.com, to make sure your application has been received and is being processed. We may reach out for additional information as well. Thank you for your patience, as we seek to make the application process easy and accessible!</em> </p>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://docs.google.com/forms/d/e/1FAIpQLSdEwJCTMI4GGxAXoBhfZhi1GrNk0DP5pFTkFFJd1qKc8TciDA/viewform?usp=header">\n      Scholarship Application\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<h2>OUR PROGRAMS</h2><p><strong><em>After-School @ TLT</em></strong></p><p>These wonderful six-week sessions are held twice weekly (Mondays &amp; Wednesdays or Tuesdays &amp; Thursdays) from 4:00pm-6:00pm. We’ll offer classes in the fall, winter, and spring, and each class will culminate in a fully staged play or musical production for friends and family to come enjoy. Students can enroll in one or both sessions. Classes are open to students in grades 1-8.<br/><br/><strong><em>Homeschool @ TLT</em></strong><br/>Modeled on our after school program, this class is designed for the homeschool families in our community. These classes meet twice weekly and take place over a six-week period, culminating in a fully staged production for friends and family to come and enjoy. Tacoma Little Theatre is a certified Community Based Instructor (CBI). Classes are open to students in grades 1-8.<br/><br/><strong><em>Improv</em></strong><br/>Learn the skills necessary to think on your feet and say “Yes, and...”. These tools help young and adult actors with their onstage skills, as well as off stage in school and work. Classes vary from evening to weekend times; please be sure to check our website for the latest details. Classes are available for 12-18-year-olds and for adults.<br/><br/><strong><em>Voice Lessons</em></strong><br/>TLT is not currently offering voice lessons. If you are interested, feel free to reach out to us and we may be able to put you in contact with a teaching artist in our community. You can email us at education@tacomalittletheatre.com.<br/><br/><strong><em>Dance</em></strong><br/>Getting ready for an audition or just wanting to build some skills? Come join us for these fast-paced classes. Classes are offered at a variety of levels and skill sets ranging from the basics of ballet, jazz and musical theater, to more intensive and specific styles of musical theater. Students will spend six weeks focused on a specific style or skill set. Classes are available for all ages.<br/><br/><strong><em>Adult Classes @ TLT</em></strong><br/>TLT’s education program includes our adult actors. These programs start for students 18 and up, they include classes like intro to acting, advanced acting, improv classes, and dance classes. We offer classes and workshops periodically. Check in to see what’s available online or email us at education@tacomalittletheatre.com.</p><p><strong><em>Club TLT</em></strong></p><p>A unique club that offers year-round education dedicated to middle and high school students, ages 13-19. Students will have opportunities to focus on their audition skills to help prepare for school and community auditions they are working on! Students will also have opportunities to learn more about writing and directing their first play. Students can work their improv skills to help build confidence to mold into a variety of characters for their theatrical endeavors. Workshops and master classes in performance, direction, design, stage management, and play writing have all been offered in the past. Special events and activities offer students opportunities to attend performances and volunteer at TLT. Students will work together to create performances specially suited for teenagers.<br/><br/><strong><em>Winter Break Camp</em></strong><br/>Join us during winter break for a fun and exciting camp experience! Dates change year to year to avoid Holidays. This is a great chance for students to spend some time onstage preparing an exciting musical before jumping back into the school year! Camp is most Mondays-Thursdays 9:00am-4:00pm, with one to two performances the last weekend of camp. Open for grades 1-12.<br/><br/><strong><em>Spring Break Camp</em></strong><br/>Join TLT for this lightning fast theater experience! Students will work hard to put together a fully staged musical in just one week! If you plan to stay home for spring break, come join us for this wonderful program! Monday-Friday 9:00am-4:00pm, performs on the weekend. <em>In 2023, we will offer a skills break camp – featuring all of the skill building, learning, and fun of a theater workshop without the pressure of putting on a play. This immersive experience would be appropriate for students who are interested in exploring theater arts, or deepening their skills on stage.</em> Open for grades 1-12.<br/><br/><strong><em>Summer Break Camps</em></strong><br/>We have two summer break camps each year. Camps are four weeks long, and provide an in-depth experience of putting a fully staged musical together, learning about the technical aspects of a production, and learning new theater techniques. Camp meets for four weeks, Monday-Friday 9:00am-4:00pm.</p><p><strong>Students On Stage</strong> </p><p>Our outreach program is designed to bring the entire educational experience to your school! Our programs range from a variety of musical and non-musical options, all designed to bring the importance and value of art into students’ learning. Please contact us for more details by emailing education@tacomalittletheatre.com.</p><h2>Registration Policies</h2>\n</div>\n</div></div><div class="float float-left"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<button class="lightbox">\n<span class="v6-visually-hidden">View fullsize</span>\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1667" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-56.jpg" width="2500"/>\n</div>\n</div>\n</button>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>Legally Blonde, Jr., Summer 2017</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<button class="lightbox">\n<span class="v6-visually-hidden">View fullsize</span>\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2744" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-41.jpg" width="4116"/>\n</div>\n</div>\n</button>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>Grease, Summer 2014</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<ul><li><h2><strong>REGISTRATION &amp; PROGRAM POLICIES</strong></h2><p><strong>Registration:</strong> All registrations are processed in the order they are received. Only payment in full or a payment of the $50 registration fee will secure your spot. Registrations will be accepted until the class is full or until the end of the first week of class, whichever comes first. Once your registration is processed, you will receive confirmation and further class details via e-mail.</p></li></ul><p><strong>Payment:</strong> When you register for classes or camps online, you will be prompted to pay the full tuition amount at that time. If you would prefer to set up a payment plan, we can arrange that! Just contact us at education@tacomalittletheatre.com. The minimum, nonrefundable fee for enrollment is $50. Some scholarship funding is available! Click the button below to apply now. A $35.00 service charge will be attached to any check returned by the bank due to insufficient funds.</p><p><strong>Cancellations:</strong> If you cancel or withdraw from the class more than 14 days prior to the class start, TLT can refund tuition minus a $50.00 cancellation fee. If you cancel within 14 days of the class/camp start date TLT can refund up to half of the tuition. No refunds will be given after the first class or day of camp. In camps or classes where casting is done, no refunds will be offered after casting is complete. We reserve the right to cancel a class if enrollment is insufficient. In this instance, any tuition paid will be refunded in full.</p><p><strong>Participation:</strong> When students join our program, they will be expected to participate in a safe manner, demonstrating respect for others and for property. If a student violates any rules or creates an unsafe situation for staff or other students, we reserve the right to remove the student from the class. Tacoma Little Theatre is not responsible for any lost, damaged, or stolen personal belongings. All dates, times and programming are subject to change.</p><p><strong>Performances:</strong> Please check all performance dates and times for conflicts before enrolling. Typically, actors are called to the theater one to one and a half hours before the performance. Details will be provided for the individual camp or class. </p><p><strong>Attendance:</strong> Please check all rehearsal and class dates/times for conflicts before enrolling. Theater is a team based activity, and absences can impact the whole group. We are often able to work around absences with enough advanced notice.</p>\n</div>\n</div></div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1667" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/image-asset-55.jpg" width="2500"/>\n</div>\n</div>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>Peter Pan, Jr. Summer 2017</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div></div></div></div>', 'About the Program', '', 'publish', 'closed', 'closed', '', 'education', '', '', '2026-05-09 16:14:25', '2026-05-09 16:14:25', '', 0, 'https://example.local/?post_type=page&amp;p=1054', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1055, 1, '2026-05-09 16:14:25', '2026-05-09 16:14:25', '<div><div><div><div>\n<div>\n<h1>In General</h1><p>All auditions are located at Tacoma Little Theatre 210 North I Street.</p><p>Audition dates are subject to change without notice. To schedule an audition appointment follow the link for each show.  If you have questions, please call:  (253) 272-2281 or <a href="/contact">email us here</a>.  <strong><em>Audition sign ups are generally taken one month before audition dates.  If there is a logo below, it will have more information.  IF THERE IS NO LOGO FOR A SHOW, AUDITIONS ARE NOT YET BEING SCHEDULED OR HAVE PASSED. </em></strong></p><p><strong>All auditions are by appointment only.  </strong></p><p><strong>Auditions are scheduled through Casting Manager.  If you don’t have an account, you can sign up for a free one at </strong><a href="http://castingmanager.com/profile/5b7c8e3901d88"><strong>http://castingmanager.com/profile/5b7c8e3901d88</strong></a><strong>.</strong></p>\n</div>\n</div></div><div><div>\n<div>\n<h2>AUDITION DATES</h2><ul><li><p><strong><em>MATILDA August 24-August 26, 2025 THIS SHOW HAS BEEN CAST<br/>Directed by Jennifer York </em></strong></p></li><li><p><strong><em>THE TIME MACHINE September 21-September 23, 2025 THIS SHOW HAS BEEN CAST<br/>Directed by Kathy Pingel</em></strong></p></li><li><p><strong><em>SPRING AWAKENING (in partnership with UWT) December 7-December 9, 2025 THIS SHOW HAS BEEN CAST<br/>Directed by Maria-Tania Bandes B. Weingarden</em></strong></p></li><li><p><strong><em>THE MOUNTAINTOP February 1-February 3, 2026 THIS SHOW HAS BEEN CAST<br/>Directed by Jalen Penn</em></strong></p></li><li><p><strong><em>SOTTO VOCE March 22-March 24, 2026 THIS SHOW HAS BEEN CAST<br/>Directed by Maria Valenzuela</em></strong></p></li><li><p><strong><em>BEDROOM FARCE Dates March 22-March 24, 2026 THIS SHOW HAS BEEN CAST<br/>Directed by Micheal O’Hara</em></strong></p></li></ul><h2>Audition Tips</h2><ul><li><p>Most directors want a 1-2 minute monologue for your initial audition. For a comedy, prepare a humorous monologue; for a non-comedy prepare a serious monologue.; for a musical prepare a song of no less than 16 bars. Bring sheet music as an accompanist will be provided. At the Callback, actors will read from the script.</p></li><li><p>Auditioning for a non-musical play? Come prepared with a monologue. A resume and head shot are nice, but not required.</p></li><li><p>Auditioning for a musical play? Choose a song that enhances and shows off your singing skills - usually not a song from the play for which you are auditioning.</p></li></ul><h2>REHEARSAL INFORMATION</h2><ul><li><p>If cast, most rehearsals take place Monday-Thursday from 7:00pm-9:30pm and on one weekend day. Directors do their best to work around rehearsal conflicts, and you will only be called to the rehearsals you need to be at.</p></li></ul>\n</div>\n</div></div></div></div>', 'Auditions', '', 'publish', 'closed', 'closed', '', 'auditions', '', '', '2026-05-09 16:14:25', '2026-05-09 16:14:25', '', 0, 'https://example.local/?post_type=page&amp;p=1055', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1056, 1, '2026-05-09 16:14:25', '2026-05-09 16:14:25', '<div class="sqs-layout sqs-grid-12 columns-12" data-type="page" data-updated-on="1776371399091" id="page-5550227be4b09fe6f89f4d32"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com">\n      ORDER SINGLE TICKETS HERE\n    </a>\n</div>\n\n</div></div></div></div><div><div><div class="summary-v2-block"><div>\n<div class="summary-block-wrapper summary-block-collection-type-blog summary-block-setting-text-size-medium summary-block-setting-text-align-right summary-block-setting-design-list summary-block-setting-design-list-thumbnail-right summary-block-setting-metadata-position-below-content summary-block-setting-primary-metadata-none summary-block-setting-secondary-metadata-none summary-block-setting-show-thumbnail summary-block-setting-show-title summary-block-setting-show-price summary-block-setting-show-excerpt summary-block-setting-show-read-more-link">\n<div class="summary-item-list-container">\n\n<div class="summary-item-list">\n<div class="summary-item summary-item-record-type-text summary-item-has-thumbnail summary-item-has-cats summary-item-has-tags summary-item-has-author">\n<div class="summary-thumbnail-outer-container">\n<a class="summary-thumbnail-container" href="/blog/20252026/spring-bpb9w">\n<div class="summary-thumbnail img-wrapper">\n<!-- First Image in Post -->\n<img alt="TLT The Mountaintop.jpg" class="summary-thumbnail-image" elementtiming="summary-thumbnail-image-list" src="/wp-content/uploads/migrated/tlt-the-mountaintop-2.jpg"/>\n</div>\n</a>\n<!-- Products: Quick View -->\n</div>\n<div class="summary-content">\n\n<div class="summary-title">\n<a class="summary-title-link" href="/blog/20252026/spring-bpb9w">THE MOUNTAINTOP</a></div>\n\n<a class="summary-read-more-link" href="/blog/20252026/spring-bpb9w">Read More →</a>\n\n</div>\n</div>\n<div class="summary-item summary-item-record-type-text summary-item-has-thumbnail summary-item-has-excerpt summary-item-has-cats summary-item-has-author summary-item-has-location">\n<div class="summary-thumbnail-outer-container">\n<a class="summary-thumbnail-container" href="/blog/2025/revenge-s2keg">\n<div class="summary-thumbnail img-wrapper">\n<!-- First Image in Post -->\n<img alt="TLT The Golden Ball Murder.jpg" class="summary-thumbnail-image" elementtiming="summary-thumbnail-image-list" src="/wp-content/uploads/migrated/tlt-the-golden-ball-murder.jpg"/>\n</div>\n</a>\n<!-- Products: Quick View -->\n</div>\n<div class="summary-content">\n\n<div class="summary-title">\n<a class="summary-title-link" href="/blog/2025/revenge-s2keg">THE GOLDEN BALL MURDER-A MURDER MYSTERY DINNER</a></div>\n\n<div class="summary-excerpt summary-excerpt-only"><p>NEW LOCATION!<br/>Join us for a fun filled Murder Mystery Dinner!</p></div>\n<a class="summary-read-more-link" href="/blog/2025/revenge-s2keg">Read More →</a>\n\n</div>\n</div>\n<div class="summary-item summary-item-record-type-text summary-item-has-thumbnail summary-item-has-excerpt summary-item-has-cats summary-item-has-author">\n<div class="summary-thumbnail-outer-container">\n<a class="summary-thumbnail-container" href="/blog/20252026/springclass">\n<div class="summary-thumbnail img-wrapper">\n<!-- First Image in Post -->\n<img alt="2026 Spring Class Announcement.png" class="summary-thumbnail-image" elementtiming="summary-thumbnail-image-list" src="/wp-content/uploads/migrated/2026-spring-class-announcement.png"/>\n</div>\n</a>\n<!-- Products: Quick View -->\n</div>\n<div class="summary-content">\n\n<div class="summary-title">\n<a class="summary-title-li