INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1079, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d3a44a2e51379000157cc44"><div><div><div><div>\n<div>\n<p>Directed by Blake R. York</p><p>POSTPONED<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, May 7 at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><h2></h2><p><br/>Larry McMurtry’s beautiful and touching story comes to life in this new stage adaptation.</p><p>Though Emma is often exasperated by her highly-opinionated mother, Aurora, they talk every day about their problems, from Aurora finding unexpected love even as she becomes a reluctant grandmother, to Emma\'s struggle in her troubled marriage. But when they need one another most, will they be able to find courage in each other? This funny and touching story captures the delicate, sometimes fractured bonds between mothers and daughters, husbands and wives, and lovers, both old and new.<br/><br/>Recommended for Ages 12+<br/></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-terms-of-endearment-poster-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Terms of Endearment', 'Directed by Blake R. York  September 10 - September 26, 2021 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, September 23rd at 7:30pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time: Act 1-49 minutes Act 2-50 minutes There will b', 'publish', 'closed', 'closed', '', 'terms-of-endearment-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1079', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1080, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60dcf8a83aaa5c53abb58299"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York</p><p>October 22 - November 7, 2021<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/><strong>ADDED PERFORMANCE<br/>FRIDAY, NOVEMBER 5, 2021 at 10:30PM</strong><br/><br/>Pay What You Can: Thursday, November 4th at 7:30pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-44 minutes Act 2-45 minutes There will be a 15 minute intermission</p><p>Was it Miss Scarlet with the lead pipe in the library?  See if you can figure it out!</p><p>Based on the iconic 1985 Paramount movie which was inspired by the classic Hasbro board game, Clue is a hilarious farce-meets-murder mystery. The tale begins at a remote mansion, where six mysterious guests assemble for an unusual dinner party where murder and blackmail are on the menu. When their host turns up dead, they all become suspects. Led by Wadsworth – the butler, Miss Scarlett, Professor Plum, Mrs. White, Mr. Green, Mrs. Peacock, and Colonel Mustard race to find the killer as the body count stacks up. Clue is the comedy whodunit that will leave both cult-fans and newcomers in stitches as they try to figure out…WHO did it, WHERE, and with WHAT!<br/><br/>Recommended for Ages 12+ </p><p>Run Time: Act 1- 45 minutes.  <br/><br/>Featuring:<br/>Mauro Bozzo as Wadsworth<br/>Hana Hahn as Yvette<br/>Robin Mae Becar as Miss Scarlet<br/>Dana Messina Galagan as Mrs. Peacock<br/>Deya Ozburn as Mrs. White<br/>Mark Peterson as Colonel Mustard<br/>Jason Sharp as Professor Plum<br/>Frank Roberts as Mr. Green<br/>Valentine Fry, Keith Ordonez, Janice Williams, Allen Melo, and Gunnar Johnson as Ensemble</p><p><a href="/s/Clue-Program.pdf" target="_blank">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/2122-tlt-clue-on-stage-poster-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Clue', 'Directed by Jennifer York  October 22 - November 7, 2021 Fridays and Saturdays at 7:30pm Sundays at 2:00pm   ADDED PERFORMANCE FRIDAY, NOVEMBER 5, 2021 at 10:30PM   Pay What You Can: Thursday, November 4th at 7:30pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run T', 'publish', 'closed', 'closed', '', 'clue-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1080', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1081, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60dcf9f6a4193f53a4780738"><div><div><div><div>\n<div>\n<p>Directed by Andrew Coopman<br/>Musical Direction by Jeff Bell</p><h3>16 Performances!</h3><p>Friday, December 10th at 7:30pm<br/>Saturday, December 11th at 7:30pm<br/>Sunday, December 12th at 2:00pm<br/>Wednesday, December 15th at 7:30pm<br/>Thursday, December 16th at 7:30pm<br/>Friday, December 17th at 7:30pm<br/>Saturday, December 18th at 7:30pm<br/>Sunday, December 19th at 2:00pm<br/>Tuesday, December 21st at 7:30pm<br/>Wednesday, December 22nd at 7:30pm<br/>Thursday, December 23rd at 7:30pm<br/>Friday, December 24th at 2:00pm<br/>Tuesday, December 28th CANCELLED<br/>Wednesday, December 29th CANCELLED<br/>Thursday, December 30th CANCELLED<br/>Friday, December 31st CANCELLED<br/><br/>Pay What You Can: Thursday, December 16th at 7:30pm<br/><br/>$29 Adults - $27 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p>Run Time: Act 1-1:10 Act 2-1:00 minutes There will be a 15 minute intermission</p><p>Spend the holidays over the rainbow in the merry old land of OZ!</p><p>Click your heels together as you experience one of the most famous stories of all time come to life on our stage. Based on the classic MGM movie musical and the book by L. Frank Baum, The Wizard of OZ has been enchanting families for generations. Follow the yellow brick road and join Dorothy, her little dog Toto, the Scarecrow, Tin Man, and Lion as they journey over the rainbow to the merry old land of Oz in search of the great and powerful Wizard. Will he grant them their hearts’ desires? With all your favorite songs, including “We’re Off to See the Wizard,” “If I Only had a Brain,” and “Somewhere Over the Rainbow,” this timeless musical will sweep you into a magical holiday adventure.<br/><br/>Recommended for All Ages <br/><br/>Featuring:<br/>Jolee Zamira as Dorothy<br/> as Aunt Em/Glinda<br/>David Breyman as Hunk/Scarecrow<br/>Noah Bruckshen as Hickory/Tin Man<br/>Chris Serface as Zeke/Cowardly Lion<br/>Stephanie Leeper as Almira Gulch/Wicked Witch of the West<br/>Joseph Woodland as Professor Marvel/Wizard of OZ<br/>John Limitone as Uncle Henry/Emerald City Guard<br/>Taylor Colvill as Dance Captain and Ensemble<br/>Chap Wolff as Ensemble<br/>Evie Merrill as Ensemble<br/>Luke Miller as Ensemble<br/>Thea Frances Yumang as Ensemble<br/>Jess Mackey as Ensemble<br/>Derek Mesford as Ensemble<br/>Isabela Quesada as Ensemble<br/>Sage Stevens as Ensemble<br/>Allen Melo as Ensemble<br/>Stefanie Van Rafelghem as Ensemble<br/>Jennifer Weddermann as Ensemble<br/>Tony Hay as Ensemble<br/>Erik Davis as Ensemble<br/>Chloe Longacre as Ensemble<br/>Kaitlyn Whitten as Ensemble<br/>Asha Grace as Ensemble</p><p><a href="/s/TLT-OZ-Program-redact.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/2122-tlt-the-wizard-of-oz-poster-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2021/12/14/follow-the-yellow-brick-road-wizard-of-oz-review-tlt/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Wizard of oz', 'Directed by Andrew Coopman Musical Direction by Jeff Bell  16 Performances!  Friday, December 10th at 7:30pm Saturday, December 11th at 7:30pm Sunday, December 12th at 2:00pm Wednesday, December 15th at 7:30pm Thursday, December 16th at 7:30pm Friday, December 17th at 7:30pm Saturday, December 18th', 'publish', 'closed', 'closed', '', 'wizard-of-oz-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1081', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1082, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d38c0cc2c17dd00013ee759"><div><div><div><div>\n<div>\n<p>Directed &amp; Choreographed by Eric Clausell<br/>Musically Directed by Jeff Bell</p><p>March 6 - March 29, 2020<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, March 19 at 7:30pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><br/>It will be ONE singular sensation when this classic show takes the stage!</p><p>From the pen of legendary composer Marvin Hamlisch, comes this Tony Award and Pulitzer Prize-winning singular sensation! Casting for a new Broadway musical is almost complete, and for 17 dancers, this audition is the chance of a lifetime and what they’ve worked their whole lives for.<em> A Chorus Line</em> brilliantly evokes both the glamour and grind of showbiz, and is the musical for everyone who’s ever had a dream and put it all on the line. The iconic score features such classics as “What I Did for Love,” “One,” “I Hope I Get It”, and more! With its celebration and true-to-life depiction of performers and their struggle to achieve greatness on the Broadway stage, <em>A Chorus Line</em> has earned unanimous praise as one of the true masterpieces of live theater.<br/><br/>Run Time  Act 1: 0:58  Act 2: 1:03<br/><br/>Recommended for Ages 12+</p><p>Featuring the talents of:<br/>Heather Adams Arneson as Ensemble<br/>Mauro Bozzo as Gregory<br/>Loucas Curry as Richie<br/>Roycen Daley as Paul<br/>Zachary Edson as Mike<br/>Nick Fitzgerald as Bobby<br/>Valentine Fry as Kristine<br/>Melanie Gladstone as Val<br/>Austin Harris as Larry<br/>Anna Herron as Ensemble<br/>Keola Holt as Diana<br/>Lisa Kelley as Bebe<br/>Anden DeLeon as Ensemble<br/>Liam Loughridge as Mark<br/>Heather Malroy as Sheila<br/>Derek Mesford as Don<br/>Micheal O’Hara as Zach<br/>Thea Ramirez as Ensemble<br/>Adrian Renon as Ensemble<br/>Cynthia Bradford Ryan as Maggie<br/>Whitney Shafer as Cassie<br/>Natalie Silva as Connie<br/>Kira Vega as Judy<br/>Benjamin Wheat as Ensemble<br/>Josh Wingerter as Al<br/></p><p><a href="/s/1920-A-Chorus-Line.pdf">Program</a><br/></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/chorus-line-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'A chorus line', 'Directed and Choreographed by Eric Clausell Musical Direction by Jeff Bell  March 11 - April 3, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, March 24th at 7:30pm  ASL Interpreted performance on Sunday, April 3, 2022 at 2:00pm  $29 Adults - $27 Students/Seniors/', 'publish', 'closed', 'closed', '', 'a-chorus-line-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1082', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1083, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60dcfed4c99bee387311998b"><div><div><div><div>\n<div>\n<p>Directed by Marilyn Bennett</p><p>April 29 - May 15, 2022<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, May 12 at 7:30pm<br/><br/>ASL Interpreted performance on Sunday, May 15, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act One- 1:15  Act Two- 1:00</p><p><a href="/s/The-Happiest-Song-Plays-Last-Program.pdf">PROGRAM</a></p><p>Tacoma Little Theatre and University of Washington-Tacoma join together!</p><p>In a barrio living room in North Philly, an activist-turned-music-professor moonlights as the local soup kitchen queen. Halfway around the world, her cousin relives his military trauma on the set of a docudrama that’s filming in Jordan. With the Egyptian revolution booming in the distance, these two young adults try to sing a defiant song of legacy and love in the face of local and global unrest.<br/><br/>Recommended for Ages 12+ </p><p>This show contains the following:<br/>THEMES OF PTSD AND STORIES OF THE HORRORS OF WAR<br/>FREQUENT STRONG PROFANITY<br/>A FLASHING LIGHT EFFECT<br/>SIMULATED VIOLENCE<br/>SEXUAL SUGGESTIVENESS<br/>NON-NICOTINE, NON-TOBACCO, NON-TAR BASED THEATRICAL CIGARETTES</p><p>Featuring:<br/>Terence Mejos as Elliot<br/>Maria-Tania Bandes B. Weingarden as Yaz<br/>Jesus Villegas Rivera as Agustin<br/>Shailendra (Shelly) Jain as Ali<br/>Katie Jones as Shar<br/>Wade Hicks as Lefty</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/2122-tlt-the-happiest-song-plays-last-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2022/05/01/the-happiest-song-plays-last-tacoma-little-theatre-review-of-the-ending-trilogy-by-quiara-alegria-hudes/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Happiest Song Plays Last', 'Directed by Marilyn Bennett  April 29 - May 15, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 12 at 7:30pm  ASL Interpreted performance on Sunday, May 15, 2022 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time:', 'publish', 'closed', 'closed', '', 'happiest-song-plays-last-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1083', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1084, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60dcffad93245867f0cefa86"><div><div><div><div>\n<div>\n<p>Directed by Lydia K. Valentine</p><p>June 3 - June 19, 2022<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, June 16 at 7:30pm</p><p>Talkback: Sunday, June 19, 2022 after the 2:00pm performance.  Free for all.<br/><br/>ASL Interpreted performance on Sunday, June 19, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-1:09 Act 2-1:07 minutes. There will be a 15 minute intermission</p><p><a href="/s/TLT-The-Luck-of-the-Irish-program.pdf">PROGRAM</a></p><p>What would you do if someone claimed your home was theirs?</p><p>When an upwardly mobile African-American couple wants to buy a home in an all-white neighborhood in 1950’s Boston, they pay a struggling Irish family to “ghost-buy” a house on their behalf. Fifty years later, the Irish family wants “their” house back. Moving across two eras, <em>The Luck of the Irish</em> explores racial and social issues and the universal longing for home.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Laurice Roberts as Lucy Taylor<br/>Mark Peterson as Rex Taylor<br/>Janice Williams as Hannah Davis<br/>Joshua Davis as Rich Davis<br/>Amy Van Mechelen as Nessa Charles<br/>Jason Sharp as Joe Donovan<br/>Jill Heinecke as Patty Ann Donovan<br/>Joseph Grant as Mr. Donovan<br/>Debbie Birkey as Mrs. Donovan<br/>Micah Williams as Miles</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlt-the-luck-of-the-irish-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2022/06/08/luck-of-the-irish-tacoma-little-theatre-review/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Luck of the Irish', 'Directed by Lydia K. Valentine  June 3 - June 19, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 16 at 7:30pm  Talkback: Sunday, June 19, 2022 after the 2:00pm performance.  Free for all.  ASL Interpreted performance on Sunday, June 19, 2022 at 2:00pm  $27 A', 'publish', 'closed', 'closed', '', 'luck-of-the-irish-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1084', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1085, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60dcfc5dff0d6745c13138e9"><div><div><div><div>\n<div>\n<p>Directed by pug Bujeaud</p><p>July 8 - July 24, 2022<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, July 21 at 7:30pm<br/><br/>ASL Interpreted performance on Sunday, July 24, 2022 at 2:00pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-62 minutes Act 2-38 minutes There will be a 15 minute intermission</p><p>The true story of a brilliant, history-making woman, hitherto unknown to many of us.</p><p>This true story of 19th-century astronomer Henrietta Leavitt explores a woman’s place in society during a time of immense scientific discoveries, when women’s ideas were dismissed until men claimed credit for them. Social progress, like scientific progress, can be hard to see when one is trapped among earthly complications; Henrietta and her female peers believe in both, and their dedication changed the way we understand both the heavens and Earth.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Jessica Robins as Henrietta Leavitt<br/>Jillian Faulk as Margaret Leavitt<br/>Mason Quinn as Peter Shaw<br/>Rachel Permann as Annie Cannon<br/>Deya Ozburn as Williamina Fleming</p><p><a href="/s/Silent-Sky-Program.pdf">PROGRAM</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/2122-tlt-silent-sky-poster-2.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://alecclayton.com/writingetc/2022/07/10/silent-sky-at-tacoma-little-theatre/?fbclid=IwAR3tthYOaHpR-GJdX8r49bdNWWKzGXOZCahPyAFagJTc2iKC47XvdUts6zM#more-142">Alec Clayton Blog</a><br/><a href="https://thesubtimes.com/2022/07/12/silent-sky-a-dream-come-true-at-tacoma-little-theatre/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Silent sky', 'Directed by pug Bujeaud  July 8 - July 24, 2022 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, July 21 at 7:30pm  ASL Interpreted performance on Sunday, July 24, 2022 at 2:00pm  $27 Adults - $25 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time: Ac', 'publish', 'closed', 'closed', '', 'silent-sky-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1085', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1086, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62be11d4b3361574726d4559"><div><div><div class="float float-right"><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="844" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/2627-season.jpg" width="299"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2><a href="/s/2627-Season-Descriptions.pdf" target="_blank">CLICK HERE FOR SEASON BROCHURE</a></h2><h2><a href="/s/2627-Season-Ticket-Order-Form.pdf" target="_blank">CLICK HERE FOR A MAIL IN SEASON TICKET ORDER FORM </a></h2><h3><strong>ONLINE ORDERS WILL BEGIN IN JULY!</strong></h3><h3>SEASON TICKET</h3><p>A Season Ticket is good for one seat to all  SEVEN (7) of our regular season productions.</p><p>If necessary, you can exchange your Season Ticket by calling the Box Office at (253) 272-2281 at least 24 hours in advance.</p><p>2026-2027 Season Tickets are only valid from August 28, 2026 to July 25, 2027.</p><p><strong><em>FLEX PASS</em></strong></p><p>Flex Passes can be redeemed for tickets by logging into your account at <a href="https://tlt.ludus.com" target="_blank">tlt.ludus.com</a> or by calling the Box Office at least 24 hours before the performance.</p><p>Flex Passes are only valid for regular season performances.  They are not valid for SPECIAL EVENTS.</p><p>Flex Passes can be used however the patron prefers.  There are SIX (6) admissions available.</p><p>Once reservations are made with the Flex Pass, there are no refunds but we offer an exchange for no extra fee.</p><p>2026-2027 FLEX passes are only valid from August 28, 2026 to July 25, 2027.</p><h2>THE OUTSIDER<br/>August 28-September 13, 2026</h2><h3>POLITICS HAVE NEVER BEEN THIS AWKWARD...OR THIS FUNNY</h3><p>Ned Newley doesn’t even want to be governor. He’s terrified of public speaking, and his poll numbers are impressively bad. To his ever-supportive Chief of Staff, Ned seems destined to fail. But political consultant Arthur Vance sees things differently: Ned might be the worst candidate to ever run for office. Unless the public is looking for the worst candidate to ever run for office.  A timely and hilarious comedy that skewers politics and celebrates democracy.</p><h2>ARSENIC AND OLD LACE<br/>October 16-November 1, 2026</h2><h3>MEET THE SWEETEST LITTLE OLD LADIES… WITH A DEADLY HOBBY</h3><p>Drama critic Mortimer Brewster’s engagement announcement is upended when he discovers a corpse in his elderly aunts’ window seat. Mortimer rushes to tell Abby and Martha before they stumble upon the body themselves, only to learn that the two women aren’t just aware of the dead man in their parlor, they killed him! Between his aunts’ penchant for poisoning wine, a brother who thinks he’s Teddy Roosevelt, and another brother using plastic surgery to hide from the police – not to mention Mortimer’s own hesitancy about marriage – it’ll be a miracle if Mortimer makes it to his wedding. </p><h2>HALLMARKED<br/>December 4-December 27, 2026</h2><h3>THE WEST COAST PREMIERE OF A NEW MUSICAL!<br/>A MUSICAL FOR PEOPLE WHO LOVE HALLMARK MOVIES… AND PEOPLE WHO DON’T</h3><p>It seems everyone on the planet is obsessed with Hallmark movies. Everyone except Julie. She had her heart stomped on once and it will not happen again. No way. No how. Not even in Idyllic, Vermont. She refuses to be \'Hallmarked\'! Oh, no! Who\'s the guy in the plaid flannel? Packed with fabulous new pop songs, loads of laughter, and heartwarming delight, Hallmarked is a rom-com fever dream for those who swoon over the movies and for those who love roasting the people who do.</p><h2>DOT<br/>February 5-February 21, 2027</h2><h3>A FAMILY COMEDY WITH HEART—AND JUST A TOUCH OF HEARTBREAK</h3><p>The holidays are always a wild family affair at the Shealy house: But this year, Dotty and her three grown children gather with more than exchanging presents on their minds. As Dotty struggles to hold on to her memory, her children must fight to balance care for their mother and care for themselves. This twisted and hilarious new play grapples unflinchingly with aging parents, midlife crises, and the heart of a West Philly neighborhood.</p><h2>URINETOWN<br/>March 26-April 18, 2027</h2><h3>A WICKEDLY FUNNY, FAST-PACED, AND SURPRISINGLY INTELLIGENT COMEDIC ROMP</h3><p>In this side-splitting satire, the young hero Bobby Strong leads his community in a fight against oppression. Set in a dystopian world where water is scarce and “Hope” is even scarcer, all citizens must now pay a fee for “The Privilege to Pee” at one of the public facilities controlled by a selfish tycoon, and monitored by authorities like Officer Lockstock. The citizens can only hold it in so much longer, and soon the poorest, filthiest of these facilities, run by the formidable Penelope Pennywise, becomes a “number one” site for major change.</p><h2>THE IMPORTANCE OF BEING EARNEST (UWT Partner Project)<br/>May 21-June 6, 2027</h2><h3>A TRIVIAL COMEDY FOR SERIOUS PEOPLE IN PARTNERSHIP WITH UWT</h3><p>Being sensible can be excessively boring. At least Jack thinks so. While assuming the role of dutiful guardian in the country, he lets loose in town under a false identity. Meanwhile, his friend Algernon takes on a similar facade. Unfortunately, living a double life has its drawbacks, especially when it comes to love. Hoping to impress two eligible ladies, the gentlemen find themselves caught in a web of lies they must carefully navigate.</p><h2>THE PLAY THAT GOES WRONG<br/>July 9-July 25, 2027</h2><h3>BACK BY POPULAR DEMAND—GET READY TO LAUGH EVEN MORE</h3><p>Welcome to opening night of the Cornley University Drama Society’s newest production, The Murder at Haversham Manor, where things are quickly going from bad to utterly disastrous. This 1920s whodunit has everything you never wanted in a show—an unconscious leading lady, a corpse that can’t play dead, and actors who trip over everything (including their lines). Nevertheless, the accident-prone thespians battle against all odds to make it through to their final curtain call, with hilarious consequences! Part Monty Python, part Sherlock Holmes, this Olivier Award–winning comedy is a global phenomenon that’s guaranteed to leave you aching with laughter!</p><p><br/><br/><br/><br/></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', '2026-2027 SEASON TICKETS', 'Click here for both new and renewing season ticket orders', 'publish', 'closed', 'closed', '', 'season-tickets', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1086', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1087, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d252b40b6b6780001d2e512"><div><div><div><div>\n<div>\n<p>Directed by Vicki Webb</p><p>September 13 - September 29, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, September 26th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p><br/>Funny, sincere, and just a wee bit naughty!</p><p>When Annie\'s husband John dies of leukemia, she and best-friend Chris resolve to raise money for a new settee in the local hospital waiting room. They manage to persuade four fellow Women’s Institute (WI) members to pose nude with them for an "alternative" calendar, with a little help from hospital porter and amateur photographer Lawrence. The news of the women\'s charitable venture spreads like wildfire, and hordes of press soon descend on the small village of Knapeley in the Yorkshire Dales. The calendar is a success, but Chris and Annie\'s friendship is put to the test under the strain of their new-found fame.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>Shannon Mahan as Chris<br/>Dayna Childs as Annie<br/>Karen Norlin Christensen as Cora<br/>Sharry O\'Hare as Jessie<br/>Carrie Sleeper-Bowers as Celia<br/>Dawn Brazel as Ruth<br/>Jen Aylsworth as Marie<br/>W. Scott Pinkston as John<br/>Kerry Bringman as Rod<br/>Tristin Nelson as Lawrence/Liam<br/>Anne Marie Rutt as Brenda/Lady Cravenshire<br/>Stephanie Leeper as Elaine</p><p><a href="/s/1920-Calendar-Girls.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/calendar-girls-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/09/Strike-a-pose-calendar-girls/#disqus_thread">The Weekly Volcano</a><br/><a href="https://www.dramainthehood.net/2019/09/calendar-girls-works-on-many-levels-for-tacoma-little-theatre/#disqus_thread">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2019/09/20/calendar-girls-tacoma-little-theatre-play-review/">The Suburban Times</a><br/><a href="https://tacomaweekly.com/city-life/comedy-with-a-few-bittersweet-moments-highlight-calendar-girls/">The Tacoma Weekly</a><br/><a href="http://thetacomaledger.com/2019/10/01/calendar-girls-at-the-historic-tacoma-little-theater/">The Tacoma Ledger</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Calendar girls', 'Directed by Vicki Webb  September 13 - September 29, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, September 26th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under   Funny, sincere, and just a wee bit naughty!  When Annie\'s', 'publish', 'closed', 'closed', '', 'calendar-girls-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1087', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1088, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d2532254e68b1000152c68f"><div><div><div><div>\n<div>\n<p>Directed by Niclas Olson<br/>Musically Directed by Benjamin Bentler<br/>Choreographed by Ashley Roy</p><p>October 25 - November 10, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>SPECIAL HALLOWEEN PERFORMANCE<br/>Thursday, October 31, 2019 at 7:30pm<br/><br/>Pay What You Can: Thursday, November 7th at 7:30pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><br/>Just in time for Halloween comes everyone’s favorite 80’s cult horror comedy!</p><p>Five college students go to an abandoned cabin in the woods and accidentally unleash an evil force that turns them all into demons. It\'s all up to Ash (a housewares employee turned demon-killing hero) and his trusty chainsaw to save the day. Blood flies. Limbs are dismembered. Demons tell bad jokes ... and all to music.  This show has fun with the horror genre and, in doing so, appeals to a wide audience. It\'s the only show with a "Splatter Zone"—a section of the audience that gets covered in fake blood. And with this combination of blood, jokes, cheesy effects and awesome musical numbers, Evil Dead The Musical is unlike any show you\'ve ever seen.<br/><br/>Recommended for Ages 16+ </p><p>Featuring the talents of:<br/>Ashley Roy as Linda<br/>Zachary Edson as Ash<br/>Molly Ellenbecker as Cheryl<br/>Annelise Martin as Shelly/Annie<br/>Aleks Merilo as Ed<br/>Guy Taylor Simpson III as Scott<br/>Eric Strachan as Jake</p><p><a href="/s/1920-Evil-Dead.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/evil-dead-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2019/10/27/evil-dead-the-musical-tacoma-little-theatre-review/">The Suburban Times</a><br/><a href="https://www.dramainthehood.net/2019/10/tlts-evil-dead-the-musical-simply-the-most-bizarre-thing/#disqus_thread">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/10/Highway-to-the-Splatter-Zone/">The Weekly Volcano</a><br/><a href="https://www.thenewstribune.com/entertainment/arts-culture/article236779133.html">The News Tribune</a><br/><a href="http://thetacomaledger.com/2019/11/12/tlts-evil-dead-the-musical-and-what-to-expect-during-this-next-season/">The Tacoma Ledger</a></p>\n</div>\n</div></div></div></div><div><div><div class="website-component-block embed-block"><div><div>\n<div class="intrinsic">\n<div class="embed-block-wrapper embed-block-provider-YouTube">\n<iframe allow="autoplay; fullscreen" allowfullscreen="true" class="embedly-embed" frameborder="0" height="480" scrolling="no" src="//cdn.embedly.com/widgets/media.html?src=https%3A%2F%2Fwww.youtube.com%2Fembed%2FJjA4tKKFvKc%3Ffeature%3Doembed&amp;url=https%3A%2F%2Fwww.youtube.com%2Fwatch%3Fv%3DJjA4tKKFvKc&amp;image=https%3A%2F%2Fi.ytimg.com%2Fvi%2FJjA4tKKFvKc%2Fhqdefault.jpg&amp;key=61d05c9d54e8455ea7a9677c366be814&amp;type=text%2Fhtml&amp;schema=youtube&amp;wmode=opaque" width="854"></iframe>\n</div>\n</div>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Evil dead', 'Directed by Niclas Olson Musically Directed by Benjamin Bentler Choreographed by Ashley Roy  October 25 - November 10, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  SPECIAL HALLOWEEN PERFORMANCE Thursday, October 31, 2019 at 7:30pm  Pay What You Can: Thursday, November 7th at 7:30pm  $27 A', 'publish', 'closed', 'closed', '', 'evil-dead-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1088', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1089, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d2cc4c399ce9b0001c880c2"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York</p><p>December 6 - December 29, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>SPECIAL ADDED PERFORMANCE<br/>Thursday, December 26, 2019 at 7:30pm<br/><br/>Pay What You Can: Thursday, December 19th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: 2:20 with a 15-minute intermission</p><p><br/>A hilarious, quirky, and thrilling alternative to your standard holiday entertainment.</p><p>It is December 1936, and Broadway star William Gillette, admired the world over for his leading role in the play Sherlock Holmes, has invited his fellow cast members to his Connecticut castle for a weekend of revelry. But when one of the guests is stabbed to death, the festivities in this isolated house of tricks and mirrors quickly turn dangerous. It is then up to Gillette himself, as he assumes the persona of his beloved Holmes, to track down the killer before the next victim appears. The danger and hilarity are non-stop in this glittering whodunit set during the Christmas holidays.<br/><br/>Recommended for Ages 12+ </p><p>Featuring the talents of:<br/>Dave Champagne as William Gillette<br/>Lissa Valentine as Martha Gillette<br/>Frank Roberts as Simon Bright<br/>Robin Mae Becar as Aggie Wheeler<br/>Blake R. York as Felix Geisel<br/>Heidi Walworth-Horn as Madge Geisel<br/>Danielle Locken as Daria Chase<br/>Anne Marie Rutt as Inspector Goring</p><p><a href="/s/1920-Holmes.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/holmes-for-the-holidays-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://thesubtimes.com/2019/12/09/holmes-for-the-holidays-tacoma-little-theatre-play-review/?fbclid=IwAR0ybUUF0okUCS5XrNBpKKWT1l4yzQzvItiUZwHgt1yYlhB27i69jUOeHik">The Suburban Times</a><br/><a href="https://www.dramainthehood.net/2019/12/holmes-for-the-holidays-a-throwback-treat-for-tlt/?fbclid=IwAR1tFbJRHbp_GFhNYmkBlB29u5BEhCW2wqOO_euqhNnrluoh3eNsJfd4vTM">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/12/The-games-afoot/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Holmes for the Holidays', 'Directed by Jennifer York  December 6 - December 29, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  SPECIAL ADDED PERFORMANCE Thursday, December 26, 2019 at 7:30pm  Pay What You Can: Thursday, December 19th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Un', 'publish', 'closed', 'closed', '', 'holmes-for-the-holidays-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1089', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1090, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d2e51e93fd8d80001ca482d"><div><div><div><div>\n<div>\n<p>by Ken Ludwig</p><p>December 14-December 28, 2019<br/>Saturday, December 14, 21 &amp; 28 at 11:00am and 2:00pm<br/>Wednesday, December 18 at 7:00pm<br/>Sunday, December 22 at 6:00pm</p><p>‘Twas the Night Before Christmas runs 50 minutes with no intermission.</p><p>Tickets:<br/>$15.00 Adults<br/>$12.00 Children (12 and under)</p><h2>Recommended for All Ages</h2><p>A delightfully fun update to the classic poem about the holiday season.</p><p>‘Twas the night before Christmas, and all through the house, creatures were stirring, including a mouse! Kick off your family’s yuletide season with this comic take on the classic poem. When Santa’s Naughty or Nice list has gone missing, it’s up to a pair of dancing mice, a spunky girl, and an Elf-B-I agent to solve the mystery before Santa boards his sleigh.</p><p>Featuring the talents of:<br/>Alexandria Bray as Calliope/Britannia<br/>Evie Merrill as Emily<br/>Jack Burns as Amos<br/>Jay Lurvey as Mulch/Santa Claus/Wendell Sneed<br/>Todd van der Ark as Sir Guy/Uncle Brierly</p><p><a href="/s/1920-Twas.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/twas-the-night-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://thetacomaledger.com/2019/12/20/twas-the-night-before-christmas-is-a-hoot-for-all-ages/"> The Tacoma Ledger</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Twas the night before christmas', 'by Ken Ludwig  December 14-December 28, 2019 Saturday, December 14, 21 &amp; 28 at 11:00am and 2:00pm Wednesday, December 18 at 7:00pm Sunday, December 22 at 6:00pm  ‘Twas the Night Before Christmas runs 50 minutes with no intermission.  Tickets: $15.00 Adults $12.00 Children (12 and under)  Rec', 'publish', 'closed', 'closed', '', 'twas-the-night-before-christmas-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1090', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1091, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d2f621ad1e1f500011df8f4"><div><div><div><div>\n<div>\n<p>Directed by Chris Serface</p><p>January 24 - February 9, 2020<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, February 6th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Run Time: Act 1-1:01  Act 2- 55:00   There will be a 15 minute intermission</p><p><br/>A World Premiere play on the TLT stage.  Winner of the AACT NewPlayFest.</p><p>Jonah has just been released from juvenile commitment into the foster care of Jacqueline Dawson, whose estranged son was murdered by a gang that Jonah was a part of.  She witnessed the crime and testified against the other two perpetrators. Now the gang leader who organized that crime wants to teach a lesson about what happens to “snitches.” He orders Jonah to torture and kill Jacqueline—or be killed himself. The instructions come through Jonah’s girlfriend LaBelle, whose investment in the outcome is intensified by her pregnancy. Jonah and LaBelle plot the murder, even as Jonah’s relationship with the strict but caring Dawson develops, and his imagined visits with her dead son jar his conscience.<br/><br/>Recommended for Ages 12+<br/><br/>Featuring the talents of:<br/>Robin McGee as Jacqueline "DeeDee" Dawson<br/>Donovan Mahannah as Jonah<br/>Joshua Hector as Sonny<br/>Cynthia Kinyanjui as LaBelle</p><p><a href="/s/1920-Shattering.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/shattering-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thenewstribune.com/entertainment/arts-culture/article239544913.html">The News Tribune</a><br/><a href="https://www.dramainthehood.net/2020/01/shattering-taut-and-timely-at-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2020/01/28/shattering-tacoma-little-theatre-play-review">The Suburban Times</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2020/01/Radical-forgiveness/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Shattering', 'Directed by Chris Serface  January 24 - February 9, 2020 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, February 6th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under  Run Time: Act 1-1:01  Act 2- 55:00   There will be a 15 minute', 'publish', 'closed', 'closed', '', 'shattering-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1091', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1094, 1, '2026-05-09 16:14:27', '2026-05-09 16:14:27', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5d3f48f85864ba0001468cc4"><div><div><div><div>\n<div>\n<p>Directed by John W. Olive</p><p>POSTPONED<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, June 18 at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><h2></h2><p><br/>Mystery and intrigue surround you in this political thriller.</p><p>Set in 1999, young American hero Raymond Shaw is decorated for saving his troops in a peacekeeping mission in the Middle East. He returns to the U.S. to find his wealthy widowed mother has married the right wing racist Senator John Iselin. Their goal of reaching the White House gets closer and closer as a game of solitaire figures prominently in the murder of everyone who blocks their way. As a tightly wound plot of espionage, brainwashing, and ruthless ambition unwinds, Raymond Shaw doesn\'t appear as the war hero everyone thought he was.</p><p>Recommended for ages 12+<br/></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/manchurian-candidate-poster-rgb-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Manchurian Candidate', 'Directed by John W. Olive  POSTPONED Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 18 at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under     Mystery and intrigue surround you in this political thriller.  Set in 1999, young Am', 'publish', 'closed', 'closed', '', 'manchurian-candidate-page', '', '', '2026-05-09 16:14:27', '2026-05-09 16:14:27', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1094', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1095, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a91eb352f53875e3605b6"><div><div><div><div>\n<div>\n<p>Directed by Casi Pruitt</p><p>September 14th - September 30th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, September 27th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>A rousing comedy first presented in 2002!</p><p>At a rural fishing Lodge, Froggy, a British demolition expert, has brought along a pathologically shy young man named Charlie who is overcome with fear at the thought of making conversation with strangers. He tells everyone that Charlie is from an exotic foreign country and speaks no English.  Once alone the fun really begins, as Charlie overhears more than he should — the evil plans of a sinister, two-faced minister and his redneck associate; the fact that the minister\'s pretty fiancée is pregnant; and many other revelations made with the thought that Charlie doesn\'t understand a word being said. All of that sets up the wildly funny ending.</p><p>Recommended for Ages 12+ </p><p>Featuring:<br/>Mikel Michener as S/Sgt. "Froggy" LeSueur<br/>Blake R. York as Charlie Baker<br/>Jen Aylsworth as Betty Meeks<br/>Cody Wyld Flower as Rev. David Marshall Lee<br/>Caiti Burke as Catherine Simms<br/>Brian Cox as Owen Musser<br/>Charlie Stevens as Ellard Simms</p><p><a href="/s/1819-The-Foreigner.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-57.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://michaeldresdner.blogspot.com/2018/09/the-foreigner-at-tlt.html?spref=fb">Dresdner’s Theatre Reviews</a><br/><a href="http://www.dramainthehood.net/2018/09/foreigner-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2018/09/15/the-foreigner-tacoma-little-theatre-play-review/">The Suburban Times-Doman</a><br/><a href="https://thesubtimes.com/2018/09/21/tlt-opens-100th-season-with-uproariously-funny-foreigner/">The Suburban Times-Geyer</a><br/><a href="https://tacomaweekly.com/city-life/the-foreigner-launches-tlts-landmark-100th-season/">The Tacoma Weekly</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/09/The-Foreigner/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Foreigner', 'Directed by Casi Pruitt  September 14th - September 30th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, September 27th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under  A rousing comedy first presented in 2002!  At a rural', 'publish', 'closed', 'closed', '', 'foreigner-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1095', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1096, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a92e42b6a282271936ba9"><div><div><div><div>\n<div>\n<p>Directed by Brett Carr</p><p>October 26th - November 11th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, November 8th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p>Halloween is the perfect time for this bewitching love story first presented in 1960!</p><p>Gillian Holroyd is one of the few modern people who can actually cast spells and perform feats of supernaturalism. She casts a spell over an unattached publisher, Shepherd Henderson, partly to keep him away from a rival and partly because she is attracted to him. He falls head over heels in love with her at once and wants to marry her. But witches, unfortunately, cannot fall in love, and this minute imperfection leads into a number of difficulties before they find out if they can live happily ever after. </p><p>Recommended for Ages 8+ </p><p>Featuring:<br/>Victoria Ashley as Gillian<br/>Jed Slaughter as Shepherd<br/>Max Christofferson as Nicky<br/>Wendy Cohen as Queenie<br/>Mike Storslee as Redlitch</p><p>Program</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tltbellbookcandle-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2018/10/bell-book-and-candle-at-tlt.html">Dresdner’s Theatre Reviews</a><br/><a href="http://www.dramainthehood.net/2018/10/bell-book-candle/?fbclid=IwAR3LtV1N38xVPFyuJZ8OyqhfDaMuUxjEZNHmOwROueyriOQqQc7U2EccoRU">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/10/A-bewitching-love-story-for-Halloween/">The Weekly Volcano</a><br/><a href="https://tacomaweekly.com/city-life/tlts-bell-book-and-candle-celebrates-the-season-of-the-witch/">The Tacoma Weekly</a><br/><a href="https://thesubtimes.com/2018/11/05/tlt-casts-a-magic-spell-on-the-audience/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Bell book and candle', 'Directed by Brett Carr  October 26th - November 11th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, November 8th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under  Halloween is the perfect time for this bewitching love story', 'publish', 'closed', 'closed', '', 'bell-book-and-candle-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1096', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1097, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a935e1ae6cf8fe6e58006"><div><div><div><div>\n<div>\n<p>Directed by Micheal O\'Hara<br/>Musically Directed by Zachary Kellogg<br/>Choreographed by Eric Clausell</p><p>December 7th - December 30th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>SPECIAL ADDED PERFORMANCES:<br/>Saturday, December 15, 2018 at 2:00pm<br/>Saturday, December 22, 2018 at 2:00pm<br/>Wednesday, December 26, 2018 at 7:30pm<br/>Thursday, December 27, 2018 at 7:30pm<br/><br/>Pay What You Can: Thursday, December 20th at 7:30pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $22 Children 12 &amp; Under<br/></p><p>Scrooge and the Ghosts of Christmas Past, Present &amp; Future return!  First presented in 1980.</p><p>One of our favorite gifts to the community is this timeless Dickens’ classic.  This musical, with book, music and lyrics by Leslie Bricusse, is adapted from the 1970 musical film Scrooge which starred Albert Finney and Sir Alec Guinness.  The miserly Ebenezer Scrooge undergoes a profound experience of redemption over the course of a Christmas Eve night, after being visited by the ghost of his former partner Jacob Marley and the Ghosts of Christmas Past, Present and Future.<br/><br/>Recommended for All Ages </p><p>Featuring:<br/>Kenya Adams as Mrs. Cratchit<br/>Susan Cates as Mrs. Fezziwig<br/>Andrew Fry as Scrooge<br/>Kathy Kluska as The Ghost of Christmas Past<br/>Jeremy Lynch as Bob Cratchit<br/>George McClure as Mr. Fezziwig<br/>Evie Merrill as Tiny Tim<br/>Chris Serface as The Ghost of Christmas Present<br/>Allie Watkins as Isabel<br/>Joseph Woodland as Jacob Marley</p><p>with Eva Hay, Emily Newland, Kaden Stanford, and Olivia Zamira as The Cratchit Children</p><p>and George Blanchard, Caleb Corpeno, Maddi Deck, Jordan Duncan, Nigel Kelley, Erinne Kellogg, Laura Knight, Elias Jensen, Liam Loughridge, Olivia Montgomery, Tamara Nelson, Tristin Nelson, Alan Plaster, and Thea Ramirez as Ensemble<br/> </p><p><a href="/s/1819-Scrooge.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-58.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://www.dramainthehood.net/2018/12/scrooge-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://michaeldresdner.blogspot.com/2018/12/scrooge-musical-at-tlt.html?spref=fb&amp;fbclid=IwAR24aCcsiDbLguKMt8oou-H-E5on15r_umXzMMxbYk-M7mtMdwOB-9Ldnb8">Dresdner’s Theatre Reviews</a><br/><a href="https://tacomaweekly.com/featured-city-life/tacoma-little-theater-stages-the-timeless-tale-of-scrooge/">Tacoma Weekly</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/12/Song-and-dance-with-Charles-Dickens/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Scrooge the musical', 'Directed by Micheal O\'Hara Musically Directed by Zachary Kellogg Choreographed by Eric Clausell  December 7th - December 30th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  SPECIAL ADDED PERFORMANCES: Saturday, December 15, 2018 at 2:00pm Saturday, December 22, 2018 at 2:00pm Wednesday, De', 'publish', 'closed', 'closed', '', 'scrooge-the-musical-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1097', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1098, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a940a8a922dc88f42d6f6"><div><div><div><div>\n<div>\n<p>Directed by Marilyn Bennett</p><p>January 25 - February 10, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, February 7th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p><br/>In 1935 TLT presented this classic which still resonates today.<br/> <br/>A story so controversial in its time that party guests were asked not to discuss it for fear of starting a fight, lauded by playwright George Bernard Shaw for challenging societal norms, Henrik Ibsen’s play features Nora Helmer: a woman in the role of a typical housewife, treated like a doll, harboring a secret debt for saving her husband’s life. Her debtor, now an employee to her husband, threatens to reveal her secret to her husband in order to save his own job. Nora finds herself faced with a difficult moral dilemma between the sacred values of her marriage and family versus her independence. </p><p>Recommended for Ages 12+ <br/> </p><p>Featuring:<br/>Annie Katica Green as Nora<br/>Sean Neely as Helmer<br/>Kristen Moriarty as Christine<br/>Jason Sharp as Krogstad<br/>Mark Peterson as Dr. Rank<br/>Robin McGee as Anne Marie<br/>Marleyne Hernandez as Helene<br/>Patrick Gow as Ivar<br/>Nigel Kelley as Bob<br/>Jillian Littrell as Emmy</p><p><a href="/s/1819-A-Dolls-House.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-59.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://tacomaweekly.com/featured-city-life/a-dolls-house/">The Tacoma Weekly</a><br/><a href="http://michaeldresdner.blogspot.com/2019/01/a-dolls-house-at-tlt.html">Dresdner’s Theatre Reviews</a><br/><a href="http://www.dramainthehood.net/2019/01/ibsen-doll-house-tlt/?fbclid=IwAR0dK__3uXikf8jcDUSz7n76jYf0L-cKxRFdrplipT4JxitPkbXK79jU6oA">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/01/A-cold-wave-of-anxiety/">The Weekly Volcano</a><br/><a href="https://anniewrightinkwell.org/2883/opinion/annie-green-stars-as-leading-role-in-a-dolls-house/">Annie Wright Inkwell</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'A Doll\'s House', 'Directed by Marilyn Bennett  January 25 - February 10, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, February 7th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under   In 1935 TLT presented this classic which still resonates t', 'publish', 'closed', 'closed', '', 'a-dolls-house-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1098', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1099, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a94628a922dc88f42eeae"><div><div><div><div>\n<div>\n<p>Directed by John Munn<br/>Musically Directed by Debbie Armstrong<br/>Choreographed by Lexi Barnett</p><p>March 8 - March 31, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, March 21st at 7:30pm<br/><br/>$27 Adults - $25 Students/Seniors/Military - $22 Children 12 &amp; Under</p><p><br/>One of Sondheim’s most famous scores comes back to the TLT for the first time since 1997!</p><p>Winner of four Tony Awards®, Stephen Sondheim’s glorious musical masterpiece returns to the TLT stage.  In 1900 Sweden, on a magical night that smiles three times, an aging actress, a married virgin, a sex-starved divinity student, and a buffoonish count find themselves hilariously tangled in a web of love affairs.  Delightful, charming and at times heartbreaking, with gorgeous, lush music, including “A Weekend in the Country,” “Liaisons” and the seminal “Send in the Clowns,” A Little Night Music is a coupling (and uncoupling) tour-de-force.<br/><br/>Recommended for Ages 12+  </p><p>Featuring:<br/>Jonathan Bill as Fredrik Egerman<br/>Jamey Cheek as Count Carl-Magnus Malcolm<br/>Hayley Ewerz as Petra<br/>Dominic Girolami as Frid<br/>Julianna Guzman-Ferreira as Fredrika Armfeldt<br/>Alyssa Hersey as Charlotte Malcolm<br/>Rosalie Hilburn as Madame Armfeldt<br/>Juliet Hollifield as Anne Egerman<br/>Will Johnson as Henrik Egerman<br/>Casi Pruitt as Desiree Armfeldt<br/>Audrey Stowe as Malla<br/>Grace Wilkerson as Osa<br/>Erik Davis, Caryl Dowd, Kira Vega, Heidi Walworth-Horn &amp; Chap Wolff as The Liebeslieder Singers<br/> </p><p><a href="/s/1819-Night-Music.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tltalittlenightmusic-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://michaeldresdner.blogspot.com/2019/03/a-little-night-music-at-tlt.html">Dresdner’s Theatre Reviews</a><br/><a href="http://www.dramainthehood.net/2019/03/night-music-tacoma-little-theatre">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2019/03/12/a-little-night-music-tacoma-little-theatre-review/">The Suburban Times</a>-Doman<br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/03/A-state-of-affairs/">The Weekly Volcano</a><br/><a href="https://thesubtimes.com/2019/03/27/still-time-to-enjoy-a-little-night-music-at-tlt/">The Suburban Times-Geyer</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'A Little Night Music', 'Directed by John Munn Musically Directed by Debbie Armstrong Choreographed by Lexi Barnett  March 8 - March 31, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, March 21st at 7:30pm  $27 Adults - $25 Students/Seniors/Military - $22 Children 12 &amp; Under   One', 'publish', 'closed', 'closed', '', 'a-little-night-music-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1099', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1100, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a94f8575d1fe4d57b753f"><div><div><div><div>\n<div>\n<p>Directed by Randy Clark</p><p>April 26 - May 12, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, May 9th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p><br/>A classic film noir story that will have you guessing until the very end.  First shown in 1947.</p><p>When Mark McPherson first falls in love with Laura, he knows he\'s in love with a phantom—for Laura is dead, and he\'s in charge of her murder investigation. From her portrait, her letters, her personal effects and from his contacts with the three men who loved her, Mark has created an image of a woman tantalizingly alive and real.  As the detective grows obsessed with the case, he finds himself falling in love with the dead woman.  What really happened to Laura?<br/><br/>Recommended for Ages 12+ </p><p>Featuring:<br/>Rodman Bolek as Mark McPherson<br/>Joel Thomas as Danny Dorgan<br/>Ben Stahl as Waldo Lydecker<br/>Randon Welch as Shelby Carpenter<br/>Valeria Sanchez Jimenez as Bessie Clary<br/>Robin McGee as Mrs. Dorgan<br/>Victoria Hope Ashley as A Girl<br/>Steve Tarry as Olsen<br/> </p><p><a href="/s/1819-Laura.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tltlaura-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.thenewstribune.com/entertainment/arts-culture/article229330029.html">The News Tribune Preview</a><br/><a href="http://michaeldresdner.blogspot.com/2019/04/laura-at-tlt.html">Dresdner’s Theatre Reviews</a><br/><a href="http://www.dramainthehood.net/2019/04/laura-classy-and-classic-drama-from-tacoma-little-theatre/?fbclid=IwAR0J1me4mBjHqbCQGEYue4hnjkaBbSxXKMh6atZsivU137dEAv7u2bSe6hI">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2019/05/01/laura-tacoma-little-theatre-review/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Laura', 'Directed by Randy Clark  April 26 - May 12, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 9th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under   A classic film noir story that will have you guessing until the very end.', 'publish', 'closed', 'closed', '', 'laura-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1100', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1101, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5b3a9546aa4a99939679d6bc"><div><div><div><div>\n<div>\n<p>Directed by Rick Hornor</p><p>June 7 - June 23, 2019<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, June 20th at 7:30pm<br/><br/>$25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under</p><p><br/>Noel Coward’s zany comedy had audiences laughing in 1924 when it first took the TLT stage!</p><p>Hoping for a quiet weekend in the country with some guests, David Bliss, a novelist and his wife Judith, a retired actress, find that an impossible dream when their high-spirited children, Simon and Sorel, appear with guests of their own. A houseful of drama waits to be ignited as misunderstandings and tempers flare. With Judith\'s new flame and David\'s newest literary “inspiration” keeping company as the children follow suit, the Bliss family lives up to its name as the “quiet weekend” comes to an exhausting and hilarious finale worthy of Feydeau.<br/><br/>Recommended for Ages 12+ <br/><br/>Featuring:<br/>John W. Olive as David Bliss<br/>Jane McKittrick as Judith Bliss<br/>Rodman Bolek as Simon Bliss<br/>Deya Ozburn as Sorel Bliss<br/>Adrianna Littlejohn Roland as Clara<br/>W. Scott Pinkston as Richard Greatham<br/>Devan Malone as Myra Arundel<br/>Frank Roberts as Sandy Tyrell<br/>Jill Heinecke as Jackie Coryton</p><p><a href="/s/1819-Hay-Fever.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/tlthayfever-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2019/06/hay-fever-at-tacoma-little-theatre.html">Dresdner’s Theatre Reviews</a> <br/><a href="http://www.dramainthehood.net/2019/06/hay-fever-tacoma-little-theatre/?fbclid=IwAR3UyAH_eqw8ndQjK5aE8_WRs1na6PcwCywxrXfDM9xP8wigb-AbaaCp8b0">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2019/06/Eccentricity-is-Bliss/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Hay Fever', 'Directed by Rick Hornor  June 7 - June 23, 2019 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 20th at 7:30pm  $25 Adults - $23 Students/Seniors/Military - $20 Children 12 &amp; Under   Noel Coward’s zany comedy had audiences laughing in 1924 when it first to', 'publish', 'closed', 'closed', '', 'hay-fever-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1101', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1102, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5cc51a6a71c10b79864eb3cc"><div><div><div><div>\n<div>\n<p>Directed by Nyree Martinez</p><p>May 17 - May 19, 2019<br/>Friday and Saturday at 7:30pm<br/>Saturday and Sunday at 2:00pm<br/></p><h2><a href="https://tix4.centerstageticketing.com/sites/tacomalittletheatre/showdates.php?s_id=317">CLICK HERE FOR TICKETS</a></h2><p><br/>Tacoma Little Theatre presents a special added program to its season, <em>Sophie</em>, a play by Bryan Willis and directed by Nyree Martinez.</p><p>From her earliest childhood, Sophie used to write about things and events and people that interested her, and as she became older she often wrote as well about her own thoughts and feelings. This one-act show takes place at an outdoor railway station, where a young Sophie (age 13) talks with her older self (age 19).</p><p>At age 19, the talented Sophie was due to direct and produce a play at the Edinburgh Fringe (Scotland) but died before this ambition could be realized. In the ensuing weeks her family decided to found a charity in Sophie’s name to give financial support to needy students of acting and of singing – ‘Sophie’s Silver Lining Fund’. The charity published a book of Sophie’s own writings entitled ‘Sophie’s Log – thoughts and feelings in poetry and prose’. A few years later the trustees commissioned a playwright to write a short play based on Sophie’s Log.</p><p>Tacoma Little Theatre’s production of <em>Sophie</em> features a strong cast of talented young actresses sharing roles.  Young Sophie is played by Alexandria Bray and Olivia Burns, with Older Sophie being played by Kate Anders and Ayla Carda.</p><p><em>Sophie </em>will run Friday, May 17, through Sunday, May 19, 2019.  Friday and Saturday evening showings are at 7:30pm with Saturday and  Sunday matinees at 2:00pm.  <em>Sophie </em>is recommended for all ages,</p><p>Tickets are $10.00 General Admission. Tickets may be purchased online by <a href="https://tix4.centerstageticketing.com/sites/tacomalittletheatre/showdates.php?s_id=317">clicking here</a>, or by calling our Box Office at (253) 272-2281.  </p><p><em>Sophie</em> will be available for bookings throughout the 2019-2020 school year.  For more information contact Nena Curley, Education Director, at <a href="mailto:education@tacomalittletheatre.com">education@tacomalittletheatre.com</a>.<br/> </p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2700" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/1819sophieposter-2.png" width="1800"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Sophie', 'A special added show to our season', 'publish', 'closed', 'closed', '', 'sophie-page', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1102', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1103, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60da10d432162e327ddfc94e"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/maria-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2024-2027</strong></p><p>A native of Tacoma, Maria has been involved in the performing arts throughout the US and abroad as a performer, director, educator, and administrator... but it all began as a performer and volunteer nearly 40 years ago at TLT. She is a veteran of the US Navy and has extensive background in both non-profit and public/government administration. Maria is a frequent coach, clinician, and adjudicator of student choral and theatrical groups, and is currently the Director of Music and Drama at Saint Patrick School. Maria is so pleased to be returning to TLT this time to serve this community and its legacy as a member of the Board of Directors.</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Maria Valenzuela', 'BOARD TERM 2024-2027   A native of Tacoma, Maria has been involved in the performing arts throughout the US and abroad as a performer, director, educator, and administrator... but it all began as a performer and volunteer nearly 40 years ago at TLT. She is a veteran of the US Navy and has extensive', 'publish', 'closed', 'closed', '', 'board-member-current-2026-may-need-to-merge', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1103', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1104, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-60b16079b2c09b2fb8ff4180"><div><div><div class="float float-right"><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3333" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/tlt-american-association-of-community-thaetre-diamond-award-2.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<p><strong>Tacoma Little Theatre</strong> of Tacoma, Washington, is being honored with the <strong>Diamond Crown Organizational Award</strong> by the American Association of Community Theatre (AACT). The 2021 AACT National Award presentations will be pre-recorded and streamed during Virtual AACTFest 2021 National Theatre Festival, Saturday, June 19, beginning at 11:45AM (Eastern). To view the AACT National Awards presentations and participate in other exciting Virtual AACTFest 2021 events during June 14–20, 2021, register at <a href="http://aact.org/21">aact.org/21</a>.</p><p>The AACT Diamond Crown Organizational Award recognizes longevity and vitality of AACT member theatres that have expanded programming and/or facilities in the past ten years and have the administrative leadership to remain vital to their communities for the next ten years. Recipients must have been in continuous operation for seventy-five years. Visit <a href="http://aact.org/awards">aact.org/awards</a> for information on all AACT National Awards, 2021 AACT Award winners, and previous honorees.</p><p>Tacoma Little Theatre (TLT) was founded in 1918 as the Tacoma Little Theatre and Drama League, and at 103 years is among the oldest community theatres currently operating in the United States. TLT’s vision is to offer a destination for the diverse community of Tacoma and Puget Sound by offering a well-rounded season of mainstage productions, staged readings, murder mysteries, special events, and a year-around education program serving both adults and children. TLT increases community awareness through special ticket programs and embracing other non-profit and service organizations, such as United Way. With the support of the community and local funders, TLT was able to complete a full remodel of its auditorium and lobby spaces, beginning in June of 2020. This was the first major upgrade since the 1950s, and came as a result of listening and responding to patron feedback. After a break in response to the Covid pandemic, the theatre is looking forward to welcoming back patrons in the fall of 2021.</p><p>AACT provides networking, resources, and support for America’s theatres. AACT represents the interests of more than 7,000 theatres across the United States and its territories, as well as theatre companies with the U.S. Military Services overseas.</p>\n</div>\n</div></div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="159" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/aactfest21.jpg" width="317"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'TLT WINS NATIONAL AWARD', 'Tacoma Little Theatre  of Tacoma, Washington, is being honored with the  Diamond Crown Organizational Award  by the American Association of Community Theatre (AACT). The 2021 AACT National Award presentations will be pre-recorded and streamed during Virtual AACTFest 2021 National Theatre Festival, S', 'publish', 'closed', 'closed', '', 'tlt-wins-national-award', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1104', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1105, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5efe961c65a3745dddfd6828"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/maria-tania-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div><div><div><div>\n<div>\n<p><strong>BOARD TERM 2022-2025</strong></p><p>Maria-Tania Bandes B. Weingarden (she/her) is an artist/scholar who has recently joined UWT as an Assistant Teaching Professor in the department of Arts Media and Culture. </p><p>As a director, Maria-Tania uses theatre to challenge homogeneous ideology.  She addresses issues of race and gender on stage by not only the content of her work, but often by casting non-traditionally, works that fit within the more traditional canon.</p><p>While her area of scholarly specialization is in Theatre History, more specifically Latinx theatre, her research focuses on revolutionary theatre.  Her book, <em>Echoes of Revolution: Nicaragua,</em> aims to expand the knowledge of the canon of works of Central American playwrights as well as explores both the successes and limitations of theatre that has undergone political turmoil.  <em>Echoes of Revolution: Nicaragua</em>, is the first of a three-part series on the revolutionary theatre of Central America. </p><p>Other areas of research include Queer Theatre, more specifically the representation of bisexuality on stage.</p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Maria-Tania Bandes B. Weingarden', 'BOARD TERM 2022-2025   Maria-Tania Bandes B. Weingarden (she/her) is an artist/scholar who has recently joined UWT as an Assistant Teaching Professor in the department of Arts Media and Culture.&nbsp;  As a director, Maria-Tania uses theatre to challenge homogeneous ideology.&nbsp; She addre', 'publish', 'closed', 'closed', '', 'maria-tania-bandes-b-weingarden', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1105', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1106, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5981033437c5813a68a8cd95"><div><div><div><div>\n<div>\n<p>Directed by Erin Chanfrau</p><p>September 15th - October 1st, 2017<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, September 28th at 7:30pm</p><p>Neil Simon’s comic genius shines</p><p>Rumors is an uproariously hilarious comedy about lies, deceit and rumors. At a large, tastefully appointed Sneden\'s Landing townhouse, the deputy mayor of New York has just shot himself. Though only a flesh wound, four couples are about to experience a severe attack of farce. Gathering for their tenth wedding anniversary, the host lies bleeding in the other room and his wife is nowhere in sight. His lawyer, Ken and wife Chris must get "the story" straight before the other guests arrive. As the confusions and miscommunications mount, the evening spins off into classic farcical hilarity.</p><p>Featuring:<br/>Jess Allan as Chris Gorman<br/>Mark Peterson as Ken Gorman<br/>Jill Nicole Heinecke as Claire Ganz<br/>Matt Garry as Lenny Ganz<br/>Shelleigh-Mairi Ferguson as Cookie Cusack<br/>Jeffery Swiney-Weaver as Ernie Cusack<br/>Kristen Blegen Bouyer as Cassie Cooper<br/>Houston White as Glenn Cooper<br/>Neicie Packer as Officer Welch<br/>Andy Bravo as Officer Pudney</p><p><a href="/s/1718-Rumors-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-49.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2017/09/rumors-at-tlt.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://www.axs.com/rumor-has-it-rumors-at-tacoma-little-theatre-is-great-fun-123248">axs.com</a><br/><a href="http://thesubtimes.com/2017/09/19/farce-fills-tlt-99th-season-opener-with-peals-of-laughter/">The Suburban Times</a><br/><a href="https://tacomaweekly.com/2017/09/21/tlts-rumors-turns-up-the-volume-on-the-funny-meter/">The Tacoma Weekly</a><br/><a href="https://www.northwestmilitary.com/music-and-culture/stage-and-visual-reviews/2017/09/rumors/">The Weekly Volcano</a><br/><a href="http://www.thenewstribune.com/entertainment/article174043441.html">The News Tribune</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Rumors', 'Directed by Erin Chanfrau  September 15th - October 1st, 2017 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, September 28th at 7:30pm  Neil Simon’s comic genius shines  Rumors is an uproariously hilarious comedy about lies, deceit and rumors. At a large, tastefully ap', 'publish', 'closed', 'closed', '', 'rumors', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1106', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1107, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5981054e414fb5f08fb7b83b"><div><div><div><div>\n<div>\n<p>Directed by Chris Serface</p><p>October 20th - November 5th, 2017<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, November 2nd at 7:30pm</p><p>Halloween is the perfect time for a comic haunting by your two dead wives!</p><p>Noël Coward’s Blithe Spirit is a spook-tacular comic classic. After a “spirited” séance goes decidedly wrong, the cantankerous novelist Charles Condomine suddenly finds himself face to face with the ghost of his deceased wife, Elvira…much to the chagrin of his current spouse, Ruth. Love and marriage devolve into laughter and mayhem when Ruth is accidentally killed and united with Elvira on the “other side.” Together the paranormal pair of blithe spirits haunt their hapless husband with hilarious consequences. <br/> </p><p>Featuring:</p><p>Jed Slaughter as Charles<br/>Deya Ozburn as Ruth<br/>Brittany D Henderson as Elvira<br/>Dana Messina Galagan as Madame Arcati<br/>John P. Saunders as Dr. Bradman<br/>Darla Smedley as Violet<br/>SarahLynn Mangan as Edith</p><p><a href="/s/1718-Blithe-Spirit-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-50.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://www.axs.com/blithe-spirit-at-tacoma-little-theatre-a-community-theater-lover-s-joy-124508">axs.com</a><br/><a href="http://www.northwestmilitary.com/music-and-culture/stage-and-visual-reviews/2017/10/blithe-spirit/">The Weekly Volcano</a><br/><a href="https://michaeldresdner.blogspot.com/2017/10/blithe-spirit-at-tlt.html?spref=fb">Dresdner\'s Theatre Reviews</a><br/><a href="https://tacomaweekly.com/featured-city-life/spooky-fun/">The Tacoma Weekly</a><br/><a href="https://thesubtimes.com/2017/10/30/hail-to-thee-blithe-spirit-what-a-funny-bird-thou-art/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Blithe spirit', 'Directed by Chris Serface  October 20th - November 5th, 2017 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, November 2nd at 7:30pm  Halloween is the perfect time for a comic haunting by your two dead wives!  Noël Coward’s Blithe Spirit is a spook-tacular comic classic', 'publish', 'closed', 'closed', '', 'blithe-spirit', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1107', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1108, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-59810eefd7bdcec55078745f"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York<br/>Musical Direction by Terry O\'Hara<br/>Choreography by Eric Clausell</p><p>December 1st - December 24th, 2017*<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Special added performances:<br/>Wednesday, December 20th at 7:30pm<br/>Thursday, December 21st at 7:30pm<br/>Saturday, December 23rd at 2:00pm<br/><br/>Pay What You Can: Thursday, December 14th at 7:30pm</p><p>Group Rates for 10 or more.  Contact the Box Office!</p><p>Celebrate the holidays with your family in the world of Dr. Seuss!  </p><p>The Cat in the Hat tells the story of Horton, an elephant who discovers a speck of dust that contains the Whos, including Jojo, a Who child sent off to military school for thinking too many "thinks." Horton faces a double challenge: not only must he protect the Whos from a world of naysayers and dangers, but he must guard an abandoned egg, left in his care by the irresponsible Mayzie La Bird. Although Horton faces ridicule, danger, kidnapping and a trial, the intrepid Gertrude McFuzz never loses faith in him. Ultimately, the powers of friendship, loyalty, family and community are challenged and emerge triumphant. </p><p>CAST LIST<br/>The Cat in the Hat-Christopher Sweet<br/>Jojo-Alexandria Bray<br/>Horton-Steve Barnett<br/>Gertrude-Brittany Griffins<br/>Mayzie-Samantha Lobberegt<br/>Sour Kangaroo-Courtney Eggert<br/>Young Kangaroo-Caleb Corpeno (Dec 1, 3, 9, 14, 16, 20, 22, 23 7:30)<br/>Young Kangaroo-Evie Merrill (Dec 2, 8, 10, 15, 17, 21, 23 2pm, 24)<br/>Wickersham Brother-Charlie Stevens<br/>Wickersham Brother-Liam Loughridge<br/>Wickersham Brother-James Wrede<br/>Bird Girl-Caiti Burke<br/>Bird Girl-Emma Konop<br/>Bird Girl-Jayda Slack<br/>Bird Girl-Maddie Fry<br/>Mr. Mayor-Micheal O\'Hara<br/>Mrs. Mayor-Sharry O\'Hare<br/>General Schmitz-Andrew Fry<br/>Ensemble: Kathy Kluska, Gunnar Ray, Thalia Wood, Megan Ross, Olivia Zamira, Caje Johnson</p><p><a href="/s/1718-Seussical-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-51.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2017/12/seussical-musical-at-tlt.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://m.axs.com/tacoma-little-theatre-hears-a-who-and-applause-for-seussical-126031">axs.com</a><br/><a href="https://tacomaweekly.com/featured-city-life/tlt-hits-a-grand-slam-with-seussical-the-musical/">The Tacoma Weekly</a><br/><a href="https://thesubtimes.com/2017/12/07/seuss-and-his-gang-brings-magic-to-tlt/">The Suburban Times</a><br/><a href="http://www.northwestmilitary.com/music-and-culture/stage-and-visual-reviews/2017/12/seussical/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Seussical', 'Directed by Jennifer York Musical Direction by Terry O\'Hara Choreography by Eric Clausell  December 1st - December 24th, 2017* Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Special added performances: Wednesday, December 20th at 7:30pm Thursday, December 21st at 7:30pm Saturday, December 23rd a', 'publish', 'closed', 'closed', '', 'seussical', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1108', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1109, 1, '2026-05-09 16:14:28', '2026-05-09 16:14:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-59811021893fc0d7ad931c06"><div><div><div><div>\n<div>\n<p>Directed by Rick Hornor<br/><br/>January 19th - February 4th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>ALL PERFORMANCES WILL BE OPEN CAPTIONED, for best seats, please contact the box office.</p><p><br/>Pay What You Can: Thursday, February 1st at 7:30pm</p><p>Winner of the Tony Award, the Outer Critics Circle, and the Drama Desk Award as best play<br/> <br/>After three years in the Peace Corps, James, a young speech therapist, joins the faculty of a school for the deaf, where he is to teach lip-reading. He meets Sarah, a school dropout, totally deaf from birth, and estranged both from the world of hearing and from those who would compromise to enter that world. Fluent in sign language, James tries, with little success, to help Sarah, but gradually the two fall in love and marry. At first their relationship is a happy and glowing one, as the gulf of silence between them seems to be bridged by their desire to understand each other\'s needs and feelings, but discord soon develops as Sarah becomes militant for the rights of the deaf and rejects any hint that she is being patronized and pitied. </p><p>Featuring:<br/>Jeremy Lynch as James<br/>Michelle Mary Schaefer as Sarah<br/>Madonna Hanna as Edna<br/>Kristen Moriarty as Mrs. Norman<br/>Kai Winchester as Orin<br/>Kerry Bringman as Franklin<br/>Melanie Gladstone as Lydia</p><p><a href="/s/1718-Lesser-God.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-52.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2018/01/children-of-lesser-god-at-tlt.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://m.axs.com/tacoma-little-theatre-stages-superb-children-of-a-lesser-god-127406">axs.com</a><br/><a href="http://www.dramainthehood.net/2018/01/children-lesser-god-speaks-powerful-language/">Drama in the Hood</a><br/><a href="https://tacomaweekly.com/featured-city-life/the-sound-of-silence/">The Tacoma Weekly</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/01/golden-opportunity/">The Weekly Volcano</a><br/><a href="https://thesubtimes.com/2018/01/26/tlts-children-scream-their-story-in-silence/">The Suburban Times</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Children of a lesser god', 'Directed by Rick Hornor  January 19th - February 4th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  ALL PERFORMANCES WILL BE OPEN CAPTIONED, for best seats, please contact the box office.   Pay What You Can: Thursday, February 1st at 7:30pm  Winner of the Tony Award, the Outer Critics Circ', 'publish', 'closed', 'closed', '', 'children-of-a-lesser-god', '', '', '2026-05-09 16:14:28', '2026-05-09 16:14:28', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1109', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1110, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5981114debbd1abb1c2bb522"><div><div><div><div>\n<div>\n<p>Directed and Choreographed by Lexi Barnett<br/>Musical Direction by Leischen Moore<br/><br/>March 9th - April 1st, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, March 22nd at 7:30pm</p><p>Andrew Lloyd Webber’s masterpiece fills the stage with music and dance.</p><p>It seems especially fitting that the first rock opera, created as a concept album at the end of the turbulent \'60s, should have at its center a social and political rebel. Jesus\' meteor-like rise in renown provides, as the title suggests, a parallel to contemporary celebrity worship. As his radical teachings are evermore embraced, Judas increasingly questions the enlightened motives of this new prophet, resulting in betrayal. Christ\'s final days are dramatized with emotional intensity, thought-provoking edge and explosive theatricality. Propelled by a stirring score, by turns driving and majestic, satirical and tender, Jesus Christ Superstar illuminates the transcendent power of the human spirit with a passion that goes straight to the heart.<br/><br/>Featuring:<br/>Bruce Haasl as Jesus<br/>Loucas T. Curry as Judas<br/>Allie Milburn as Mary<br/>Rico Lastrapes as Simon<br/>Christopher Sweet as Peter<br/>DuWayne Andrews Jr. as Pilate<br/>Aleks Merilo as Caiaphas<br/>Karen Christensen as Annas<br/>Andrew Fry as Herod<br/>George McClure as Priest<br/>James Klarich as Priest<br/>Caiti Burke as Apostle/Soul Girl<br/>Melanie Gladstone as Apostle/Soul Girl<br/>Jill Heinecke as Aspotle/Soul Girl<br/>Jaden Downing as Apostle<br/>Carl Frank as Apostle<br/>Sydney Lenoch as Apostle<br/>Shauntal Pyper as Apostle<br/>Mary Thornton as Apostle<br/>Barrett Vandiver as Apostle<br/>Madison Watkins as Apostle<br/>Randon Welch as Apostle<br/>Julia Wyman as Apostle</p><p><a href="/s/1718-JCS-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-53.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2018/03/jesus-christ-superstar.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://www.dramainthehood.net/2018/03/jesus-christ-superstar-super-good-at-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://thesubtimes.com/2018/03/13/tlts-superstar-is-a-super-star-quality-production/">The Suburban Times</a><br/><a href="https://tacomaweekly.com/featured-city-life/tlt-brings-jesus-christ-superstar-to-the-stage-in-time-for-easter/">The Tacoma Weekly</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/03/Jesus-Christ-Superstar/">The Weekly Volcano</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Jesus Christ Superstar', 'Directed and Choreographed by Lexi Barnett Musical Direction by Leischen Moore  March 9th - April 1st, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, March 22nd at 7:30pm  Andrew Lloyd Webber’s masterpiece fills the stage with music and dance.  It seems especiall', 'publish', 'closed', 'closed', '', 'jesus-christ-superstar', '', '', '2026-05-09 16:14:29', '2026-05-09 16:14:29', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1110', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1111, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5981120fe6f2e10bc7aa2134"><div><div><div><div>\n<div>\n<p>Directed by Blake R. York<br/><br/>April 20th - May 6th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, May 3rd at 7:30pm</p><p>Gripping drama and intrigue that will have you thinking about things differently.</p><p>Martin McDonagh echoes the works of Stoppard, Kafka, and the Brothers Grimm in this New York Drama Critics\' Circle and Olivier Award winning script. The Pillowman is a viciously funny and seriously disturbing tale of Katurian, a fiction writer in an unnamed totalitarian state. Katurian and his brother Michael are brought in for questioning by two bulldog detectives, Tupolski and Ariel, when the content of his short stories  — which involve disturbingly gruesome tales — begin to resemble real-life murders. The Pillowman weaves between reality and storytelling; and the result is an urgent work of theatrical bravura and an unflinching examination of the very nature and purpose of art. </p><p>Featuring:<br/><a href="https://www.facebook.com/ticeblade">Jacob Tice</a> as Katurian<br/><a href="https://www.facebook.com/andrew.fry.547">Andrew Fry</a> as Tupolski<br/><a href="https://www.facebook.com/christian.carvajal.585">Christian Carvajal</a> as Ariel<br/>Sean Neely as Michal<br/><a href="https://www.facebook.com/ellen.peters.509">Ellen Peters</a> as Mother<br/><a href="https://www.facebook.com/tim.takechi">Tim Takechi</a> as Father<br/>Alexandria <a href="https://www.facebook.com/christine.c.bray">Bray</a> as Child<br/>Nathaniel Walker as Man</p><p><a href="/s/1718-The-Pillowman-Program.pdf">Program</a></p><h2><strong><em>Please be advised that this show contains:<br/>Severe and Harsh Language, Mature Content, Simulated Violence, Blood on Stage, and Live Gunfire</em></strong></h2>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/6-the-pillowman-poster-3.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://michaeldresdner.blogspot.com/2018/04/the-pillowman-at-tlt.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://www.dramainthehood.net/2018/04/pillowman-brilliant-and-not-for-the-faint-of-heart-at-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="https://tacomaweekly.com/city-life/tlts-the-pillowman-takes-audiences-on-a-fun-and-wild-ride/">The Tacoma Weekly</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/04/The-Pillowman/">The Weekly Volcano</a><br/><a href="http://www.thenewstribune.com/entertainment/article209628499.html">The News Tribune</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Pillowman', 'Directed by Blake R. York  April 20th - May 6th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, May 3rd at 7:30pm  Gripping drama and intrigue that will have you thinking about things differently.  Martin McDonagh echoes the works of Stoppard, Kafka, and the Brot', 'publish', 'closed', 'closed', '', 'pillowman', '', '', '2026-05-09 16:14:29', '2026-05-09 16:14:29', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1111', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1112, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-59811365d482e9d2f73890aa"><div><div><div><div>\n<div>\n<p>Directed by pug Bujeaud<br/><br/>June 1st - June 17th, 2018<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm<br/><br/>Pay What You Can: Thursday, June 14th at 7:30pm</p><p>Start your summer with Shakespeare and one of his best!</p><p>Macbeth is a brave and loyal Thane to King Duncan. After hearing a prophecy that he will become king himself, Macbeth is overcome by ambition and greed. Bolstered by the prophecy and his wife’s encouragement, he kills King Duncan and takes the throne. Afterwards, Macbeth’s guilt, fear, and paranoia lead him to commit even more murders to secure his power. His confidence in the prophecies eventually leads to his downfall and he is overthrown and killed by those he has wronged. <br/><br/>Starring:<br/>Jess Allan as Gentlewoman<br/>Nicholas Anderson as Seyton<br/>Rodman Bolek as Macduff<br/><a href="https://www.facebook.com/ethan.bujeaud?fref=mentions">Ethan Bujeaud</a> as Witch/Siward<br/><a href="https://www.facebook.com/jonathan.hart.754?fref=mentions">Jonathan Hart</a> as Porter/2nd Murderer<br/><a href="https://www.facebook.com/adrianna.littlejohn.3?fref=mentions">Adrianna Littlejohn</a> as Lady Macduff<br/>Corbin McLaughlin as 1st Murderer/Whey Faced Lion<br/><a href="https://www.facebook.com/kathryn.philbrook?fref=mentions">Kathryn Grace Philbrook</a> as Lady Macbeth<br/><a href="https://www.facebook.com/maddoxpratt?fref=mentions">Maddox Pratt</a> as Ross<br/><a href="https://www.facebook.com/kaylie.rainer?fref=mentions">Kaylie Hussey</a> as Witch (Mother)<br/><a href="https://www.facebook.com/laurice.roberts?fref=mentions">Laurice Roberts</a> as Hecate/Doctor<br/><a href="https://www.facebook.com/ben.stahl1?fref=mentions">Ben</a> Stahl as Lennox<br/><a href="https://www.facebook.com/ticeblade?fref=mentions">Jacob Tice</a> as Malcolm<br/><a href="https://www.facebook.com/dylan.twiner?fref=mentions">Dylan Twiner</a> as Macbeth<br/><a href="https://www.facebook.com/JLRVC?fref=mentions">Jackie VC</a> as Witch<br/>Jessica Weaver as Banquo<br/>Dennis Worrell as Duncan<br/>Sean Raybell as Angus<br/>Simon Bonsteel as Fleance<br/>Caleb Corpeno as Son of Macduff<br/><a href="https://www.facebook.com/profile.php?id=100009407800232&amp;fref=mentions">Kyle Yoder</a> as Donalbain</p><p><a href="/s/1718-Macbeth.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/6-the-pillowman-poster-4.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="https://michaeldresdner.blogspot.com/2018/06/macbeth-at-tlt.html">Dresdner\'s Theatre Reviews</a><br/><a href="https://thesubtimes.com/2018/06/03/macbeth-at-tacoma-little-theatre-review/">The Suburban Times</a>-Doman<br/><a href="http://www.dramainthehood.net/2018/06/macbeth-tacoma-little-theatre/">Drama in the Hood</a><br/><a href="http://www.weeklyvolcano.com/stage-and-visual-reviews/2018/06/Macbeth/">The Weekly Volcano</a><br/><a href="https://tacomaweekly.com/city-life/tlts-macbeth-explores-the-psychology-of-a-tyrant/">The Tacoma Weekly</a><br/><a href="https://thesubtimes.com/2018/06/06/tlt-brings-bards-scottish-play-to-the-stage/">The Suburban Times-Geyer</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Macbeth', 'Directed by pug Bujeaud  June 1st - June 17th, 2018 Fridays and Saturdays at 7:30pm Sundays at 2:00pm  Pay What You Can: Thursday, June 14th at 7:30pm  Start your summer with Shakespeare and one of his best!  Macbeth is a brave and loyal Thane to King Duncan. After hearing a prophecy that he will be', 'publish', 'closed', 'closed', '', 'macbeth', '', '', '2026-05-09 16:14:29', '2026-05-09 16:14:29', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1112', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1113, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '\n<div class="body entry-content"><div id="item-581e432b8419c273288cdc05"><div><div><div><div>\n<div>\n<p>Tacoma Little Theatre has limited parking available for Season Ticket Holders and Donors.  For more information about this parking agreement, please contact the Box Office. </p><p>For general parking, we recommend that you arrive 30 minutes before curtain to find parking. Yakima Avenue, 2nd, I, and J streets are popular choices.  </p><p>For ADA parking, we have one spot in front of the building on I Street.  If you contact us in advance, we can also hold a spot in the 7-11 parking lot for you.</p><p>Please note: The 7-11 parking lot has THREE marked spots for TLT patrons.  Do not park in any other 7-11 parking spot.  Also, do not park in any of the private apartment lots.  They will tow your vehicle.</p>\n</div>\n</div></div></div></div></div></div>\n', 'Parking', 'Tacoma Little Theatre has limited parking available for Season Ticket Holders and Donors.&nbsp; For more information about this parking agreement, please contact the Box Office.   For general parking, we recommend that you arrive 30 minutes before curtain to find parking. Yakima Avenue, 2nd, I,', 'publish', 'closed', 'closed', '', 'parking', '', '', '2026-05-09 16:14:29', '2026-05-09 16:14:29', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1113', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1114, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-57b3e1b846c3c4245bbcf029"><div><div><div><div>\n<div>\n<p>Directed by Jennifer York</p><p>September 16 - October 2nd<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>From the hilarious mind of Steve Martin.</p><p>The renowned comic actor and author of Picasso at the Lapine Agile provides a wild satire adapted from the classic German play about Louise and Theo Maske, a couple whose conservative existence is shattered when Louise\'s bloomers fall down in public. Though she pulls them up quickly, he thinks the incident will cost him his job as a government clerk. Louise\'s momentary display does not result in the feared scandal but it does attract two infatuated men, each of whom wants to rent the spare room in the Markes\' home. Oblivious of their amorous objectives, Theo splits the room between them, happy to collect rent from both the foppish poet and the whiny hypochondriac.</p><p>Featuring:<br/>Jed Slaughter as Theo Maske<br/>Cassie Jo Fastabend as Louise Maske<br/>Deya Ozburn as Gertrude<br/>Ben Stahl as Versati<br/>Andrew Fry as Cohen<br/>Dale Bowers as Klinglehoff<br/>Bob Lozier as The Distinguished Caller</p><p><a href="/s/1617-Underpants-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3750" sizes="(max-width: 640px) 100vw, (max-width: 767px) 33.33333333333333vw, 33.33333333333333vw" src="/wp-content/uploads/migrated/image-asset-42.jpg" width="2500"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div>\n<h2>Reviews</h2><p><a href="http://www.northwestmilitary.com/music-and-culture/stage-and-visual-reviews/2016/09/the-underpants/" target="_blank">NorthwestMilitary.com</a></p><p><a href="http://michaeldresdner.blogspot.com/2016/09/the-underpants-at-tlt.html" target="_blank">Dresdner\'s Theatre Reviews</a></p><p><a href="http://www.axs.com/tacoma-little-theatre-hits-blooming-home-run-with-the-underpants-106793">axs.com</a></p><p><a href="http://www.thenewstribune.com/entertainment/arts-culture/article103281752.html">Tacoma News Tribune</a></p><p><a href="http://thesubtimes.com/2016/09/21/laugh-it-up-tlts-underpants-are-showing/">The Sub Times</a></p><p><a href="http://www.tacomaweekly.com/citylife/article/bloomers-and-rumors-abound-in-the-underpants">The Tacoma Weekly</a></p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Underpants', 'Directed by Jennifer York  September 16 - October 2nd Fridays and Saturdays at 7:30pm Sundays at 2:00pm  From the hilarious mind of Steve Martin.  The renowned comic actor and author of Picasso at the Lapine Agile provides a wild satire adapted from the classic German play about Louise and Theo Mask', 'publish', 'closed', 'closed', '', 'underpants', '', '', '2026-05-09 16:14:29', '2026-05-09 16:14:29', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1114', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1115, 1, '2026-05-09 16:14:29', '2026-05-09 16:14:29', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-57b3e415c534a5fd32f1a888"><div><div><div><div><div><div>\n<div>\n<p>October 21st - November 6th<br/>Fridays and Saturdays at 7:30pm<br/>Sundays at 2:00pm</p><p>Bram Stoker’s classic novel comes to life just in time for Halloween<br/> <br/>"I want your fear. For your fear, like a current, rushes through your body. Your fear makes your heart pound, it renders your veins rich and full. Your fear hemorrhages deliciously within you." This new adaptation restores the suspense and seduction of Bram Stoker\'s classic novel to the stage. As Count Dracula begins to exert his will upon the residents of London, they try to piece together the clues of his appearances—in a valiant attempt to save themselves from a hideous fate. Rich with both humor and horror, this play paints a wickedly theatrical picture of Stoker\'s famous vampire.</p><p>Featuring:<br/>Michael Christopher (Dracula)<br/>Joseph Grant (Van Helsing),<br/>Christopher Rocco (Seward)<br/>Jacob Tice (Harker)<br/>Jesse Morrow (Mina)<br/>Brynn Garrett (Lucy)<br/>Brian Wayne Jansen (Renfield)<br/>Jess Allan (Ensemble)<br/>Kadi Burt (Vixen)<br/>Ariel Birks (Vixen)<br/>Ethan Bujeaud (Ensemble)<br/>Gerardo Zaragoza (Man)</p><p><a href="/s/1617-Dracula-Program.pdf">Program</a></p>\n</div>\n</div></div><div class="gallery-block"><div>\n<div class="block-animation-none clear">\n<div>\n<div class="slide content-fill">\n<noscript><img alt="TLTDrac1.jpg" src="/wp-content/uploads/migrated/tltdrac1-2