INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1145, 1, '2026-05-09 16:14:31', '2026-05-09 16:14:31', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-64add58aeac40d330d93b819"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/thomas-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Thomas Robinson', '', 'publish', 'closed', 'closed', '', 'current-shop-technician', '', '', '2026-05-09 16:14:31', '2026-05-09 16:14:31', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1145', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1146, 1, '2026-05-09 16:14:31', '2026-05-09 16:14:31', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-555418a6e4b0d44531ecd6a2"><div><div><div><div>\n<div>\n<p>March 14 through 30, 2014</p><p>Writer George Schneider, a recent widower, is encour- aged by his younger brother Leo to start dating again. But this sends George into even more of a depression after a series of bad matches. Then Leo comes up with Jennie Malone and she’s a keep-<br/>er. Still, it’s a bumpy trip on the road to Dreamland for these not-so-young lovers. But George and Jennie stumble on, overcoming both their hesitation on the rebound and emotional neediness. </p><p><a href="/s/1314-Chapter-Two-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<button class="lightbox">\n<span class="v6-visually-hidden">View fullsize</span>\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3864" sizes="(max-width: 640px) 100vw, (max-width: 767px) 25vw, 25vw" src="/wp-content/uploads/migrated/image-asset-9.jpg" width="2500"/>\n</div>\n</div>\n</button>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Chapter two', 'March 14 through 30, 2014  Writer George Schneider, a recent widower, is encour- aged by his younger brother Leo to start dating again. But this sends George into even more of a depression after a series of bad matches. Then Leo comes up with Jennie Malone and she’s a keep- er. Still, it’s a bumpy t', 'publish', 'closed', 'closed', '', 'chapter-two', '', '', '2026-05-09 16:14:31', '2026-05-09 16:14:31', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1146', 0, 'tlt_show', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1147, 1, '2026-05-09 16:14:31', '2026-05-09 16:14:31', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-5554199be4b0df117521534f"><div><div><div><div>\n<div>\n<p>January 24 through February 9, 2014</p><p>Wide-eyed Scout is fascinat- ed with the people of her small town but, from the start, there’s a rumble of thunder just under the calm surface. When Scout’s father, the humble and respected lawyer Atticus Finch, defends a black man against shocking accu- sations by a white family, the town takes sides, and Scout learns about the contradic- tions of prosperity and dire poverty, celebrated freedom and rank injustice, love and hate. This dramatization of </p><p>the touching classic tale is a meaningful work of art. </p><p><a href="/s/1314-Mockingbird-Program.pdf">Program</a></p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<button class="lightbox">\n<span class="v6-visually-hidden">View fullsize</span>\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3864" sizes="(max-width: 640px) 100vw, (max-width: 767px) 25vw, 25vw" src="/wp-content/uploads/migrated/image-asset-11.jpg" width="2500"/>\n</div>\n</div>\n</button>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'To kill a mockingbird', 'January 24 through February 9, 2014  Wide-eyed Scout is fascinat- ed with the people of her small town but, from the start, there’s a rumble of thunder just under the calm surface. When Scout’s father, the humble and respected lawyer Atticus Finch, defends a black man against shocking accu- sations', 'publish', 'closed', 'closed', '', 'to-kill-a-mockingbird', '', '', '2026-05-09 16:14:31', '2026-05-09 16:14:31', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1147', 0, 'tlt_show', '', 0);
