INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1152, 1, '2026-05-09 16:14:31', '2026-05-09 16:14:31', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-62be1a2756273238ab9ded29"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="3300" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/emma-2.jpg" width="2550"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Emma DeLoye', '', 'publish', 'closed', 'closed', '', 'current-box-office-lead', '', '', '2026-05-09 16:14:31', '2026-05-09 16:14:31', '', 0, 'https://example.local/?post_type=tlt_show&amp;p=1152', 0, 'tlt_team', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1153, 1, '2026-05-09 16:14:31', '2026-05-09 16:14:31', '\n<div class="body entry-content"><div id="item-631286b109db2e13c97d98e8"><div><div><p class="button-row"><a href="https://forms.gle/GSvxnkz3J9ubGuov5" target="_blank">\n      Apply Now\n    </a></p><div><div>\n<div>\n<p><br/></p><p>Tacoma Little Theatre works hard to make our programs accessible for our community. Our camps and classes are priced based on the true cost to run the program and pay our staff for their time and energy. We recognize that, although we cannot lower the cost of participation, finances can create a barrier to participation in our programs. In response to that knowledge, we have, through intentional budgeting, grants, and the contributions of generous donors, built an ongoing scholarship fund. Anyone is welcome to apply to receive financial support for any of our education programs through this scholarship fund. </p><p>Scholarships are awarded based on need, as well as our available resources. Applications are processed in order of receipt. It can take 5-8 business days to process, but you should hear back from us with confirmation of what scholarship amount we can approve. We are unable to approve full scholarships. TLT is dedicated to honoring each request and making sure that every adult and child who wants to experience theatre art can do so through our programs. </p><p>We won’t ask you for anything in exchange for the scholarship. We may send an optional survey at some point in the year following your participation to seek some feedback, and possibly testimonials that can help us secure grants for future programs.</p><p>We do ask that, whether your student is participating through a scholarship or not, they attend each class or rehearsal, come on time, and participate fully in the process.  Every cast member is a vital part of the experience. </p><p>If you have questions about our programs, or your scholarship application, please email education@tacomalittletheatre.com. Please also consider signing up for our ‘youth theatre’ email list to be notified of upcoming opportunities at the theatre! </p><p><br/>Thanks for considering joining us at TLT, and we look forward to seeing you at the theatre! </p>\n</div>\n</div></div></div></div></div></div>\n', 'Is there actually a link that people can use for scholarships, or is this it?', '', 'publish', 'closed', 'closed', '', 'is-there-actually-a-link-that-people-can-use-for-scholarships-or-is-this-it', '', '', '2026-05-09 16:14:31', '2026-05-09 16:14:31', '', 0, 'https://example.local/?post_type=post&amp;p=1153', 0, 'post', '', 0);
