INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1260, 1, '2026-05-09 18:34:28', '2026-05-09 18:34:28', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69deb6033cc29c77daaac78c"><div><div><div><div>\n<div>\n<h2>NEW LOCATION!<br/><br/>Presented at:<br/>LA QUINTA INN<br/>1425 E 27th Street<br/>Tacoma, WA 98421</h2><h2>Tickets: $80.00 <br/>includes dinner and show</h2>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/200528982" target="_blank">\n      CLICK HERE FOR TICKETS\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<p>Tacoma Little Theatre ends its Murder Mystery Dinner Season with, <em>THE GOLDEN BALL MURDER, </em>by Andrew Fry and directed by Micheal O’Hara. </p><p><em>THE GOLDEN BALL MURDER </em>is a fast-paced, comedic whodunit set at a high-stakes auction for a mysterious golden bingo ball. When the prized item vanishes mid-event, eccentric bidders, tangled romances, and long-held rivalries collide as auctioneer-turned-detective Sheerluck Bidman takes on the case. Watch closely, trust no one, and be ready—because by the final reveal, you might just solve the mystery… or become part of it.<br/><br/>Featuring;<br/>Andrew Fry as Jimmy Vegas<br/>Heidi Walworth-Horn as Lady Dauber<br/>Mickie Milton as Pamela Dauber<br/>Chad Russell as Benjamin Cage<br/>Stacia Russell as N. Deanna Jones<br/>Kerry Bringman as Sheerluck Bidman<br/>Aleks Aurelion as Justin Case<br/>Micheal O’Hara as The Wedding Planner<br/></p><h2><strong>Dinner includes:</strong></h2><p><strong>-APPETIZER BUFFET-</strong><br/>Assorted meats, cheeses, vegetables, and crackers<br/>Bruschetta with diced tomatoes, basil, onion, garlic, balsamic, and olive oil</p><p><strong>-PLATED SALAD-</strong><br/>Assorted greens, candied walnuts, dried cranberries, and bleu cheese with a balsamic vinaigrette (on the side).</p><p><strong>-YOUR CHOICE OF MAIN ENTREE-</strong><br/>CHICKEN <br/>Chicken Cordon Bleu-Breaded chicken breast filled with ham and swiss cheese, and topped with hollandaise sauce.  Served with Rice Pilaf, Vegetable Medley, rolls, and butter.<br/><strong><em>-OR-</em></strong><br/>VEGETARIAN<br/>Vegetarian Stir Fry- White rice, assorted vegetables with a teriyaki glaze and topped with sesame seeds<br/>(Lactose free and gluten free options are available)</p><p><strong>-DESSERT-<br/></strong>Cheesecake topped with strawberries<br/><br/>Coffee, Tea, and Water are included. Other beverages including alcohol are available for purchase at the bar.</p><p>Tickets are $80.00 per person (includes dinner, gratuity, and show)</p><p>Come hungry for a meal and a mystery — and remember, in this show, everyone’s a suspect until the final reveal!</p>\n</div>\n</div></div></div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="5400" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/tlt-the-golden-ball-murder.jpg" width="3600"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="4284" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/img-4795.jpg" width="5712"/>\n</div>\n</div>\n<figcaption class="image-caption-wrapper">\n<div class="image-caption"><p>A photo from our October 2024 dinner!</p></div>\n</figcaption>\n</figure>\n</div>\n</div></div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="299" sizes="(max-width: 640px) 100vw, (max-width: 767px) 50vw, 50vw" src="/wp-content/uploads/migrated/la-quinta-logo.jpg" width="372"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'The Golden Ball Murder — A Murder Mystery Dinner', 'NEW LOCATION! Join us for a fun-filled Murder Mystery Dinner! May 28-31, 2026 at La Quinta Inn.', 'publish', 'closed', 'closed', '', 'golden-ball-murder', '', '', '2026-05-09 18:34:28', '2026-05-09 18:34:28', '', 0, 'http://tlt.local/?p=golden-ball-murder', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1261, 1, '2026-05-09 18:35:58', '2026-05-09 18:35:58', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69e126fb83eff920f061e4d6"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1999" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/2026-spring-class-announcement.png" width="1545"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69e126fb83eff920f061e4d6"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/index.php?sections=classes" target="_blank">\n      CLICK HERE TO REGISTER\n    </a>\n</div>\n\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Spring Education @ TLT', 'Three great programs for students in grades 1-8!', 'publish', 'closed', 'closed', '', 'spring-classes-2026', '', '', '2026-05-09 18:35:58', '2026-05-09 18:35:58', '', 0, 'http://tlt.local/?p=spring-classes-2026', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1262, 1, '2026-05-09 18:36:38', '2026-05-09 18:36:38', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69dd6d9aada7b32eb255f44d"><div><div><div><div>\n<div class="layout-caption-below design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1350" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/2026-summer-camp-announcement.png" width="1080"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69dd6d9aada7b32eb255f44d"><div><div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://tlt.ludus.com/index.php?sections=classes" target="_blank">\n      CLICK HERE TO ENROLL\n    </a>\n</div>\n\n</div></div><div><div>\n<div>\n<h2><em>SESSION 1: Oliver jr.<br/></em>(Entering 1st grade through 6th grade)</h2><p>June 22 - July 18. Monday - Friday from 9 AM - 4 PM. <br/>Performances July 17 at 7:00 PM and July 19 at 2:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p><strong>About the Show:</strong></p><p>Consider yourself at home with <em>Oliver! JR., </em>the Broadway Junior version of Lionel Bart\'s classic musical based on Charles Dickens\' novel, <em>Oliver Twist</em>. The Tony and Olivier Award-winning show is one of the few musicals to win an Academy Award for Best Picture and is widely hailed as a true theatrical masterpiece by actors and audience members alike.</p><p>The streets of Victorian England come to life as Oliver, a malnourished orphan in a workhouse, becomes the neglected apprentice of an undertaker. Oliver escapes to London and finds acceptance amongst a group of petty thieves and pickpockets led by the elderly Fagin. When Oliver is captured for a theft that he did not commit, the benevolent victim, Mr. Brownlow takes him in. Fearing the safety of his hideout, Fagin employs the sinister Bill Sikes and the sympathetic Nancy to kidnap him back, threatening Oliver’s chances of discovering the true love of a family.</p><p><em>Oliver! JR. </em>is full of classic songs like "Consider Yourself", "Food Glorious Food", and "Oom-Pah-Pah", and perfectly showcases the talents of a large ensemble cast.<br/><br/></p><h2><em>Session 1: High School musical, jr.<br/></em>(Entering 7th grade through graduating senior)</h2><p>June 22 - July 18. Monday - Friday from 9 AM - 4 PM. <br/>Performances July 18 at 11:00 AM and at 5:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p> <strong>About the Show:</strong></p><p>Disney Channel\'s smash hit movie musical comes to life on your stage in <em>Disney’s High School Musical JR. </em>Now updated to the convenient binder version! Troy, Gabriella and the students of East High must deal with issues of love, friends and family while balancing their classes and extra curricular activities. The show’s infectious, danceable songs are sure to engage performers and audiences alike.</p><p>It’s the first day after winter break at East High. The Jocks, Brainiacs, Thespians and Skater Dudes all find their cliques. Basketball team captain and resident jock, Troy, discovers that the brainy Gabriella, a girl he met singing karaoke on his ski trip, has just enrolled at East High. The couple cause an upheaval when they decide to audition for the high school musical. Although many students resent the threat posed to the "status quo," Troy and Gabriella’s alliance might just open the door for others to shine as well.</p><p><em>Disney’s High School Musical JR. </em>is a great way to involve your school’s student-athletes. The show’s large cast size can easily be expanded to accommodate students in many grade levels, and its modern-day school setting, scenery and costumes are easily accessible.</p><h2><em>Session 2: TITLE TO BE ANNOUNCED<br/></em>(Entering 1st grade through 6th grade.)</h2><p>July 20 - August 15. Monday - Friday from 9 AM - 4 PM. <br/>Performances August 14 at 7:00 PM and August 15 at 2:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p> <strong>About the Show:</strong></p><p>This is a fun show that we are waiting on the official rights for.  It will be a show full of singing and dancing that you will love!<br/><br/></p><h2><em>SESSION 2: XANADU, Jr.</em> <br/>(Entering 7th grade through graduating senior)</h2><p>July 20 - August 15. Monday - Friday from 9 AM - 4 PM. <br/>Performances August 15 at 11:00 AM and  5:00 PM<br/>Cost: $625<br/>Location: Hilltop Heritage Middle School<br/>602 N Sprague Ave<br/>Tacoma, WA 98403</p><p><strong>About the Show:</strong></p><p><em>Xanadu JR.</em> is inspired by the Tony Award-nominated Broadway musical and the Universal Pictures\' cult classic movie that starred Olivia Newton-John and Gene Kelly. <em>Xanadu JR.</em> is a moving, electrifying tale of endless fun that will keep audiences in stitches while the original, legendary chart-topping tunes lift them out of their seats.</p><p><em>Xanadu JR.</em> follows the journey of a magical and beautiful Greek muse, Kira, who descends from the heavens of Mt. Olympus to Venice Beach, California, on a quest to inspire a struggling artist, Sonny, to achieve the greatest artistic creation of all time – the first Roller Disco. (Hey, it\'s 1980!) But, when Kira falls into forbidden love with the mortal Sonny, her jealous sisters take advantage of the situation, and chaos abounds.</p><p>With a flexible cast size and lots of room for large disco dance numbers, <em>Xanadu JR.</em> will have your students rolling along (no skates required!)<br/></p><h2><strong>Scholarships:</strong></h2><p>Some scholarship funding is available. <a href="https://docs.google.com/forms/d/e/1FAIpQLSdEwJCTMI4GGxAXoBhfZhi1GrNk0DP5pFTkFFJd1qKc8TciDA/viewform?usp=header" target="_blank"><span>Click here to be directed to the application.</span></a><span> </span>Apply now, so we can process your application before enrollment opens!</p><p>*Note:  Please apply for a scholarship <strong>BEFORE</strong> trying to enroll your student.  Once approved, your scholarship will hold your students spot in the camp. </p>\n</div>\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'Summer Camp @ TLT', 'Summer Camp is enrolling now!', 'publish', 'closed', 'closed', '', 'summer-camp-2026', '', '', '2026-05-09 18:36:38', '2026-05-09 18:36:38', '', 0, 'http://tlt.local/?p=summer-camp-2026', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1263, 1, '2026-05-09 18:42:53', '2026-05-09 18:42:53', '<!--SPECIAL CONTENT-->\n<div class="special-content"><div id="promoted-block-69fa4c25fd533f4af513b70a"><div><div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="1080" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/orange-and-peach-simple-now-hiring-announcement-instagram-post.png" width="1080"/>\n</div>\n</div>\n</figure>\n</div>\n</div></div></div></div></div></div>\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-69fa4c25fd533f4af513b70a"><div><div><div><div>\n<div>\n<p>Tacoma Little Theatre is seeking designers for our 2026-2027 season. </p><p>We are seeking collaborative designers with a passion for the arts and their craft. The following design positions are available:</p><ul><li><p>Stage Managers</p></li><li><p>Resident Properties Designer</p></li><li><p>Resident Sound Designer</p></li><li><p>Show Costume Designer</p></li><li><p>Scenic Artist Apprentice</p></li></ul><p>At TLT, we believe theatre is a space for connection, reflection, and community storytelling. We are committed to producing work that is artistically bold, inclusive, and reflective of the diverse voices that make up our region. We strongly encourage designers of all backgrounds, identities, and experience levels to apply. </p><h2><span><strong>PRODUCTIONS</strong></span></h2><p><strong>THE OUTSIDER<br/>BY PAUL SLADE SMITH<br/>August 28-September 13, 2026</strong><br/>Ned Newley doesn’t even want to be governor. He’s terrified of public speaking, and his poll numbers are impressively bad. To his ever-supportive Chief of Staff, Ned seems destined to fail. But political consultant Arthur Vance sees things differently: Ned might be the worst candidate to ever run for office. Unless the public is looking for the worst candidate to ever run for office.  A timely and hilarious comedy that skewers politics and celebrates democracy.</p><p><strong>ARSENIC AND OLD LACE<br/>BY JOSEPH KESSERLING<br/>October 16-November 1, 2026</strong><br/>Drama critic Mortimer Brewster’s engagement announcement is upended when he discovers a corpse in his elderly aunts’ window seat. Mortimer rushes to tell Abby and Martha before they stumble upon the body themselves, only to learn that the two women aren’t just aware of the dead man in their parlor, they killed him! Between his aunts’ penchant for poisoning wine, a brother who thinks he’s Teddy Roosevelt, and another brother using plastic surgery to hide from the police – not to mention Mortimer’s own hesitancy about marriage – it’ll be a miracle if Mortimer makes it to his wedding. </p><p><strong>HALLMARKED<br/>BY MICHAEL D. FOX<br/>December 4-27, 2026</strong><br/>It seems everyone on the planet is obsessed with Hallmark movies. Everyone except Julie. She had her heart stomped on once and it will not happen again. No way. No how. Not even in Idyllic, Vermont. She refuses to be \'Hallmarked\'! Oh, no! Who\'s the guy in the plaid flannel? Packed with fabulous new pop songs, loads of laughter, and heartwarming delight, Hallmarked is a rom-com fever dream for those who swoon over the movies and for those who love roasting the people who do.</p><p><strong>DOT<br/>BY COLMAN DOMINGO<br/>February 5-21, 2027</strong><br/>The holidays are always a wild family affair at the Shealy house: But this year, Dotty and her three grown children gather with more than exchanging presents on their minds. As Dotty struggles to hold on to her memory, her children must fight to balance care for their mother and care for themselves. This twisted and hilarious new play grapples unflinchingly with aging parents, midlife crises, and the heart of a West Philly neighborhood.</p><p><strong>URINETOWN<br/>BY GREG KOTIS<br/>March 26-April 18, 2027</strong><br/>In this side-splitting satire, the young hero Bobby Strong leads his community in a fight against oppression. Set in a dystopian world where water is scarce and “Hope” is even scarcer, all citizens must now pay a fee for “The Privilege to Pee” at one of the public facilities controlled by a selfish tycoon, and monitored by authorities like Officer Lockstock. The citizens can only hold it in so much longer, and soon the poorest, filthiest of these facilities, run by the formidable Penelope Pennywise, becomes a “number one” site for major change.</p><p><strong>THE IMPORTANCE OF BEING EARNEST (UWT Partner Project)<br/>BY OSCAR WILDE<br/>May 21-June 6, 2027</strong></p><p>Being sensible can be excessively boring. At least Jack thinks so. While assuming the role of dutiful guardian in the country, he lets loose in town under a false identity. Meanwhile, his friend Algernon takes on a similar facade. Unfortunately, living a double life has its drawbacks, especially when it comes to love. Hoping to impress two eligible ladies, the gentlemen find themselves caught in a web of lies they must carefully navigate.</p><p><strong>THE PLAY THAT GOES WRONG<br/>BY HENRY LEWIS, JONATHAN SAYER &amp; HENRY SHIELDS<br/>July 9-July 25, 2027</strong></p><p>Welcome to opening night of the Cornley University Drama Society’s newest production, The Murder at Haversham Manor, where things are quickly going from bad to utterly disastrous. This 1920s whodunit has everything you never wanted in a show—an unconscious leading lady, a corpse that can’t play dead, and actors who trip over everything (including their lines). Nevertheless, the accident-prone thespians battle against all odds to make it through to their final curtain call, with hilarious consequences! Part Monty Python, part Sherlock Holmes, this Olivier Award–winning comedy is a global phenomenon that’s guaranteed to leave you aching with laughter!</p><h2><span><strong>COMPENSATION</strong></span></h2><p>Honorariums range in amounts from $600.00-$1400.00 per show.</p><h2><span><strong>HOW TO APPLY</strong></span></h2><p>If you are interested, please submit a current resume, and a letter of interest with the show(s) you are applying for to <a href="mailto:jobs@tacomalittletheatre.com?subject=2026-2027%20Director%20Search" target="_blank">jobs@tacomalittletheatre.com</a> or click the button below. You may apply for more than one production in your email. Letters will be reviewed on a rolling basis and positions filled by May 31, 2026.</p>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="mailto:jobs@tacomalittletheatre.com?subject=2026-2027%20Director%20Search" target="_blank">\n      SUBMIT EMAIL\n    </a>\n</div>\n\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'NOW HIRING-PRODUCTION TEAM MEMBERS FOR 2026-2027', 'TLT is currently accepting applications for production team members for 2026-2027!', 'publish', 'closed', 'closed', '', 'now-hiring-2026-27', '', '', '2026-05-09 18:42:53', '2026-05-09 18:42:53', '', 0, 'http://tlt.local/?p=now-hiring-2026-27', 0, 'post', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES (1264, 1, '2026-05-09 18:43:01', '2026-05-09 18:43:01', '<!--SPECIAL CONTENT-->\n<!--POST HEADER-->\n\n<!--POST BODY-->\n<div class="body entry-content"><div id="item-680981a194649a1f781713a4"><div><div><div><div>\n<div>\n<p>Tacoma Little Theatre is excited to announce its partnership with <a href="https://www.facebook.com/HarborLightsTacoma?__cft__[0]=AZXcW4NYm2Vn3-zIk18RHGaZlV2zSc-ux4YaryhZQhXpH0J1ksms78jsKTdO4_5BGCMfF8FXStVxJG811JqXXOcTYE7SS-hr6LBIc9Kzu9jW0KlJ4Qh6OXtHVHUBz4zMhIWN7qRkGzEAWnYaUBIA24NlZgMzlgVQFv7JMSmwvbUkBlAtJoFkiT6Wmy13JHJKtu0lvcx6gJvCx3t8RqMusITw&amp;__tn__=-]K-R"><strong>Harbor Lights</strong></a> for our patrons.</p><p>ALL PATRONS</p><p>Enjoy access to the 3-Course Sunset Dinner menu any day of the week before or after a performance. Just show your ticket!</p><p>SEASON/FLEX PASS HOLDERS</p><p>Dinner deserves a standing ovation too. Your subscription includes one complimentary appetizer or dessert with every performance.</p>\n</div>\n</div></div><div><div>\n<div class="layout-caption-hidden design-layout-inline combination-animation-none individual-animation-none individual-text-animation-none">\n<figure class="intrinsic">\n<a href="https://www.anthonys.com/restaurant/harbor-lights/" target="_blank">\n<div>\n<div class="has-aspect-ratio">\n<img alt="" decoding="async" elementtiming="system-image-block" height="2550" sizes="(max-width: 640px) 100vw, (max-width: 767px) 100vw, 100vw" src="/wp-content/uploads/migrated/harbor-lights-program-insert-0126-2.jpg" width="1650"/>\n</div>\n</div>\n</a>\n</figure>\n</div>\n</div></div><div class="website-component-block button-block"><div>\n<div>\n<a href="https://www.anthonys.com/restaurant/harbor-lights/" target="_blank">\n      CLICK HERE TO MAKE A RESERVATION\n    </a>\n</div>\n\n</div></div></div></div></div></div>\n<!--POST FOOTER-->', 'GRAB DINNER AT HARBOR LIGHTS!', 'TLT AND HARBOR LIGHTS START A NEW PARTNERSHIP  Tacoma Little Theatre is excited to announce its partnership with   Harbor Lights   for our patrons.  ALL PATRONS  Enjoy access to the 3-Course Sunset Dinner menu any day of the week before or after a performance. Just show your ticket!  SEASON/FLEX PAS', 'publish', 'closed', 'closed', '', 'harbor-lights', '', '', '2026-05-09 18:43:01', '2026-05-09 18:43:01', '', 0, 'http://tlt.local/?p=harbor-lights', 0, 'post', '', 0);
